// Correcciones Simulia — tanda 3 — parte 4 de 8: fotos, protocolos, escalas y dudas (10 oct 2026)
// Pegar en mongosh (Compass) conectado a SimuLIA. Guarda copia de cada original antes de tocarlo.
const db2 = db.getSiblingDB('CSV');
const backup = db2.getCollection('backup_correcciones_2026_10_10_t3');
let ok=0, del=0, warn=0;
function fix(coll, filter, set) {
  const c = db2.getCollection(coll); const d = c.find(filter).toArray();
  if (d.length !== 1) { warn++; print('⚠️ ' + coll + ' ' + JSON.stringify(filter).slice(0,90) + ' -> ' + d.length); return; }
  backup.insertOne({ coll, original: d[0], savedAt: new Date() });
  c.updateOne({ _id: d[0]._id }, { $set: set }); ok++;
}
function rm(coll, filter) {
  const c = db2.getCollection(coll); const d = c.find(filter).toArray();
  if (d.length !== 1) { warn++; print('⚠️ ' + coll + ' ' + JSON.stringify(filter).slice(0,90) + ' -> ' + d.length); return; }
  backup.insertOne({ coll, original: d[0], deleted: true, savedAt: new Date() });
  c.deleteOne({ _id: d[0]._id }); del++;
}

fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977965") }, {"long_answer": "El plan fija como indicador que aumente, respecto a 2023, el número de convocatorias específicas dirigidas a profesionales jóvenes de Atención Primaria, con el fin de favorecer la incorporación de nuevas generaciones a la investigación y asegurar el relevo de los grupos. La participación de empresas farmacéuticas privadas no es el indicador fijado en esta acción. Publicar en revistas no especializadas no mejora la calidad ni la visibilidad de la investigación, y reducir el número de convocatorias nacionales iría en sentido contrario al objetivo de impulsar la investigación en Atención Primaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977967") }, {"long_answer": "Con la constitución de redes cooperativas de investigación en Atención Primaria financiadas por la Acción Estratégica en Salud, el plan espera disponer entre 2025 y 2027 de una red estatal liderada por profesionales de este nivel asistencial, que reúna a grupos de distintas comunidades autónomas y aumente la masa crítica y la calidad de la investigación. No se pretende crear un grupo exclusivamente internacional. Reducir la actividad investigadora fuera del hospital es lo contrario de lo que se busca, y limitar la investigación a una sola comunidad anularía el carácter estatal y cooperativo de la red."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97796f") }, {"long_answer": "La estrategia estatal de recursos humanos en Atención Primaria busca garantizar la accesibilidad, la longitudinalidad y la estabilidad de los equipos, atraer y retener talento y reducir la temporalidad, en línea con la agenda de la OMS sobre personal sanitario para 2030. Con ello se pretende que la población tenga profesionales de referencia estables. Aumentar la temporalidad para favorecer la rotación iría contra la longitudinalidad. Reducir el acceso a la formación especializada agravaría el déficit de especialistas, y centralizar la gestión en organismos internacionales es incompatible con las competencias de las comunidades autónomas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977976") }, {"long_answer": "Dentro de la línea de gobernanza, el plan establece que el conjunto de indicadores seleccionados para monitorizar el estado de la Atención Primaria y Comunitaria en el SNS se publique antes de fin de 2025. Disponer pronto de estos indicadores es necesario para evaluar después la evolución del propio plan y para construir el entorno público de presentación de resultados previsto para 2027. Las fechas de mitad de 2026 y fin de 2027 son posteriores al plazo fijado, y publicarlos después de 2027 dejaría al plan sin herramientas para su seguimiento durante su vigencia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97797e") }, {"long_answer": "Para avanzar en la profesionalización de la gestión en Atención Primaria, el plan prevé aprobar antes de 2026 un marco de evaluación común para los planes anuales de gestión de los centros de salud, de modo que los objetivos y resultados de cada centro puedan valorarse con criterios homogéneos. Un plan de formación solo para personal administrativo no responde a la profesionalización de la dirección de los centros. Eliminar los planes anuales de gestión o elaborar informes sin mecanismos de evaluación sería contrario a la rendición de cuentas que persigue el plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977982") }, {"long_answer": "En el impulso a la atención familiar en el hogar, el plan considera fundamental el papel de las enfermeras del equipo de Atención Primaria, que gestionan los protocolos de actuación basados en la evidencia y coordinan los cuidados en el domicilio, especialmente en personas con dependencia, cronicidad compleja o al final de la vida. La atención domiciliaria es una tarea del equipo, por lo que no recae solo en los médicos de familia. El personal administrativo apoya la organización, pero no gestiona la atención, y el personal externo contratado por las comunidades no forma parte del modelo planteado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977983") }, {"long_answer": "La estrategia de atención familiar en el hogar considera clave la coordinación con la atención hospitalaria y con los recursos de atención al final de la vida, como los equipos de cuidados paliativos, para garantizar la continuidad asistencial de los pacientes que reciben atención domiciliaria y evitar ingresos innecesarios. La comunicación limitada al interior del centro de salud no asegura esa continuidad. Incorporar exclusivamente voluntarios no profesionales no garantiza la calidad de los cuidados, y el uso único de plataformas digitales sin contacto presencial no es adecuado para pacientes que precisan atención en su domicilio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977990") }, {"long_answer": "Según la Estrategia, en las fases tempranas del desarrollo de medicamentos, como la investigación básica y preclínica, la financiación pública suele ser predominante, porque la inversión necesaria es menor y la incertidumbre sobre el éxito es mayor, lo que desincentiva la inversión privada. A medida que el proyecto avanza hacia las fases clínicas, aumenta el peso de la inversión privada. Por eso no es cierto que la financiación privada predomine al inicio por retornos garantizados. Las organizaciones filantrópicas participan, pero no financian exclusivamente estas fases, y sí existe financiación antes del desarrollo clínico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977994") }, {"long_answer": "El Comité Interministerial de Seguimiento de la Estrategia tiene como función principal la coordinación entre los distintos ministerios implicados y el seguimiento de la Estrategia y de las acciones que se derivan de ella, garantizando su ejecución coherente. No negocia directamente los precios de los medicamentos con la industria, función que corresponde a la Comisión Interministerial de Precios de los Medicamentos. Tampoco gestiona inversiones privadas en biotecnología ni se limita a supervisar rondas de financiación internacional, ya que su papel es de coordinación y seguimiento global."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977996") }, {"long_answer": "El Comité Mixto Ministerios-Industria se caracteriza por incluir representantes de los ministerios implicados en la Estrategia y representantes de la industria farmacéutica, de modo que el diálogo entre la Administración y el sector se produce de forma estable dentro de la gobernanza. Este enfoque permite consensuar medidas y hacer seguimiento conjunto. No está formado únicamente por miembros del Ministerio de Sanidad, ya que participan otros ministerios y la industria. Tampoco se compone solo de asociaciones de pacientes y profesionales ni exclusivamente de expertos académicos independientes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97799b") }, {"long_answer": "La Estrategia entiende por reposicionamiento terapéutico el uso de medicamentos ya existentes para nuevas indicaciones distintas de aquellas para las que se autorizaron. Como su seguridad y farmacología ya son conocidas, el desarrollo es más rápido y barato, lo que acelera el acceso a tratamientos eficaces y reduce costes. No consiste en reciclar principios activos para producir genéricos, que son copias de un medicamento con la misma indicación. Tampoco se limita a terapias avanzadas biotecnológicas, ni supone retirar medicamentos antiguos para dejar espacio a la innovación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97799d") }, {"long_answer": "La Estrategia considera la medicina personalizada de precisión una prioridad estratégica porque puede transformar la atención sanitaria al combinar datos genéticos, clínicos, ambientales y sociales para elegir tratamientos más eficaces y seguros para cada paciente, evitando terapias inútiles y efectos adversos. No tiene como fin reducir el coste de producción de los genéricos. Tampoco es una terapia estándar para enfermedades infecciosas emergentes, y no garantiza la igualdad de acceso sin evaluar las condiciones clínicas, ya que precisamente se basa en caracterizar a cada paciente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca97799e") }, {"long_answer": "En la estructura de gobernanza de la Estrategia, la secretaría del Comité Interministerial de Seguimiento corresponde a la persona titular de la Secretaría de Estado de Sanidad del Ministerio de Sanidad, que coordina el trabajo de los distintos ministerios implicados. El presidente de Farmaindustria representa a la industria y participa en los espacios de diálogo con el sector, pero no forma parte de la secretaría de un comité interministerial. El ministro de Hacienda no ostenta esta función, y un representante de la Comisión Europea no forma parte de la gobernanza nacional de la Estrategia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779a1") }, {"long_answer": "Para garantizar la eficiencia del gasto farmacéutico, la Estrategia plantea que su crecimiento no supere la tasa de referencia del crecimiento del PIB prevista para la economía española, de forma que el gasto evolucione en consonancia con la capacidad económica del país. Incrementar el gasto por encima del PIB para acelerar la innovación comprometería la sostenibilidad del sistema. Asignar un presupuesto fijo independiente de la evolución económica no se corresponde con el mecanismo previsto, y reducir el gasto solo en medicamentos originales sin considerar los biosimilares no es una medida de la Estrategia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779a2") }, {"long_answer": "Que muchas innovaciones farmacéuticas se originen en instituciones académicas y pequeñas empresas biotecnológicas demuestra la creciente descentralización del desarrollo de medicamentos y la importancia de la colaboración público-privada. Las ideas suelen surgir en universidades, centros de investigación y startups, y después se desarrollan y comercializan con la participación de grandes compañías. Esto no limita la capacidad de las grandes empresas para comercializar innovaciones, sino que las complementa. Tampoco significa que el desarrollo se concentre en las grandes compañías, ni que la industria se dedique solo a la producción final."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779a6") }, {"long_answer": "Según la Estrategia, la resistencia a los antibióticos aumenta la morbilidad y la mortalidad por infecciones que se vuelven difíciles o imposibles de tratar, eleva los costes sanitarios por estancias más largas y tratamientos más caros y amenaza avances médicos como la cirugía o los trasplantes, que dependen de antibióticos eficaces. Por eso es un ámbito de alta necesidad que requiere incentivar el desarrollo de nuevos antimicrobianos. No disminuye la necesidad de investigación, sino que la aumenta. Tampoco reduce la carga económica, y no impide el desarrollo de terapias personalizadas y avanzadas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779a9") }, {"long_answer": "En el marco de la Estrategia, la participación de los distintos agentes y la colaboración intersectorial sirven para integrar políticas de diferentes ámbitos, como el sanitario, el industrial y el científico, y dar una respuesta ágil a las necesidades de salud prioritarias. Este enfoque se refleja en la Alianza para la Estrategia y en los órganos de gobernanza compartida. Limitar la participación a expertos académicos excluiría a pacientes, profesionales y sociedad civil. Reducir la transparencia o concentrar las decisiones solo en el Ministerio de Industria es contrario al modelo de gobernanza colaborativa planteado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779ae") }, {"long_answer": "El Informe Draghi sobre el futuro de la competitividad europea contiene referencias relevantes sobre la pérdida de competitividad de Europa frente a Estados Unidos y Asia, también en el sector farmacéutico y biotecnológico, y sus conclusiones influyen en la Estrategia española, que se alinea con la necesidad de reforzar la innovación y la autonomía estratégica. No es un documento exclusivo de salud pública sin relación con la competitividad industrial, ya que trata precisamente de competitividad. Su impacto no se limita al ámbito europeo, porque orienta las políticas nacionales, y sí se considera relevante para la formulación de la Estrategia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779b1") }, {"long_answer": "Que la Estrategia establezca un ecosistema farmacéutico integrado significa que la innovación, la producción, el acceso a los medicamentos y la sostenibilidad del sistema se abordan en un enfoque único y coordinado, reconociendo que cada uno de estos elementos influye en los demás. Separar la innovación, la producción y el acceso es justo lo contrario de la integración. Orientarse exclusivamente a la producción nacional sin considerar el acceso, o impulsar solo la producción para la exportación, dejaría fuera elementos esenciales del ecosistema."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779b3") }, {"long_answer": "Dentro del eje dedicado al acceso y la sostenibilidad, una de las líneas de acción clave de la Estrategia es mejorar el procedimiento actual de financiación de medicamentos y la evaluación de tecnologías sanitarias, haciéndolos más ágiles, transparentes y basados en el valor terapéutico y la eficiencia. Fortalecer el monopolio de los medicamentos innovadores no es un objetivo de la Estrategia. Reducir la evaluación de tecnologías sanitarias para acelerar los procesos comprometería la calidad de las decisiones, y eliminar los sistemas de información sobre consumo impediría tomar decisiones basadas en datos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779b4") }, {"long_answer": "Según la Estrategia, en su elaboración participó un grupo de trabajo interministerial formado por los Ministerios de Sanidad, Hacienda, Industria y Turismo, y Ciencia, Innovación y Universidades, junto con las principales patronales del sector farmacéutico, lo que refleja el enfoque colaborativo entre la Administración y la industria. Los Ministerios de Educación y Deportes no forman parte de este grupo. Farmaindustria y BioSim participaron como patronales, pero no elaboraron la Estrategia en solitario, y los Ministerios de Agricultura y Medio Ambiente tampoco integran el grupo interministerial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779bc") }, {"long_answer": "La Estrategia considera que la incorporación de biomarcadores y pruebas genéticas es clave para avanzar en la medicina personalizada de precisión, ya que permiten identificar qué pacientes se beneficiarán de un tratamiento, ajustar las dosis y prever efectos adversos. Por eso se busca integrarlos en la cartera de servicios y en la práctica clínica habitual. No se limitan a complementar la investigación sin impacto clínico. Reducir su uso para evitar costes desaprovecharía su potencial para hacer los tratamientos más eficientes, y restringirlos a la investigación básica impediría su aplicación terapéutica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779bd") }, {"question": "Según la Estrategia de la Industria Farmacéutica, ¿a cuánto ascendió aproximadamente el gasto farmacéutico en España en 2023?", "long_answer": "Según los datos recogidos en la Estrategia de la Industria Farmacéutica, el gasto farmacéutico en España en 2023 ascendió aproximadamente a 29,69 miles de millones de euros. Este volumen, en crecimiento sostenido, explica la importancia de vincular su evolución a una tasa de referencia ligada al PIB para garantizar la sostenibilidad del sistema. Las cifras de 5 y 10 miles de millones infravaloran claramente el gasto real, y la de 50 miles de millones lo sobrestima."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779cc") }, {"long_answer": "La Estrategia considera que las acciones formativas específicas son fundamentales para promover el conocimiento y las competencias en investigación, desarrollo e innovación, tanto de investigadores como de profesionales sanitarios y del ámbito regulatorio. Contar con personal cualificado en ensayos clínicos, terapias avanzadas o regulación es imprescindible para que el ecosistema farmacéutico sea competitivo. Afirmar que no son necesarias en I+D+i contradice la Estrategia. Tampoco se centran solo en el personal administrativo ni se limitan a cursos de comercialización farmacéutica, sino que abarcan la ciencia, la clínica y la regulación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779cf") }, {"question": "Según la Estrategia de la Industria Farmacéutica, ¿cómo evolucionó el gasto público en medicamentos en España entre 2014 y 2023?", "option_1": "Se mantuvo estable sin incrementos significativos.", "option_2": "Se incrementó en promedio 1,2 miles de millones de euros anuales.", "option_3": "Disminuyó progresivamente para controlar el déficit público.", "option_4": "Experimentó incrementos variables sin una tendencia clara.", "long_answer": "Según la Estrategia de la Industria Farmacéutica, entre 2014 y 2023 el gasto público en medicamentos en España se incrementó de forma sostenida, con un aumento medio de unos 1,2 miles de millones de euros cada año. Este crecimiento se explica por el envejecimiento de la población, el aumento de la cronicidad y la incorporación de medicamentos innovadores de alto coste, y justifica las medidas de sostenibilidad que plantea la Estrategia. No se mantuvo estable ni disminuyó durante ese periodo. Tampoco se trató de incrementos variables sin tendencia, ya que la evolución fue claramente ascendente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779d9") }, {"long_answer": "Según la Estrategia, la decisión de financiar un medicamento con fondos públicos tiene en cuenta varios criterios, entre ellos el beneficio clínico adicional que aporta frente a las alternativas, la incertidumbre sobre sus resultados, las garantías de suministro y su aportación económica al país, por ejemplo por la producción o la inversión en I+D en España. Basarse solo en el precio más bajo del mercado europeo ignora el valor terapéutico. Considerar únicamente la producción nacional o el volumen de ventas previsto sin atender a los resultados clínicos no se corresponde con los criterios de financiación del SNS."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779dd") }, {"long_answer": "La Estrategia prevé crear un observatorio continuo de precios en el mercado farmacéutico que permita disponer de información actualizada para proponer medidas cuando la competencia no sea adecuada o cuando los precios, por ser demasiado bajos, amenacen la viabilidad de la comercialización de ciertos medicamentos y pongan en riesgo el suministro. No se limita a registrar los precios de los medicamentos innovadores. Tampoco busca la reducción constante de precios, que podría provocar desabastecimientos, ni limitar el acceso a los datos a las grandes compañías."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779e0") }, {"long_answer": "Según la Estrategia, tendrán acceso al sistema de información nacional de consumo de medicamentos las unidades administrativas que forman parte de los órganos colegiados del ámbito farmacéutico y sanitario, como los que intervienen en la financiación, la fijación de precios o la evaluación de tecnologías, para que puedan tomar decisiones basadas en datos reales. No se trata de un acceso abierto a cualquier investigador público o privado. Tampoco está dirigido al público general, ya que contiene información sensible, ni se reserva a las compañías farmacéuticas autorizadas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779e4") }, {"long_answer": "La Estrategia promueve una colaboración bidireccional entre el sector público y el privado en investigación clínica para desarrollar soluciones más eficientes y acelerar la llegada de las innovaciones al mercado y a los pacientes. España es un país líder en ensayos clínicos y esta colaboración permite aprovechar la capacidad de los hospitales del SNS y la inversión de la industria. No tiene como finalidad reducir el gasto público en investigación. Tampoco pretende limitar la investigación a centros privados ni centrarse exclusivamente en la formación del personal sanitario."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779e5") }, {"long_answer": "El objetivo de elevar la financiación pública en I+D hasta el 1,25% del PIB en 2030 busca, además, movilizar la inversión privada para que la inversión total en I+D alcance el 3% del PIB, en línea con las recomendaciones de la Unión Europea. La inversión pública actúa como palanca que atrae y multiplica la inversión empresarial. Por eso no se trata de consolidar solo la financiación pública sin impacto en la privada. Reducir la investigación preclínica o eliminar la participación en programas internacionales es contrario a este objetivo de impulso a la I+D."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779e8") }, {"long_answer": "El Espacio Nacional de Datos en Salud, federado con el Espacio Europeo de Datos Sanitarios, permitirá realizar estudios, investigación e innovación con datos de vida real procedentes del sistema sanitario, dentro de un marco regulatorio transparente y seguro que proteja la privacidad de los pacientes. Estos datos son muy valiosos para evaluar la efectividad de los medicamentos en la práctica. No pretende bloquear el acceso a los investigadores privados, que pueden acceder bajo condiciones reguladas. Tampoco supone publicar sin restricciones los datos personales, ni limitar su uso a la administración pública."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779e9") }, {"long_answer": "Para aumentar la capacidad de los Comités de Ética de la Investigación con medicamentos (CEIm), la Estrategia propone desarrollar guías de buenas prácticas en la evaluación de los ensayos clínicos, incluyendo aspectos de protección de datos y ciberseguridad, para que las evaluaciones sean más homogéneas, ágiles y rigurosas. Centralizar todas las decisiones en una entidad europea no es la medida prevista, ya que los CEIm son nacionales. Eliminar la participación de las comunidades autónomas reduciría su capacidad, y limitar la evaluación a aspectos económicos es incompatible con la función ética de estos comités."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779ed") }, {"long_answer": "Coordinar las capacidades científicas del sistema público de investigación con las capacidades empresariales tiene como objetivo final lograr un avance más rápido en el desarrollo de productos de interés sanitario, como medicamentos, vacunas o terapias avanzadas, a la vez que se fomenta el empleo cualificado y la competitividad del país. Desvincular el sector académico de los retos empresariales es lo contrario de lo que se busca. Reducir el número de proyectos científicos o priorizar el desarrollo industrial sin impacto sanitario no responde al enfoque de la Estrategia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779ee") }, {"long_answer": "Los contratos tipo de carácter orientativo para la investigación clínica en el SNS buscan minimizar los tiempos y los costes de administración mediante cláusulas armonizadas que puedan utilizar todos los centros y promotores, evitando largas negociaciones contrato a contrato que retrasan el inicio de los ensayos clínicos. No pretenden garantizar la exclusividad en la publicación de resultados. Tampoco buscan incrementar la inversión privada sin supervisión pública, ni ampliar la duración de los ensayos, sino precisamente agilizar su puesta en marcha."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779ef") }, {"long_answer": "El Consorcio Estatal en Red para el desarrollo de Medicamentos de Terapias Avanzadas (CERTERA) está coordinado por el Instituto de Salud Carlos III, organismo que gestiona la Acción Estratégica en Salud y las infraestructuras de investigación biomédica del Estado. CERTERA reúne a centros públicos con capacidad para desarrollar y fabricar medicamentos de terapia avanzada, como las terapias CAR-T. El Ministerio de Sanidad no coordina directamente el consorcio. El CDTI financia proyectos de innovación empresarial, y la AEMPS es la autoridad reguladora que autoriza estos medicamentos, pero no coordina su desarrollo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779f2") }, {"option_1": "Coinvertir, de forma público-privada, en empresas tecnológicas innovadoras en etapas tempranas", "long_answer": "El programa INNVIERTE, gestionado por el CDTI, tiene como finalidad la coinversión pública y privada en empresas tecnológicas innovadoras en etapas tempranas, mediante la entrada en su capital junto con inversores privados especializados. Así se movilizan recursos para empresas biotecnológicas y farmacéuticas emergentes que tienen dificultades para acceder a financiación. No financia exclusivamente la compra de equipos industriales. Tampoco está destinado a incrementar el personal sanitario de los hospitales, ni se limita a ayudar a grandes multinacionales, ya que se dirige a empresas innovadoras en fases iniciales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779f5") }, {"long_answer": "En el ámbito de la formación de profesionales en I+D+i, la AEMPS propone programar acciones formativas periódicas y ofrecer asesoría científico-regulatoria a los distintos actores de la investigación clínica, como investigadores, promotores académicos y pequeñas empresas, para que conozcan los requisitos regulatorios desde las fases iniciales del desarrollo. Formar solo en medicina tradicional sin actualización tecnológica no tiene relación con su papel. Eliminar la formación continua de los investigadores independientes o limitar las acciones formativas a las grandes empresas sería contrario al objetivo de impulsar la investigación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779f7") }, {"long_answer": "Una de las áreas de trabajo principales para fortalecer el sector industrial farmacéutico es el fomento y apoyo a su competitividad a través del programa PROFARMA, gestionado conjuntamente por los ministerios de Industria y de Ciencia, que evalúa y clasifica a las compañías según su actividad industrial, investigadora y de inversión en España. Reducir la inversión en proyectos innovadores debilitaría al sector. Limitar la cooperación internacional en I+D+i o excluir la digitalización de los procesos industriales es contrario a la modernización y la competitividad que busca la Estrategia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779fb") }, {"long_answer": "Según la Estrategia, la Ley de Industria en tramitación tiene entre sus objetivos promover ecosistemas industriales y proyectos tractores de interés general, que sirvan para reforzar la capacidad productiva y la autonomía estratégica en sectores clave como el farmacéutico. No pretende eliminar la regulación del sector farmacéutico, que tiene su propia normativa. Tampoco se dirige exclusivamente a la industria electrónica, ni busca centralizar toda la producción farmacéutica en Europa, sino reforzar la base industrial española."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779fc") }, {"long_answer": "ENISA, la Empresa Nacional de Innovación, financia mediante préstamos participativos proyectos innovadores de pequeñas y medianas empresas y startups, incluidas las del sector farmacéutico y biotecnológico, para fomentar modelos de producción competitivos y sostenibles. No es un organismo regulador ni supervisa la seguridad de los medicamentos, función propia de la AEMPS. Tampoco dirige su apoyo financiero a grandes multinacionales, ni es un programa estatal de formación educativa, ni financia infraestructuras hospitalarias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779fd") }, {"long_answer": "El Fondo de Coinversión (FOCO), gestionado por COFIDES, tiene como finalidad movilizar recursos de inversores extranjeros para coinvertir junto a ellos en proyectos privados de sectores estratégicos de la economía española, como el farmacéutico y el biotecnológico, atrayendo capital internacional. No financia exclusivamente proyectos agrícolas. Tampoco sustituye al CDTI, que mantiene su propio papel en la financiación tecnológica, ni se limita a proyectos públicos sin inversión privada, ya que se basa precisamente en la coinversión con capital privado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a01") }, {"long_answer": "Una de las principales causas que han impulsado la estrategia europea de autonomía estratégica en la industria farmacéutica es la pérdida de peso de Europa en inversiones, en I+D y en producción frente a Asia y Estados Unidos, que ha generado dependencia exterior en principios activos y medicamentos esenciales, como se evidenció en los desabastecimientos durante la pandemia. La reducción global de las enfermedades infecciosas no es una causa de esta estrategia. El consumo farmacéutico en Europa no ha disminuido, y no se ha producido un aumento descontrolado de fabricantes europeos, sino lo contrario."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a02") }, {"long_answer": "El IPCEI Med4Cure es un Proyecto Importante de Interés Común Europeo en el ámbito de la salud que moviliza ayudas públicas y colaboraciones entre empresas de distintos países para desarrollar productos y procesos innovadores en el sector biofarmacéutico. Según la Estrategia, en él participan seis empresas españolas. No es un programa de formación sanitaria. Tampoco es una normativa de regulación farmacéutica, ni una iniciativa para reducir el gasto público en I+D, sino un instrumento europeo para impulsar la innovación y la capacidad industrial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a05") }, {"long_answer": "La mesa de trabajo constituida para aumentar las capacidades productivas en España tiene como función identificar los recursos estratégicos, como los principios activos y medicamentos esenciales, y fortalecer las capacidades productivas del tejido industrial farmacéutico nacional, reduciendo la dependencia exterior. Reducir la producción nacional en favor de las importaciones es justo lo contrario de lo que se busca. Planificar la exportación masiva sin regulación o privatizar el sector sin control público no se corresponde con los objetivos de autonomía estratégica de la Estrategia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a0a") }, {"long_answer": "La Estrategia describe la industria farmacéutica española como un sector relevante y competitivo, con una alta presencia de tecnologías farmacéuticas avanzadas, una sólida capacidad de fabricación y personal altamente cualificado, además de liderazgo en ensayos clínicos. Por eso se considera un sector estratégico para la economía y la salud. No es irrelevante ni poco desarrollada en innovación. Tampoco es totalmente dependiente de la producción extranjera, aunque existan dependencias en algunos principios activos, y no se limita a los genéricos, ya que cuenta con una presencia creciente de empresas biotecnológicas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a0b") }, {"long_answer": "Para las primeras inversiones en empresas de transferencia de tecnología basadas en el conocimiento, el CDTI ofrece el fondo de capital semilla del programa INNVIERTE, dirigido a proyectos en fase muy temprana procedentes de universidades y centros de investigación, que son el origen de muchas innovaciones farmacéuticas. El programa PROFARMA clasifica a las compañías según su actividad industrial e investigadora, pero no es un fondo de inversión. La línea Industria Conectada 4.0 apoya la digitalización industrial, y el Fondo de Apoyo a la Inversión Industrial Productiva financia inversiones industriales, no capital semilla."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a0e") }, {"long_answer": "Según la evidencia clínica que recoge el Plan de Acción para la Prevención del Suicidio, los intentos previos de suicidio son el factor de riesgo aislado más importante para predecir una nueva conducta suicida, sobre todo en los meses posteriores al intento. Por eso el plan insiste en el seguimiento estrecho de estas personas tras el alta. La edad avanzada es un factor de riesgo, especialmente en varones, pero su peso predictivo es menor. El estigma social dificulta pedir ayuda, aunque no predice por sí solo la conducta, y el acceso a servicios de salud mental es un factor protector."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a11") }, {"long_answer": "El Plan de Acción para la Prevención del Suicidio entiende que la conducta suicida es, ante todo, la expresión de un sufrimiento emocional profundo que la persona percibe como insoportable y sin salida, y no únicamente la consecuencia de una enfermedad. La enfermedad mental diagnosticada es un factor de riesgo importante, pero no está presente en todos los casos ni es la manifestación fundamental. El desconocimiento social no es una característica de la persona en riesgo, y el aislamiento físico puede contribuir al malestar, pero no es lo que subyace de forma esencial a la conducta suicida."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a13") }, {"long_answer": "Los medios de comunicación pueden contribuir a la prevención del suicidio difundiendo información rigurosa, testimonios de personas que han superado una crisis y recursos de ayuda, como la línea 024, lo que se conoce como efecto Papageno, que tiene un efecto protector. Publicar detalles sobre casos concretos, como el método o el lugar, puede favorecer la imitación o efecto Werther. Centrar la información en estadísticas alarmantes o sensacionalistas también es desaconsejable, y evitar hablar del suicidio contribuye al estigma y al silencio, por lo que las recomendaciones apuestan por informar de forma responsable."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a18") }, {"long_answer": "La evidencia recogida en el plan señala que las intervenciones de posvención dirigidas a familiares y allegados de una persona fallecida por suicidio, como los grupos de apoyo de supervivientes, reducen la intensidad del duelo y el malestar psicológico, y ayudan a afrontar la culpa y el estigma asociados a esta pérdida. Afirmar que eliminan por completo el riesgo futuro de suicidio en los familiares es excesivo, aunque contribuyan a reducirlo. No es cierto que falte evidencia, y su eficacia no depende de que se realicen intervenciones médicas, ya que muchas son psicosociales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a19") }, {"long_answer": "El Plan de Acción para la Prevención del Suicidio otorga a la comunidad un papel esencial en la creación de entornos de apoyo que fortalezcan el bienestar emocional y los lazos sociales, reduzcan el aislamiento y ayuden a detectar a las personas en riesgo y orientarlas hacia los recursos disponibles. La prevención no corresponde solo a las autoridades sanitarias, sino que implica a familias, escuelas, entidades y otros agentes sociales. Afirmar que la comunidad no tiene un papel relevante o que la prevención es exclusiva del ámbito clínico contradice el enfoque comunitario del plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a1c") }, {"long_answer": "Los protocolos específicos para la intervención de los equipos de emergencia en crisis suicidas definen las fases de actuación, las competencias de cada profesional implicado y las medidas de seguridad necesarias para la persona en riesgo y para los intervinientes, con el fin de dar una respuesta coordinada y eficaz. No se limitan a la evacuación, ya que incluyen la intervención psicológica en crisis y la contención. Sí contemplan la coordinación interinstitucional entre servicios sanitarios, cuerpos de seguridad y otros recursos, y se aplican fuera del hospital, en el lugar donde se produce la crisis."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a1e") }, {"long_answer": "Para mejorar la equidad y la cohesión del SNS en la prevención del suicidio, el plan considera fundamental promover la colaboración entre las distintas administraciones, como el Ministerio y las comunidades autónomas, y con la sociedad civil, incluyendo asociaciones de supervivientes y entidades del tercer sector. Así se garantiza que todas las personas, vivan donde vivan, tengan acceso a medidas de prevención y atención de calidad. Reducir el acceso comunitario a los servicios, centralizar la atención en hospitales especializados o eliminar el seguimiento de las personas con conducta suicida empeoraría la equidad y la protección."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a21") }, {"long_answer": "El Observatorio para la Prevención del Suicidio tiene como función principal analizar y difundir información homogénea, fiable y actualizada sobre la conducta suicida, mediante la coordinación entre instituciones como el Ministerio de Sanidad, las comunidades autónomas, el Instituto Nacional de Estadística o los institutos de medicina legal. Esta información permite orientar y evaluar las políticas de prevención. El Observatorio no presta atención psicológica directa a personas en crisis. Tampoco regula los contenidos de los medios de comunicación ni tiene capacidad para sancionar el incumplimiento de protocolos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a24") }, {"long_answer": "El plan reconoce que muchas personas que mueren por suicidio contactaron con Atención Primaria en las semanas previas, por lo que prevé acciones formativas dirigidas a los médicos y demás profesionales de este nivel para mejorar la detección, la valoración del riesgo, el seguimiento y la atención de las personas en riesgo. Derivar directamente todos los casos a psiquiatría sin seguimiento propio desaprovecha la cercanía y la continuidad de la Atención Primaria. Limitarse a administrar medicación sin seguimiento o evitar tratar los problemas de salud mental es contrario al papel que el plan atribuye a este nivel asistencial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a27") }, {"long_answer": "El plan considera a las personas LGTBIQ+ un grupo vulnerable en la prevención del suicidio por las distintas formas de estigma, discriminación, rechazo familiar, acoso y violencia que sufren por su orientación sexual o su identidad de género. Estas experiencias generan estrés de minoría y aumentan el riesgo de ideación e intentos de suicidio, sobre todo en adolescentes y jóvenes. Su vulnerabilidad no se debe a la edad avanzada. Tampoco se atribuye a una mayor prevalencia de enfermedades crónicas, ni a que se encuentren mayoritariamente en situación de pobreza."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a29") }, {"long_answer": "Un componente esencial de la atención y el seguimiento en la prevención del suicidio es monitorizar a las personas que han sobrevivido a un intento, aplicando intervenciones específicas como el contacto activo tras el alta, la cita precoz con salud mental, el plan de seguridad y la coordinación con Atención Primaria, ya que el riesgo de repetición es máximo en los meses siguientes. Limitar el contacto a sesiones médicas rutinarias no da respuesta a ese riesgo. Evitar intervenir alegando autonomía deja desprotegida a la persona, y centrarse solo en tratamiento farmacológico ignora el abordaje psicosocial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a2c") }, {"long_answer": "Aumentar el peso de la Atención Primaria en los grados universitarios de ciencias de la salud tiene como objetivo mejorar la formación teórico-práctica de los futuros profesionales en este ámbito y fomentar la investigación y la innovación en Atención Primaria, de modo que el alumnado conozca el modelo y se sienta atraído por él. Reducir el número de profesionales dedicados a Atención Primaria es contrario al plan. Concentrar los estudios prácticos en hospitales terciarios o eliminar la participación de los profesionales de Atención Primaria en la docencia restaría presencia a este nivel en la formación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a2d") }, {"long_answer": "El plan fija como meta que en 2026 se haya presentado al Ministerio de Universidades una propuesta, elaborada por el Ministerio de Sanidad junto con las comunidades autónomas, para reconocer la Atención Primaria como área de conocimiento en el ámbito universitario. Este reconocimiento facilitaría la creación de departamentos y plazas docentes vinculadas a este nivel. La propuesta no corresponde exclusivamente a las universidades, no se plantea para 2027 sin consultar a las comunidades autónomas, ni para 2024 mediante una resolución automática."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a30") }, {"long_answer": "La definición y aprobación de mapas de competencias en la reestructuración de los equipos de Atención Primaria busca redistribuir las tareas de forma que cada necesidad de la población sea atendida por el profesional más adecuado según sus competencias, ya sea de enfermería, medicina, fisioterapia, trabajo social o administración. Así se mejora la eficiencia y la accesibilidad. Eliminar la figura del administrativo sanitario es contrario al plan, que refuerza este perfil. Asignar todas las funciones a los médicos de familia o limitar la participación de otros perfiles va en contra del trabajo en equipo multidisciplinar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a35") }, {"long_answer": "El plan fija como indicador que, antes del 31 de diciembre de 2027, al menos el 80% de las comunidades autónomas y el INGESA hayan incorporado al menos el 70% del contenido de la actualización de la cartera común de servicios de Atención Primaria. De este modo se asegura que las mejoras previstas, como los nuevos procedimientos diagnósticos o la atención no presencial, lleguen a la mayor parte de la población. El 50% y el 30% son porcentajes inferiores a la meta establecida, y afirmar que no hay ningún porcentaje fijado es incorrecto, porque el indicador está cuantificado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a39") }, {"long_answer": "Para reducir la carga burocrática en las consultas, el plan prevé firmar antes de 2026 un acuerdo entre el Ministerio de Sanidad y los organismos públicos competentes para impulsar la autodeclaración responsable, de forma que la ciudadanía pueda justificar determinadas ausencias o situaciones de corta duración sin necesidad de un certificado médico. Esto libera tiempo asistencial para tareas clínicas. Prohibir las autodeclaraciones iría en sentido contrario. Centralizar todo el papeleo en el Ministerio o automatizarlo por completo sin supervisión humana no son medidas contempladas en el plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a3a") }, {"long_answer": "El plan establece como objetivo que en 2026 el 100% de las comunidades autónomas hayan adecuado e implantado la autodeclaración responsable, como medida de desburocratización que evita que los profesionales de Atención Primaria tengan que emitir justificantes para situaciones que la propia persona puede declarar. La implantación en todas las comunidades garantiza que la medida beneficie a toda la ciudadanía por igual. El 50% y el 25% son inferiores a la meta fijada, y que ninguna comunidad la haya implantado sería contrario al propio indicador."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a3e") }, {"long_answer": "El plan fija como indicador que, en 2027, al menos el 60% de las comunidades autónomas hayan conseguido un incremento del 25% respecto a 2026 en el número de procesos de salud resueltos en Atención Primaria. Este aumento refleja una mayor capacidad resolutiva del primer nivel, gracias a la ampliación de la cartera, el acceso a pruebas diagnósticas y la redistribución de competencias. Un incremento del 10% es inferior a la meta y uno del 50% la supera. Afirmar que no se establece incremento es incorrecto, ya que el indicador está cuantificado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a43") }, {"long_answer": "El plan fija como indicador que, en 2026, el 80% de las comunidades autónomas evidencien la implantación de las recomendaciones para el manejo de la persona mayor con polimedicación, que incluyen la revisión periódica de la medicación, la conciliación y la deprescripción. Con ello se busca reducir interacciones, efectos adversos y caídas en este grupo de población. Los porcentajes del 50% y el 30% son inferiores a la meta establecida. El 100% supera el objetivo fijado para esa fecha, aunque la implantación completa sea deseable a más largo plazo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a46") }, {"long_answer": "Respecto al Protocolo Común de Actuación Sanitaria frente a la Violencia en la Infancia y la Adolescencia, el plan fija como indicador que en 2027 el 50% de las comunidades autónomas presenten evidencias de su implantación en Atención Primaria, que tiene un papel clave en la detección precoz y la protección de menores. No se contempla suspender su aplicación hasta una nueva normativa. Limitar su aplicación inicial a una sola comunidad no se corresponde con la meta, y restringirlo a los centros hospitalarios dejaría fuera a la Atención Primaria, que es precisamente donde se busca implantarlo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a47") }, {"long_answer": "El Comité Institucional y el Comité Técnico del Marco Estratégico de Atención Primaria y Comunitaria (MAPyC) colaboran en el consenso y la elaboración de la propuesta del modelo de gestión integral de la demanda, que se basa en el mapa de competencias de los profesionales. Estos comités reúnen a representantes del Ministerio, de las comunidades autónomas y de profesionales, de modo que el modelo se construye de forma participativa. Ignorar las propuestas de los profesionales, reducir la participación de los pacientes o centralizar la gestión en el Ministerio sin colaboración es contrario a su función."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a49") }, {"long_answer": "Para facilitar la incorporación de profesionales de Atención Primaria a puestos docentes universitarios, el plan busca garantizar que puedan obtener la acreditación adecuada conforme a los criterios actualizados de la ANECA, que deben reconocer la actividad asistencial, docente e investigadora propia de este nivel. Así se favorece que médicos, enfermeras y otros profesionales de Atención Primaria accedan a plazas académicas. Restringir la docencia a los médicos excluiría a las enfermeras y otros perfiles. Eliminar el requisito de acreditación o reducir la formación práctica no se corresponde con el plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a4c") }, {"long_answer": "En relación con la prevención de la fragilidad en la persona mayor, el plan impulsa la actualización y la aplicación íntegra en Atención Primaria del documento de consenso del SNS sobre prevención de la fragilidad, que incluye el cribado y la valoración de la fragilidad, la actividad física multicomponente, la revisión de la medicación y la prevención de caídas. Recomendar exclusivamente actividad física sin evaluación previa no se ajusta a un abordaje individualizado. La derivación inmediata al hospital no es necesaria, ya que se aborda desde Atención Primaria, y no se recomiendan suplementos vitamínicos de forma rutinaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a50") }, {"long_answer": "Para facilitar la intervención desde Atención Primaria en la prevención del suicidio, el plan incluye la identificación de las personas en situación de soledad no deseada y su vinculación con la red comunitaria, ya que el aislamiento social es un factor de riesgo relevante y los recursos comunitarios refuerzan el apoyo y los vínculos. La derivación inmediata a urgencias hospitalarias no es el mecanismo previsto para todos los casos. Aplicar test psicológicos mensuales a toda la población no es factible ni recomendable, y limitar el seguimiento a pacientes con antecedentes psiquiátricos dejaría fuera a muchas personas en riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a56") }, {"long_answer": "Los sistemas de comunicación bidireccional entre las farmacias comunitarias y los centros de salud tienen como finalidad optimizar la coordinación farmacoterapéutica y la atención al paciente, permitiendo comunicar incidencias en la dispensación, problemas de adherencia, interacciones o reacciones adversas, y resolverlas de forma conjunta. Aumentar la burocracia administrativa es lo contrario de lo que se busca. Centralizar la dispensación en los hospitales no tiene relación con esta medida, y eliminar el historial farmacológico compartido restaría seguridad en el uso de los medicamentos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a5b") }, {"long_answer": "Para mejorar la motivación de los profesionales de Atención Primaria, el plan contempla, dentro de los acuerdos de recursos humanos, una mayor flexibilidad en los horarios y una mayor capacidad para gestionar su propia actividad y agenda, lo que mejora la conciliación y la satisfacción laboral y ayuda a fidelizar a los profesionales. Reducir los días de descanso para aumentar la productividad aumentaría el desgaste profesional. Eliminar los permisos para la formación continuada o imponer una jornada fija sin adaptaciones son medidas contrarias a la fidelización y la atracción del talento que persigue el plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a5f") }, {"long_answer": "Para medir la integración y la continuidad asistencial en las historias de salud digitales, el plan utiliza como indicador el número de comunidades autónomas que disponen de sistemas interoperables entre Atención Primaria y Atención Hospitalaria, de modo que la información clínica se comparta entre niveles. Las consultas presenciales sin registro digital y el porcentaje de médicos que utilizan papel para anotar el historial reflejan prácticas contrarias a la digitalización. El número de historias sin acceso para los servicios sociosanitarios mediría una carencia, no la integración que se pretende evaluar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a63") }, {"long_answer": "Para actualizar y mejorar la atención comunitaria, el plan establece que las comunidades autónomas deben implementar, visibilizar y evaluar sus Estrategias de Salud Comunitaria, con el fin de reforzar la orientación comunitaria de los equipos de Atención Primaria, la promoción de la salud y el trabajo en red con los activos del territorio. Concentrar la atención comunitaria en los servicios hospitalarios es contradictorio con su propia naturaleza. Reducir la formación de los profesionales en orientación comunitaria o eliminar la evaluación de las estrategias iría en contra de los objetivos de la Línea 7 del plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f0c") }, {"option_2": "Contacto estrecho piel con piel con las lesiones o fluidos corporales de una persona infectada", "long_answer": "En el brote actual de mpox, la transmisión se produce fundamentalmente de persona a persona mediante contacto estrecho y directo, piel con piel, con las lesiones cutáneas, costras o fluidos corporales de una persona infectada, especialmente durante las relaciones sexuales. También puede transmitirse por gotas respiratorias en contactos cara a cara prolongados y por fómites, pero son vías secundarias. La transmisión aérea a distancia no es el mecanismo principal, no se ha descrito transmisión por vectores como mosquitos o garrapatas, y la ingestión de alimentos contaminados no es una vía relevante de contagio entre personas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f0e") }, {"option_4": "Usar mascarilla quirúrgica al compartir espacio con otras personas, especialmente si hay síntomas respiratorios", "long_answer": "Según el protocolo del Ministerio de Sanidad, los casos sospechosos o probables de mpox deben permanecer aislados en la medida de lo posible y, cuando compartan espacio con otras personas, utilizar mascarilla quirúrgica, sobre todo si presentan síntomas respiratorios, además de cubrir las lesiones y extremar la higiene de manos. No se exige llevar mascarilla en todo momento, incluso estando solos, ni evitar cualquier actividad física, que no guarda relación con la transmisión. Mantener interacciones sociales normales sería incorrecto, porque el contacto estrecho es precisamente la principal vía de contagio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f18") }, {"long_answer": "Para los contactos estrechos de un caso de mpox sin contacto físico directo, el protocolo del Ministerio de Sanidad no establece cuarentena, pero sí recomienda vigilancia de la aparición de síntomas y extremar las precauciones durante los 21 días posteriores a la última exposición, que corresponden al periodo máximo de incubación. Esto incluye reducir las interacciones sociales, evitar el contacto sexual y con personas vulnerables y usar mascarilla en espacios compartidos. No hacer ningún seguimiento sería incorrecto, la cuarentena obligatoria no está indicada y mantener una vida social normal no protege frente a una posible transmisión presintomática o en fase prodrómica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f1a") }, {"option_3": "Diferir la donación de sustancias durante 21 días", "long_answer": "Las personas que han tenido una exposición de riesgo a un caso confirmado de mpox deben abstenerse de donar sangre, células, tejidos, órganos, leche materna o semen durante 21 días desde la última exposición, ya que este plazo coincide con el periodo máximo de incubación de la enfermedad y permite descartar que la persona esté infectada. No aplicar ninguna restricción supondría un riesgo de transmisión al receptor. Un diferimiento de 14 días resulta insuficiente porque no cubre toda la incubación, y uno de 40 días sería excesivo y no se corresponde con la recomendación establecida."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f1d") }, {"option_3": "Alteración cognitiva transitoria y fluctuante, de inicio brusco y con alteración del nivel de conciencia", "long_answer": "La Guía de Práctica Clínica sobre demencia del SNS define la demencia como un síndrome clínico caracterizado por un déficit adquirido en más de un dominio cognitivo, que supone una pérdida respecto al nivel previo y reduce de forma significativa la autonomía funcional. La definición que habla de pérdida neuronal y sináptica con depósito de agregados proteicos describe una enfermedad neurodegenerativa, no el síndrome demencial. La alteración transitoria, fluctuante y de inicio brusco con afectación del nivel de conciencia corresponde al delirium o síndrome confusional agudo. Un déficit limitado a un solo dominio cognitivo no cumple los criterios de demencia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f1f") }, {"long_answer": "Los factores de riesgo de demencia no modificables son aquellos sobre los que no se puede intervenir: la edad, que es el principal, el sexo, los antecedentes familiares de demencia y la presencia del alelo ε4 de la apolipoproteína E, que aumenta la probabilidad de enfermedad de Alzheimer. La hipertensión, la diabetes, la hipercolesterolemia o el traumatismo craneal grave son factores de riesgo modificables o potencialmente prevenibles. La depresión, el tabaquismo o el bajo nivel educativo también son modificables. La vacunación, la terapia hormonal sustitutiva, la actividad física o los ácidos grasos omega-3 se han estudiado como posibles factores protectores, no como factores no modificables."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f26") }, {"question": "¿Cuál es la tasa estimada de amputaciones en los pacientes con diabetes?", "long_answer": "La tasa de amputaciones en personas con diabetes se estima entre aproximadamente 0,5 y 10 por cada 1.000 pacientes al año, con gran variabilidad según el país, el control metabólico y la organización de la atención al pie diabético. La cifra de una prevalencia de alrededor del 2-3 % no se refiere a la tasa anual de amputaciones, sino a la frecuencia de lesiones o úlceras de pie en la población diabética. Un 10 % anual o un 30 % de las personas con diabetes sobrestiman claramente el riesgo de amputación, que, aunque muy superior al de la población general, es mucho menor."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f33") }, {"long_answer": "Alrededor del 30 % de los pacientes con enfermedad de Parkinson presentan ya leves alteraciones cognitivas, compatibles con deterioro cognitivo leve, en el momento del diagnóstico, afectando sobre todo a funciones ejecutivas, atención y capacidades visuoespaciales. Estas alteraciones suelen progresar con la evolución y muchos pacientes acaban desarrollando demencia en fases avanzadas. Una cifra inferior al 10 % infraestima la frecuencia real del deterioro cognitivo inicial, mientras que porcentajes cercanos al 50 % o superiores al 70 % corresponden más bien a la prevalencia acumulada de deterioro cognitivo o demencia a largo plazo, no a la situación en el momento del diagnóstico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f36") }, {"long_answer": "Tradicionalmente, en las unidades neonatales el contacto físico de la familia con el recién nacido se consideraba una posible fuente de contaminación e infección, por lo que se restringía el acceso de los padres y se limitaba su participación en los cuidados. Hoy se sabe que esta visión era errónea: el contacto piel con piel y la presencia de los padres favorecen la estabilidad fisiológica, la lactancia materna y el vínculo, sin aumentar las infecciones. No se consideraba una práctica habitual de interacción, precisamente porque se restringía; tampoco se presentaba como irrelevante ni como una estrategia para disminuir la ansiedad parental."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f43") }, {"long_answer": "Dentro del útero el feto vive en un ambiente cálido, oscuro y húmedo, rodeado de líquido amniótico, donde los sonidos externos le llegan amortiguados y los estímulos son suaves y rítmicos. Por ello, en los cuidados centrados en el desarrollo se intenta reproducir en la unidad neonatal algunas de estas condiciones, reduciendo la luz y el ruido y favoreciendo la contención. Un entorno frío, seco, ruidoso e iluminado es justo lo que encuentra el prematuro al nacer y no lo que tenía en el útero. Tampoco existe luz intensa intrauterina ni estímulos constantes y sin amortiguar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f48") }, {"option_4": "Aumento de la presión arterial", "long_answer": "Reducir la intensidad de la luz en la unidad de cuidados intensivos neonatales disminuye el estrés del recién nacido, especialmente del prematuro, cuyo sistema visual es inmaduro y no está preparado para la luz intensa y continua. La penumbra favorece el sueño, la estabilidad fisiológica y la organización conductual, y se integra en los cuidados centrados en el desarrollo. Por ello, la reducción lumínica no aumenta la frecuencia cardiaca, sino que tiende a estabilizarla, ni incrementa la actividad motora, que suele disminuir al haber menos estímulos. Tampoco provoca un aumento de la presión arterial, que es un signo asociado precisamente a situaciones de estrés."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f59") }, {"long_answer": "En los países desarrollados los sucedáneos de leche materna comercializados están suplementados con vitamina K, por lo que los recién nacidos alimentados exclusivamente con ellos reciben un aporte suficiente y no necesitan dosis adicionales después de la profilaxis administrada al nacimiento para prevenir la enfermedad hemorrágica tardía. Las pautas orales repetidas, ya sean semanales hasta la 12.ª semana o dosis en las semanas 1 y 4, se plantean para lactantes amamantados cuyos padres rechazan la vía intramuscular, ya que la leche materna contiene poca vitamina K. La dosis intramuscular de 1 mg corresponde a la profilaxis universal al nacer, no a dosis posteriores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f60") }, {"long_answer": "Históricamente, la principal causa de oftalmia neonatal fue Neisseria gonorrhoeae, adquirida durante el paso por el canal del parto, que producía una conjuntivitis purulenta grave capaz de causar ceguera; por ello se instauró la profilaxis ocular sistemática, inicialmente con nitrato de plata. Actualmente, en los países desarrollados, Chlamydia trachomatis es el agente más frecuente, pero no lo fue en el pasado. Staphylococcus aureus y Escherichia coli pueden causar conjuntivitis neonatal, aunque con menor gravedad y sin el papel histórico que tuvo el gonococo en la justificación de la profilaxis."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f68") }, {"long_answer": "La elección del fármaco para la profilaxis oftálmica neonatal debe basarse en la epidemiología local de las infecciones de transmisión sexual, las resistencias antibióticas de los microorganismos implicados, la aceptabilidad, el coste y la disponibilidad del producto, tal como recoge la guía de cuidados desde el nacimiento del Ministerio de Sanidad. Se trata de una decisión de salud pública basada en la evidencia y en el contexto, no en preferencias individuales. Por ello no es adecuado decidir según la preferencia de los padres, la experiencia personal del neonatólogo o la tradición de cada comunidad, que no garantizan la eficacia ni la seguridad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f6b") }, {"question": "Según el calendario 1-3-6 del cribado auditivo neonatal, ¿antes de qué edad debe completarse el diagnóstico audiológico de los niños que no superan el cribado?", "long_answer": "El programa de cribado auditivo neonatal sigue el esquema 1-3-6: el cribado debe realizarse antes del primer mes de vida, el diagnóstico audiológico de los niños que no lo superan debe completarse antes de los 3 meses y la intervención o tratamiento debe iniciarse antes de los 6 meses. Esta precocidad es clave para el desarrollo del lenguaje. Afirmar que no es necesario es incorrecto, ya que la hipoacusia congénita es frecuente y tratable. Los 6 meses corresponden al inicio de la intervención y no al diagnóstico, y esperar hasta los 12 meses retrasaría de forma inaceptable la detección."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f6c") }, {"long_answer": "La recomendación de realizar el cribado auditivo neonatal universal mediante potenciales evocados auditivos automatizados de tronco cerebral tiene un grado B, es decir, existe evidencia científica de calidad moderada de que la intervención aporta un beneficio neto y se recomienda su aplicación. El grado A exigiría evidencia de alta calidad con beneficio sustancial, que no se alcanza por la ausencia de grandes ensayos sobre resultados a largo plazo. Los grados C y D se reservan para intervenciones con beneficio pequeño o incierto, o para aquellas en las que se desaconseja su realización, lo que no corresponde a este cribado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f6f") }, {"long_answer": "El objetivo del cribado metabólico neonatal es identificar precozmente, en la población de recién nacidos aparentemente sanos, trastornos metabólicos y endocrinos congénitos para los que existe una intervención eficaz, como la dieta en la fenilcetonuria o el tratamiento hormonal en el hipotiroidismo congénito, evitando así discapacidad intelectual, secuelas graves o muerte. Su sentido es precisamente la detección antes de que aparezcan síntomas, no en etapas avanzadas. El recuento de leucocitos y la evaluación de la capacidad pulmonar no forman parte de este programa, que se basa en determinaciones bioquímicas específicas en sangre seca."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f70") }, {"long_answer": "La determinación analítica del cribado metabólico neonatal consiste en la obtención de unas gotas de sangre mediante punción en el talón del recién nacido, que se recogen e impregnan en papel de filtro especial y se envían al laboratorio de referencia para su análisis. La muestra suele tomarse entre las 24 y 72 horas de vida, tras el inicio de la alimentación. No se extraen muestras de tejido para microscopía ni se analiza de rutina la orina. Aunque algunas confirmaciones diagnósticas incluyan estudios genéticos, la prueba de cribado poblacional no consiste en realizar pruebas genéticas a todos los neonatos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f7a") }, {"option_1": "Reinfundir la sangre del circuito al paciente para minimizar la pérdida hemática", "long_answer": "Ante una hemólisis aguda durante la hemodiálisis, se detiene la bomba, se pinzan las líneas y, antes de retirar el circuito extracorpóreo, la enfermera debe revisarlo para intentar identificar los factores causales del episodio, como acodaduras o estrechamientos de las líneas, temperatura o conductividad inadecuadas del líquido de diálisis o contaminación del agua, y así evitar nuevos episodios. La sangre del circuito no debe reinfundirse, porque está hemolizada y aportaría potasio y hemoglobina libre al paciente. Dejar el circuito sin revisar o terminar la sesión sin más procedimientos impide conocer y corregir la causa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f7f") }, {"long_answer": "Según el informe técnico del Ministerio de Sanidad sobre SARS-CoV-2 en aguas residuales, aunque el ARN viral se detecta con frecuencia en heces, solo tres estudios habían logrado aislar virus infectivo en muestras fecales de pacientes con COVID-19, lo que indica que es posible pero poco frecuente y que la transmisión fecal-oral tiene un papel muy limitado. Por tanto, no es cierto que no exista ninguna evidencia, ni que se base en un único estudio. Tampoco puede afirmarse que el documento no lo mencione, ya que recoge expresamente estos hallazgos al valorar el riesgo asociado a las aguas residuales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f80") }, {"long_answer": "El tratamiento de las aguas residuales en las depuradoras, mediante procesos biológicos y de desinfección, reduce de forma importante la carga viral y la viabilidad de virus envueltos como el SARS-CoV-2, que son poco resistentes en el medio acuático. Por ello, el documento técnico del Ministerio de Sanidad considera que el tratamiento disminuye el riesgo de presencia de virus infectivo en el agua tratada. No aumenta el riesgo ni carece de impacto, ya que precisamente su objetivo es eliminar microorganismos. Además, el documento sí aborda esta cuestión al evaluar el riesgo de transmisión a través del ciclo del agua."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f81") }, {"long_answer": "El Ministerio de Sanidad desaconsejó verter lejía en inodoros y desagües como medida frente a la COVID-19 porque no aporta beneficio para prevenir la transmisión y, en cambio, aumenta el riesgo de contaminación ambiental: el cloro llega a las depuradoras, puede alterar los procesos biológicos de tratamiento del agua y generar subproductos tóxicos en el medio. Además, puede producir gases irritantes si se mezcla con otros productos. El motivo no es la falta de disponibilidad de lejía ni su coste, que es bajo. Tampoco se afirma que no tenga ningún efecto, ya que es un desinfectante eficaz sobre superficies."});
rm('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f89") });
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f8d") }, {"long_answer": "El periodo de incubación de la hepatitis A oscila entre 15 y 50 días, con una media aproximada de 28 días, es decir, unas cuatro semanas entre la exposición al virus y la aparición de los síntomas. Este dato es importante para el estudio de contactos y brotes, y para valorar la profilaxis posexposición con vacuna o inmunoglobulina, eficaz si se administra en las dos primeras semanas tras la exposición. Un intervalo de 15-20 días corresponde al extremo inferior del rango, 40-50 días al extremo superior y 60 días supera el periodo de incubación máximo habitual."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f92") }, {"option_4": "Tomar una copa de vino tinto al día como factor protector", "long_answer": "El Código Europeo contra el Cáncer recomienda llevar una alimentación saludable que incluya abundantes cereales integrales, legumbres, frutas y verduras, limitar los alimentos hipercalóricos y las bebidas azucaradas y evitar la carne procesada, limitando además el consumo de carne roja y de alimentos con mucha sal, por su relación con el cáncer colorrectal y otros tumores. No contempla fumar en exteriores, ya que recomienda no fumar ni consumir tabaco en ninguna forma. Los alimentos hipercalóricos deben limitarse. Respecto al alcohol, aconseja limitar su consumo y señala que no beberlo es lo mejor para prevenir el cáncer, por lo que no tiene efecto protector."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f95") }, {"long_answer": "El Código Europeo contra el Cáncer recomienda averiguar si se está expuesto en el domicilio a radiación procedente de niveles naturales elevados de radón y, en ese caso, tomar medidas para reducirlos, ya que el radón es un gas radiactivo natural que constituye la segunda causa de cáncer de pulmón tras el tabaco. Ignorar la posible exposición es contrario a esta recomendación. La ventilación puede formar parte de las medidas correctoras, pero el Código no recomienda ventilar constantemente sin conocer previamente el nivel de exposición. Los protectores solares no tienen ninguna utilidad frente al radón, que se inhala."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f96") }, {"question": "Según el Código Europeo contra el Cáncer, ¿frente a qué infección se recomienda que las niñas participen en programas de vacunación?", "option_1": "Hepatitis A", "option_2": "Virus del papiloma humano (VPH)", "option_3": "Virus de Epstein-Barr", "option_4": "Helicobacter pylori", "answer": 2, "long_answer": "El Código Europeo contra el Cáncer recomienda asegurarse de que los hijos participen en los programas de vacunación frente a la hepatitis B, en el caso de los recién nacidos, y frente al virus del papiloma humano, en el caso de las niñas, ya que la infección persistente por VPH de alto riesgo es la causa necesaria del cáncer de cuello uterino y se relaciona con otros tumores anogenitales y orofaríngeos. La hepatitis A no se asocia a cáncer. Frente al virus de Epstein-Barr no existe vacuna disponible, y Helicobacter pylori, aunque se relaciona con el cáncer gástrico, tampoco cuenta con vacuna."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f97") }, {"long_answer": "El Código Europeo contra el Cáncer se centra en acciones individuales que cualquier ciudadano puede adoptar para reducir su riesgo de cáncer, como no fumar, mantener un peso saludable, hacer actividad física, limitar el alcohol, protegerse del sol, vacunarse y participar en los programas de cribado. Es, por tanto, una herramienta de prevención dirigida a la población general. No se ocupa de la búsqueda de una cura ni del tratamiento del cáncer avanzado, que corresponden al ámbito asistencial y de investigación. Promover el consumo de tabaco es justo lo contrario de su primera recomendación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f98") }, {"long_answer": "El Código Europeo contra el Cáncer recomienda evitar la exposición excesiva al sol, sobre todo en los niños, utilizar protección solar y no usar cabinas de rayos UVA, ya que la radiación ultravioleta es la principal causa de melanoma y otros cánceres de piel, y las quemaduras en la infancia aumentan especialmente el riesgo. Por ello, las camas de bronceado están expresamente desaconsejadas. El aceite bronceador no protege y favorece una mayor absorción de radiación. No usar protección solar contradice directamente la recomendación del Código."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976f9d") }, {"long_answer": "La Ley 33/2011, General de Salud Pública, establece que la vacunación en España es voluntaria, sin perjuicio de que las autoridades sanitarias puedan adoptar medidas especiales en situaciones de riesgo para la salud pública. Por ello, la estrategia de vacunación se basa en la información, la recomendación y la confianza de la población, alcanzando coberturas altas sin obligatoriedad. La obligatoriedad no es el principio general. La responsabilidad ética y la colaboración son valores presentes en la salud pública, pero no constituyen el principio que define jurídicamente el carácter de la vacunación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fa3") }, {"option_1": "Linfadenopatía y náuseas", "long_answer": "Según la ficha técnica de Comirnaty 30 μg, en personas de 12 años o más las reacciones adversas más frecuentes son el dolor en el lugar de la inyección, que aparece en más del 80 % de los vacunados, y la fatiga, en más del 60 %, seguidas de cefalea, mialgia y escalofríos. Suelen ser leves o moderadas y desaparecer en pocos días. Los escalofríos y el dolor muscular son frecuentes, pero menos que el dolor local y la fatiga. La linfadenopatía y las náuseas son poco frecuentes, y los mareos y la debilidad no figuran entre las reacciones más habituales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fa8") }, {"long_answer": "En las personas con alto grado de inmunosupresión, como trasplantados, pacientes con tratamientos inmunosupresores intensos o en quimioterapia, la respuesta inmunitaria a la primovacunación frente a COVID-19 es menor, por lo que el Ministerio de Sanidad recomendó administrar una dosis adicional de vacuna para completar la pauta y optimizar la protección. La dosis estándar resulta insuficiente en estos pacientes. No vacunar sería un error, ya que tienen mayor riesgo de enfermedad grave y las vacunas de ARNm no están contraindicadas. Tampoco se limita la vacunación al entorno hospitalario."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fb0") }, {"long_answer": "En la comunicación sobre mpox es fundamental ofrecer información veraz, actualizada y basada en la evidencia científica, con un lenguaje claro y sin estigmatizar a ningún colectivo, para que la población conozca los síntomas, las vías de transmisión y las medidas preventivas y acuda precozmente a los servicios sanitarios. Las estrategias o el tono alarmista generan miedo, desconfianza y estigma, y pueden hacer que las personas oculten síntomas o eviten consultar. El lenguaje técnico y confuso dificulta la comprensión y va en contra de cualquier principio de comunicación en salud pública."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fb3") }, {"long_answer": "El Manual de políticas sobre el alcohol contrapone dos perspectivas: la de salud pública, que busca reducir el consumo de alcohol y los daños que provoca, priorizando el bienestar de la población, y la de lucro, propia de la industria, orientada a aumentar las ventas y el beneficio económico. Por tanto, la perspectiva que persigue reducir el consumo y sus daños es la de salud pública. La perspectiva de lucro tiene el objetivo contrario, por lo que no puede afirmarse que ambas busquen reducirlo, y la opción de ninguna de las anteriores es incorrecta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fb6") }, {"long_answer": "En el Manual de políticas sobre el alcohol, la perspectiva de lucro representa los intereses de la industria del alcohol, dirigidos a aumentar las ventas y el beneficio económico, lo que entra en conflicto con los objetivos de salud pública. Esta perspectiva suele oponerse a medidas eficaces como la subida de impuestos, la limitación de la publicidad o el etiquetado con advertencias. No busca reducir el consumo ni priorizar el bienestar de las personas, ni sirve al interés público. Tampoco carece de influencia: la industria ejerce una presión considerable sobre el diseño de las políticas sobre alcohol."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fb7") }, {"long_answer": "La evidencia en salud pública señala que el alcohol es una sustancia tóxica, cancerígena, teratogénica y adictiva: daña múltiples órganos, está clasificado como carcinógeno del grupo 1, su consumo durante el embarazo puede causar el trastorno del espectro alcohólico fetal y genera dependencia. Por ello, no existe un nivel de consumo totalmente seguro. Los supuestos beneficios del consumo moderado no se sostienen con la evidencia actual y no constituyen efectos tóxicos ni adictivos. Tampoco puede hablarse de efectos positivos en la salud general, y afirmar que no hay efectos negativos demostrados es falso."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fb8") }, {"long_answer": "Según la OMS, el consumo de alcohol es un factor causal de más de 200 enfermedades y lesiones, entre ellas varios tipos de cáncer, como el de mama, colorrectal, hígado, esófago o cavidad oral, y enfermedades cardiovasculares como la hipertensión, la miocardiopatía alcohólica o las arritmias. Por ello, la opción que asocia el alcohol con el cáncer de mama y los problemas cardiacos es la correcta. El cáncer de pulmón se relaciona fundamentalmente con el tabaco y no figura entre los cánceres atribuidos al alcohol. La relación del alcohol con la diabetes es menos directa y no se considera una de sus enfermedades causales principales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fbb") }, {"long_answer": "Según la evidencia en salud pública, las advertencias sanitarias en los envases de bebidas alcohólicas aumentan la concienciación de la población sobre los daños relacionados con el alcohol, como el cáncer o los riesgos durante el embarazo, y pueden contribuir a modificar actitudes y conductas, sobre todo cuando son visibles y se acompañan de otras medidas. Por tanto, no es cierto que carezcan de impacto. No existe evidencia de que aumenten la intención de beber. Calificarlas de incoherentes e inadecuadas no se corresponde con la evidencia, que respalda su utilidad como fuente de información clara."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fbd") }, {"long_answer": "En la evaluación rápida de riesgo del Ministerio de Sanidad sobre el brote de enfermedad por virus de Marburgo en Ruanda, la probabilidad de exposición e infección de las personas españolas que visitan o residen en el país se consideró baja, ya que la transmisión se produce por contacto directo con fluidos de personas enfermas o fallecidas, y los casos se concentraron sobre todo en personal sanitario y sus contactos. Para la población general que sigue las medidas de prevención el riesgo no es alto ni moderado. Tampoco puede considerarse nulo, porque existe transmisión activa en el país."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fc2") }, {"long_answer": "El documento técnico del Ministerio de Sanidad señala la higiene de manos como la medida más sencilla y eficaz para prevenir la transmisión de microorganismos, incluido el coronavirus, ya que las manos son el principal vehículo de transmisión por contacto. Puede hacerse con agua y jabón o con solución hidroalcohólica, y debe realizarse antes y después del contacto con el paciente o su entorno. La mascarilla, el distanciamiento y la desinfección de superficies son medidas complementarias útiles, pero no se consideran la medida básica más sencilla y eficaz, y ninguna sustituye a una correcta higiene de manos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fc5") }, {"long_answer": "El documento técnico del Ministerio de Sanidad sobre manejo domiciliario de la COVID-19 recomienda limpiar y desinfectar diariamente las superficies de contacto frecuente y el baño con lejía diluida en agua, preparada en el momento de su uso, utilizando guantes y manteniendo una buena ventilación. La lejía es un desinfectante eficaz y accesible frente al coronavirus. El agua y jabón sirven para la limpieza previa, pero no se plantean como desinfectante de elección. El alcohol común no es la opción indicada para grandes superficies ni para el baño, y la recomendación sí especifica el producto a emplear."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fe1") }, {"long_answer": "Para la temporada 2024-2025, la Comisión de Salud Pública del Consejo Interterritorial del SNS mantuvo como estrategia frente al VRS en población infantil la inmunización pasiva con nirsevimab, un anticuerpo monoclonal de vida media prolongada que se administra en dosis única y aporta anticuerpos ya formados, sin requerir respuesta inmunitaria del lactante. Por eso no es una inmunización activa, que es la que generan las vacunas. Las vacunas frente al VRS no estaban autorizadas para administrarse directamente a lactantes. La estrategia sí estaba claramente especificada en las recomendaciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fe5") }, {"long_answer": "Las recomendaciones del Ministerio de Sanidad indican que los nacidos durante la temporada de VRS deben recibir nirsevimab de forma muy precoz, preferentemente en las primeras 24-48 horas de vida, antes del alta de la maternidad, ya que el riesgo de hospitalización por bronquiolitis es máximo en los primeros meses. Esperar a que cumplan un mes los dejaría desprotegidos en el periodo de mayor vulnerabilidad. Las recomendaciones sí están especificadas y estos lactantes constituyen precisamente la población diana prioritaria, por lo que es falso que no puedan recibirlo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fe8") }, {"long_answer": "En los lactantes nacidos fuera de la temporada de VRS que forman parte de la población diana, las recomendaciones establecen inmunizar a la mayoría al principio de la temporada, idealmente en octubre, mediante campañas de captación activa, para que estén protegidos durante los meses de mayor circulación del virus, dado que nirsevimab proporciona protección durante al menos cinco meses. Inmunizar al final de la temporada sería ineficaz, porque la mayor parte de la exposición ya habría ocurrido. La recomendación sí está especificada, y no inmunizar a esta población la dejaría sin protección."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fe9") }, {"option_2": "Facturar el coste de la dosis a la familia del lactante", "long_answer": "Las recomendaciones del Ministerio de Sanidad indican que cada dosis de nirsevimab debe registrarse en el sistema de información de la comunidad autónoma para poder identificar a los lactantes no inmunizados y realizar acciones de captación activa cuando sea necesario, además de permitir el seguimiento de coberturas. La inmunización es gratuita, por lo que el registro no tiene finalidad de facturación a las familias. No sirve para garantizar la exención de dosis adicionales, y el registro en sí no reduce el riesgo de contagio, que depende de la administración del anticuerpo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fea") }, {"long_answer": "La vacuna frente al VRS administrada a la embarazada, habitualmente entre las semanas 24 y 36 de gestación, tiene como objetivo que la madre produzca anticuerpos que pasan al feto a través de la placenta, de modo que el lactante nace con protección pasiva frente a la enfermedad grave por VRS durante sus primeros meses de vida. Por tanto, su objetivo no es proteger exclusivamente a la madre ni exclusivamente al feto, sino reducir la enfermedad por VRS en el lactante tras el nacimiento. Además, es falso que no exista vacuna para embarazadas, ya que se dispone de una vacuna autorizada con esta indicación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fec") }, {"answer": 1, "long_answer": "Ante la escasez de dosis, el Ministerio de Sanidad recomendó administrar la vacuna frente a mpox (MVA-BN) por vía intradérmica a dosis de 0,1 ml en personas de 18 años o más, ya que esta pauta de ahorro de dosis genera una respuesta inmunitaria comparable a la de la vía subcutánea. En menores de 18 años, embarazadas y personas con inmunodepresión se mantiene la dosis completa de 0,5 ml por vía subcutánea. Por ello, es incorrecto administrar 0,1 ml por vía subcutánea, y tampoco se utilizan 0,5 ml por vía intradérmica en menores ni en personas inmunodeprimidas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fed") }, {"long_answer": "Las recomendaciones de vacunación frente a mpox priorizan la profilaxis preexposición en personas con prácticas sexuales de alto riesgo, principalmente hombres que tienen relaciones sexuales con hombres con múltiples parejas, ya que la transmisión durante el brote se ha producido sobre todo por contacto estrecho en el contexto sexual. También se incluye a determinado personal de laboratorio con riesgo ocupacional. Las personas inmunodeprimidas, la población infantil y las embarazadas no constituyen por sí mismas el grupo prioritario de preexposición, aunque pueden vacunarse en determinadas situaciones, por ejemplo tras una exposición."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fee") }, {"long_answer": "La vacunación posexposición frente a mpox se recomienda a los contactos estrechos de casos confirmados que no hayan pasado la enfermedad, administrando la vacuna lo antes posible, preferentemente en los primeros 4 días tras la exposición y hasta un máximo de 14 días, para prevenir la infección o atenuar su gravedad. Las personas inmunodeprimidas y las embarazadas pueden vacunarse si son contactos estrechos, pero no constituyen por sí mismas la indicación posexposición. El riesgo ocupacional se relaciona con la vacunación preexposición de determinados profesionales, no con la posexposición."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ff2") }, {"long_answer": "La Ley 28/2005 prohíbe vender o entregar productos del tabaco a menores de 18 años y hace responsable del cumplimiento de esta prohibición al punto de venta minorista, es decir, al titular del establecimiento o de la máquina expendedora, que debe comprobar la edad del comprador y, en caso de duda, exigir un documento acreditativo. El fabricante y el mayorista no realizan la venta directa al consumidor, por lo que no responden del incumplimiento en el momento de la dispensación. Al gobierno le corresponde la regulación y la inspección, pero no la responsabilidad por una venta concreta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ffb") }, {"long_answer": "Para prevenir errores con la medicación propia que el paciente trae al hospital, las recomendaciones de seguridad del paciente establecen que enfermería debe custodiarla, administrarla y registrarla adecuadamente, integrándola en el tratamiento prescrito y conciliándola con la orden médica, para evitar duplicidades, omisiones o interacciones. Prohibir que el paciente traiga su medicación o negar sistemáticamente su uso puede provocar interrupciones de tratamientos necesarios y no es la recomendación. Permitir que el paciente la tome por su cuenta, sin conocimiento del equipo, es precisamente una fuente de errores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ffd") }, {"long_answer": "Dentro del reto mundial Medicación sin Daño de la OMS, una de las recomendaciones para involucrar a pacientes y familiares en el uso seguro de los medicamentos es facilitarles herramientas que les ayuden a organizar y administrar sus tratamientos, como listas actualizadas de medicación, pastilleros, calendarios o aplicaciones, junto con información clara y comprensible. Proporcionar información confusa, limitar el acceso a la información sobre el tratamiento o no implicarles en las decisiones contradice el principio de participación activa del paciente, que es una barrera esencial frente a los errores de medicación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977006") }, {"long_answer": "Cuando, al escuchar las observaciones de pacientes o familiares, los profesionales identifican un posible error de medicación, deben tomar medidas inmediatas para solventarlo, verificar la prescripción y comunicar o notificar el incidente, ya que la participación del paciente es una barrera eficaz para detectar errores antes de que causen daño. Ignorar las observaciones o esperar a que el error produzca daño es contrario a la cultura de seguridad. Tomar decisiones sin coordinarse con el resto del equipo tampoco es adecuado, porque la resolución del error requiere comunicación entre profesionales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977007") }, {"long_answer": "Si los pacientes, familiares o cuidadores perciben que la dosis de su medicación puede ser errónea, deben comunicarlo a los profesionales sanitarios antes de administrarla, ya que su participación activa constituye una barrera eficaz para detectar errores de medicación, tal como promueve el reto Medicación sin Daño de la OMS. Ignorar la sospecha para evitar problemas o esperar a que el error cause daño puede tener consecuencias graves. Modificar la dosis por su cuenta, sin consultar a los profesionales, también es peligroso, porque puede introducir un nuevo error en lugar de corregirlo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977009") }, {"long_answer": "Los medicamentos sobrantes o caducados deben devolverse a la farmacia, donde existen puntos de recogida específicos, como los puntos SIGRE, que garantizan su correcta gestión y eliminación sin riesgo para el medio ambiente. Tirarlos a la basura común o por el desagüe contamina el entorno y facilita su uso indebido. Entregarlos a otros pacientes es peligroso, porque puede provocar errores, reacciones adversas o el uso de fármacos no indicados. Comunicar la situación a los profesionales puede ser útil en algunos casos, pero no resuelve la eliminación segura de los medicamentos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97700a") }, {"option_4": "Retirar la hoja de tratamiento al paciente para evitar confusiones", "long_answer": "Para fomentar la participación de los pacientes en la supervisión de su tratamiento, los profesionales sanitarios les proporcionan una lista actualizada con los medicamentos prescritos, con su dosis, pauta y finalidad, de modo que puedan comprobar lo que reciben, detectar discrepancias y compartir la información en las transiciones asistenciales. Limitar el acceso a la información, desalentar su participación en la continuidad del tratamiento o retirarles la hoja de tratamiento dificulta la detección de errores y es contrario a las recomendaciones de seguridad del paciente, que consideran al paciente informado una barrera frente a los errores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977014") }, {"option_3": "Eliminar por completo las amputaciones en personas con diabetes en un plazo de dos años", "long_answer": "La Estrategia en Diabetes del SNS, en su actualización de 2012, incluye entre sus objetivos relacionados con las complicaciones facilitar la detección precoz del pie diabético, mediante la exploración periódica de los pies y la estratificación del riesgo en atención primaria, para prevenir úlceras y amputaciones. Eliminar por completo las amputaciones en dos años no es un objetivo realista ni figura en la Estrategia. La realización de un número concreto de campañas no se plantea como objetivo. Tampoco es cierto que el documento no mencione el pie diabético, al que dedica atención específica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977023") }, {"long_answer": "Si durante una hemólisis aguda en hemodiálisis el paciente presenta disnea, la primera medida urgente es administrar oxígeno, ya que la hemólisis reduce la capacidad de transporte de oxígeno y puede acompañarse de hiperpotasemia, dolor torácico e inestabilidad. A continuación se detiene la sesión sin retornar la sangre, se avisa al nefrólogo y se extraen analíticas. La radiografía de tórax no es una medida urgente prioritaria y retrasaría el tratamiento. Tomar la presión arterial forma parte de la monitorización, pero no corrige la hipoxemia, y los analgésicos no tratan la causa de la disnea."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977024") }, {"long_answer": "Ante una hemólisis aguda durante la hemodiálisis, antes de retirar el circuito extracorpóreo debe examinarse en busca de factores causales, como acodaduras o estrechamientos de las líneas, agujas inadecuadas, temperatura excesiva o conductividad incorrecta del líquido de diálisis, o contaminación del agua. Identificar la causa permite corregirla y evitar nuevos episodios en este y otros pacientes. Retirarlo de inmediato sin revisarlo impide conocer el origen del problema. Consultar al paciente no aporta información sobre el funcionamiento del circuito, y la ecocardiografía no tiene relación con la investigación de la causa de la hemólisis."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977027") }, {"answer": 3, "long_answer": "El Plan de Acción Europeo para el Ictus 2018-2030 establece cuatro objetivos generales: reducir el número absoluto de ictus en Europa en un 10 %, tratar al 90 % o más de los pacientes en una unidad de ictus como primer nivel de atención, disponer de planes nacionales de ictus que abarquen toda la cadena asistencial, desde la prevención primaria hasta la vida después del ictus, e implementar plenamente estrategias nacionales de intervenciones multisectoriales de salud pública. Por ello, reducir el número de ictus un 20 % o tratar al 100 % en una unidad de ictus no son las cifras del plan, y las estrategias de prevención que propone son nacionales, no internacionales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977028") }, {"long_answer": "La Estrategia en Ictus del Sistema Nacional de Salud incluye entre sus líneas y objetivos promover la salud y la prevención primaria, actuando sobre los factores de riesgo vascular y los estilos de vida para reducir la incidencia de ictus, junto con la mejora de la atención en fase aguda, la rehabilitación y la vida después del ictus. Las opciones que hablan de reducir el número de ictus en Europa o de tratar al 90 % de los pacientes europeos en unidades de ictus corresponden al Plan de Acción Europeo, no a la Estrategia nacional, y la implementación de intervenciones multisectoriales es otro de los objetivos generales del plan europeo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97702c") }, {"long_answer": "La hipertensión arterial es la principal causa de la hemorragia intracerebral primaria, ya que produce lesiones degenerativas en las pequeñas arterias perforantes profundas que acaban rompiéndose, típicamente en ganglios basales, tálamo, protuberancia y cerebelo. La aterosclerosis se asocia sobre todo al ictus isquémico. Las coagulopatías, incluidas las secundarias a anticoagulantes, son causa de hemorragias, pero mucho menos frecuente que la hipertensión. El infarto cerebral es un ictus isquémico y, aunque puede sufrir transformación hemorrágica, no constituye la causa de la hemorragia primaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97702e") }, {"option_3": "Cefalea intensa de inicio brusco", "answer": 3, "long_answer": "La cefalea intensa de inicio brusco, especialmente si se acompaña de vómitos, disminución del nivel de conciencia y cifras de presión arterial muy elevadas, orienta a un ictus hemorrágico, aunque el diagnóstico de certeza requiere neuroimagen urgente. La pérdida de sensibilidad u hormigueo es un síntoma deficitario que puede aparecer tanto en ictus isquémicos como hemorrágicos y no orienta hacia ninguno de ellos. La pérdida súbita de visión monocular sugiere isquemia retiniana de origen carotídeo. Una presión arterial normal no orienta a hemorragia, que suele cursar con hipertensión marcada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977032") }, {"long_answer": "Los factores de riesgo de ictus no modificables son aquellos sobre los que no se puede intervenir: la edad, que es el principal, el sexo, los antecedentes familiares de enfermedad cardiovascular y de ictus en familiares de primer grado, y otros como la raza o etnia y factores genéticos. Su identificación permite reconocer a las personas con mayor riesgo. El tabaquismo, el alcohol, la dieta rica en grasas, la inactividad física, la hipertensión, la diabetes, la obesidad, la dislipemia o el consumo de drogas son factores de riesgo modificables, sobre los que actúan la prevención primaria y secundaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977035") }, {"long_answer": "El consumo de tabaco incrementa el riesgo de enfermedad cerebrovascular porque favorece la formación de trombos, al aumentar la agregación plaquetaria y la coagulabilidad, y acelera la aterosclerosis por daño endotelial, inflamación y alteración del perfil lipídico. El riesgo es dosis dependiente y disminuye progresivamente tras dejar de fumar, por lo que el abandono del tabaco es una medida prioritaria en la prevención del ictus. Afirmar que no tiene efecto o que reduce el riesgo es falso, y el tabaco disminuye la esperanza de vida en lugar de aumentarla."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977039") }, {"long_answer": "Las unidades de ictus son áreas hospitalarias específicas, atendidas por un equipo multidisciplinar con neurólogos y enfermería entrenada, que proporcionan monitorización continua no invasiva y cuidados especializados a los pacientes con ictus agudo, detectando precozmente complicaciones y aplicando protocolos de tratamiento y movilización precoz. Han demostrado reducir la mortalidad y la dependencia. No están destinadas a cuidados paliativos, aunque puedan aplicarse si son necesarios. No son unidades de procedimientos quirúrgicos invasivos, y su aportación va más allá de administrar tratamientos médicos generales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97703a") }, {"long_answer": "La viabilidad del área de penumbra en el ictus isquémico depende de que se mantenga un aporte de oxígeno suficiente, que llega principalmente a través de la circulación colateral, y del tiempo transcurrido, ya que el tejido que recibe un flujo reducido puede recuperarse si se restablece la perfusión, pero evoluciona hacia infarto si la hipoxia se prolonga. El tamaño del núcleo isquémico refleja el tejido ya perdido, no el que puede salvarse. La presión arterial sistémica y la temperatura corporal influyen en la evolución del daño cerebral, pero no son los factores determinantes de la viabilidad de la penumbra."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97703b") }, {"long_answer": "El objetivo principal de las terapias de recanalización arterial en el ictus isquémico, como la trombólisis intravenosa y la trombectomía mecánica, es alcanzar la reperfusión del tejido isquémico, restableciendo el flujo sanguíneo en la arteria ocluida para salvar el área de penumbra y limitar la extensión del infarto. Evitar el daño cerebral secundario es una consecuencia de la reperfusión y un objetivo de los cuidados generales, no la finalidad específica de estas terapias. Optimizar la circulación colateral o reducir la presión arterial sistémica no son sus objetivos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977040") }, {"long_answer": "Según los datos recogidos en la Estrategia en Ictus del SNS, la tasa de trombectomías mecánicas en España alcanzó en 2022 aproximadamente 17,1 procedimientos por cada 100.000 habitantes, reflejando la importante expansión de este tratamiento gracias a la organización del Código Ictus y de las redes de centros con neurointervencionismo, aunque con diferencias entre comunidades autónomas. Las cifras de 4,6 u 8,1 por 100.000 corresponden a niveles propios de años anteriores, con menor implantación de la técnica, y la cifra de 10 tampoco coincide con la tasa alcanzada en 2022."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977045") }, {"long_answer": "El daño cerebral diferido, también llamado isquemia cerebral diferida, es una de las complicaciones más temidas tras una hemorragia subaracnoidea aneurismática, porque aparece habitualmente entre el 4.º y el 14.º día, se relaciona con el vasoespasmo y otros mecanismos, y es la principal causa de morbilidad y mortalidad en los pacientes que sobreviven al sangrado inicial. Las crisis epilépticas, la hidrocefalia aguda y el estatus no convulsivo son también complicaciones posibles de la hemorragia subaracnoidea, pero tienen menor repercusión pronóstica global o pueden tratarse eficazmente, por lo que no se consideran la complicación más temida."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977047") }, {"option_1": "Inducción de hipotensión arterial controlada", "answer": 3, "long_answer": "En la profilaxis del daño cerebral diferido tras una hemorragia subaracnoidea aneurismática, la recomendación con mayor evidencia es el tratamiento con nimodipino oral, un calcioantagonista que ha demostrado mejorar el pronóstico funcional, junto con el mantenimiento de la euvolemia. La hipotensión inducida es perjudicial, ya que reduce la perfusión cerebral en un cerebro vulnerable a la isquemia. La hipervolemia profiláctica no aporta beneficio y aumenta las complicaciones. Los antagonistas de la endotelina 1, como el clazosentán, reducen el vasoespasmo angiográfico pero no han demostrado mejorar los resultados clínicos, por lo que no se recomiendan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97704c") }, {"long_answer": "El Código Ictus es un procedimiento de actuación prehospitalario e intrahospitalario que permite identificar rápidamente a los pacientes con ictus en fase hiperaguda candidatos a tratamiento de reperfusión, priorizar su atención y trasladarlos al centro adecuado, alertando previamente al equipo de ictus para reducir los tiempos. No es solo un protocolo diagnóstico, aunque incluye la valoración clínica y de neuroimagen. Tampoco es un tratamiento en sí mismo, sino el sistema que facilita su aplicación, ni una unidad física especializada, que corresponde a la unidad de ictus."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97704d") }, {"option_1": "Realizar exclusivamente intervenciones neuroquirúrgicas", "option_2": "Proporcionar rehabilitación a largo plazo durante varios meses", "option_4": "Sustituir el seguimiento posterior en Atención Primaria", "long_answer": "La principal finalidad del ingreso en una unidad de ictus es ofrecer cuidados generales protocolizados y tratamientos dirigidos a prevenir y detectar precozmente las complicaciones neurológicas y sistémicas, mediante monitorización continua, control de constantes, glucemia, temperatura, deglución y movilización precoz, aplicados por personal especializado. Esto ha demostrado reducir la mortalidad y la dependencia. La unidad de ictus no es un área de intervenciones neuroquirúrgicas exclusivas. Tampoco proporciona rehabilitación prolongada durante meses, que se realiza en otros dispositivos, ni sustituye el seguimiento posterior en Atención Primaria, con el que debe coordinarse."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977055") }, {"option_2": "Limitar la información al alta a los pacientes que la soliciten por escrito", "option_3": "Restringir los cuidados paliativos a los pacientes con enfermedad oncológica", "option_4": "Evaluar los indicadores de la Estrategia únicamente cada diez años", "long_answer": "Entre las recomendaciones de la Estrategia en Ictus del SNS figura promover la formación continuada y específica en enfermedades cerebrovasculares de todos los profesionales implicados en la atención al ictus, ya que la capacitación del equipo mejora la calidad asistencial y los resultados. Limitar la información al alta a quien la solicite por escrito es contrario a la recomendación de informar a todos los pacientes y allegados de forma integral. Restringir los cuidados paliativos a pacientes oncológicos impediría su acceso a los pacientes con ictus que los necesitan, y evaluar los indicadores solo cada diez años es insuficiente para un seguimiento útil."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977057") }, {"long_answer": "Tras un ictus, el cerebro pone en marcha mecanismos de plasticidad neuronal que permiten la recuperación funcional. Después de la fase aguda, en la que predominan la resolución del edema y la recuperación de la penumbra, entre las 2 y 4 semanas se observa una reorganización de las redes neuronales, con reclutamiento de áreas perilesionales y contralaterales, lo que abre una ventana especialmente favorable para la rehabilitación intensiva. A las 24-48 horas predominan aún los fenómenos agudos, en la primera o segunda semana comienzan los procesos de reparación, y entre las 4 y 8 semanas la recuperación continúa, pero la reorganización ya se ha iniciado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977058") }, {"long_answer": "La pérdida de función motora, en forma de hemiparesia o hemiplejía, es el déficit más frecuente tras un ictus y la principal causa de dependencia para las actividades de la vida diaria, por lo que es el foco principal de la rehabilitación. También son frecuentes las alteraciones del lenguaje, la disfagia y los trastornos cognitivos. La pérdida de memoria puede aparecer, pero es menos frecuente que el déficit motor. La pérdida de visión, como la hemianopsia, se presenta en una proporción menor de pacientes, y la pérdida de audición es rara."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97705c") }, {"long_answer": "El objetivo principal de la prevención secundaria del ictus y el AIT en la Estrategia en Ictus del SNS es asegurar que todos los pacientes con ictus isquémico, hemorrágico o AIT accedan a estrategias de prevención y tratamientos de los factores de riesgo vascular basados en la evidencia científica, para reducir las recurrencias. El acceso a pruebas diagnósticas, los programas de seguimiento en Atención Primaria y Comunitaria o el registro de hemorragias en pacientes anticoagulados son medidas concretas que contribuyen a ese fin, pero no constituyen el objetivo principal de la prevención secundaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97705d") }, {"long_answer": "La Estrategia en Ictus del SNS recomienda que el seguimiento tras un ictus o AIT en consultas externas de Neurología se dirija a los pacientes con mayor riesgo de recidiva o que precisan estudios diagnósticos o tratamientos más complejos, mientras que el resto puede seguirse de forma coordinada en Atención Primaria. No es cierto que no sea necesario ningún seguimiento específico, ya que el riesgo de recurrencia es elevado. Limitarlo a ictus criptogénicos o a pacientes revascularizados resulta demasiado restrictivo, porque excluiría a otros pacientes de alto riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97705e") }, {"option_2": "Hipertensión arterial", "answer": 2, "long_answer": "La hipertensión arterial es el factor de riesgo más importante de la hemorragia intracerebral, tanto por su prevalencia como por su potencia, ya que produce lipohialinosis y microaneurismas en las arterias perforantes profundas que acaban rompiéndose. Su control es la medida preventiva más eficaz. La edad avanzada aumenta el riesgo, sobre todo por angiopatía amiloide, pero no supera a la hipertensión. El tabaco y el consumo excesivo de alcohol también incrementan el riesgo de sangrado, aunque en menor medida, por lo que no son el factor principal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97706a") }, {"long_answer": "La evidencia muestra que el uso restringido de la episiotomía, frente a su práctica rutinaria, reduce el riesgo de traumatismo perineal posterior grave, disminuye la necesidad de sutura y las complicaciones de la cicatrización, sin aumentar el traumatismo perineal grave, por lo que las guías desaconsejan la episiotomía sistemática. Por ello, es falso que el uso restringido aumente el traumatismo perineal posterior o provoque más complicaciones en la cicatrización. La menor necesidad de sutura es también un beneficio, pero el efecto clave descrito en la pregunta es la reducción del traumatismo perineal posterior."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97706f") }, {"long_answer": "La revisión Cochrane sobre las posiciones maternas durante el periodo expulsivo analizó ensayos clínicos que comparaban las posiciones verticales o lateralizadas con la posición supina o de litotomía en mujeres sin anestesia epidural. Sus resultados mostraron una ligera reducción de los partos instrumentales y episiotomías y menos alteraciones de la frecuencia cardiaca fetal, a costa de un posible aumento de desgarros de segundo grado y de pérdida hemática. Por tanto, no se centró en el dolor del parto, en los métodos de parto en general ni en las complicaciones posparto como objeto principal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977072") }, {"long_answer": "La Estrategia de atención al parto normal y la guía de práctica clínica recomiendan evitar la práctica rutinaria del rasurado perineal en las mujeres de parto, ya que no ha demostrado reducir las infecciones ni facilitar la sutura y, en cambio, produce molestias, irritación y microlesiones cutáneas. Si se considera necesario para suturar, puede recortarse el vello de forma puntual. Por ello, no está indicado el rasurado rutinario, completo o parcial, en todas las gestantes. Tampoco se plantea como una práctica a demanda, sino que la recomendación general es no realizarlo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977073") }, {"long_answer": "La Estrategia de atención al parto normal recomienda permitir y alentar a todas las mujeres a contar con personas de apoyo de su elección durante todo el proceso del parto, ya que el acompañamiento continuo reduce la necesidad de analgesia y de partos instrumentales, aumenta la probabilidad de parto vaginal espontáneo y mejora la satisfacción materna. No permitir el acompañamiento, restringirlo a la fase final del parto o impedir la presencia de personas ajenas al personal sanitario va en contra de esta recomendación y priva a la mujer de sus beneficios demostrados."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977078") }, {"long_answer": "La Estrategia de atención al parto normal recomienda que la criatura recién nacida sana permanezca en contacto piel con piel con su madre inmediatamente tras el parto y de forma ininterrumpida, al menos durante 70 minutos, ya que este periodo favorece el inicio espontáneo de la lactancia materna, la termorregulación, la estabilidad cardiorrespiratoria y el establecimiento del vínculo. Separar al recién nacido de su madre inmediatamente o impedir el contacto en las primeras horas interfiere con estos beneficios. Considerar que el contacto piel con piel carece de importancia contradice la evidencia disponible."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97707d") }, {"long_answer": "Para que las usuarias puedan participar en la toma de decisiones sobre su atención, la Estrategia de atención al parto normal establece que deben recibir información basada en evidencias documentadas, clara y comprensible, sobre los beneficios, riesgos y alternativas de cada práctica. Solo así pueden elegir de forma libre e informada. La información sesgada a favor de determinadas prácticas médicas limita la autonomía de la mujer. La información general y sin detalles no permite valorar las opciones, y la procedente de fuentes no confiables puede inducir a decisiones erróneas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977083") }, {"long_answer": "La toma de decisiones conjunta entre usuarias y profesionales requiere incluir las preferencias, valores y expectativas de las usuarias junto con la mejor evidencia disponible y la experiencia profesional, de modo que la decisión final sea compartida y respete su autonomía. Proporcionar información sin evidencias documentadas impide decidir con fundamento. No tener en cuenta las preferencias de las usuarias supone volver a un modelo paternalista, contrario al enfoque de la Estrategia de atención al parto normal, e impedir la comunicación entre usuarias y profesionales hace imposible cualquier decisión compartida."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97708b") }, {"long_answer": "Se recomienda cuestionar y observar con mirada crítica cualquier información sobre salud y atención al parto procedente de los medios de comunicación, contrastándola con fuentes fiables y con los profesionales sanitarios, ya que puede estar simplificada, sesgada o responder a intereses comerciales. Esta actitud crítica es necesaria para que las mujeres tomen decisiones informadas. Por el contrario, confiar sin más en la veracidad de la información, no cuestionarla o aceptarla sin dudar expone a las usuarias a mensajes erróneos o incompletos que pueden influir negativamente en sus decisiones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97708c") }, {"long_answer": "La participación de las mujeres en la toma de decisiones sobre su atención sanitaria busca sustituir el modelo paternalista tradicional por un modelo de alianza, consenso y responsabilidad compartida entre la usuaria y los profesionales, en el que la mujer, adecuadamente informada, decide junto al equipo sobre su proceso asistencial. Adoptar o mantener el modelo paternalista, en el que el profesional decide unilateralmente, es lo contrario de lo que se pretende. No cambiar el modelo de relación o excluir a las mujeres de la toma de decisiones vulneraría su autonomía y sus derechos como usuarias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977092") }, {"question": "¿Cuál de los siguientes motivos se ha utilizado tradicionalmente para justificar el rasurado del periné durante el trabajo de parto?", "option_1": "Acelerar la dilatación cervical", "long_answer": "Tradicionalmente, el rasurado del periné durante el trabajo de parto se justificaba por la supuesta facilidad que aportaba para suturar el periné en caso de desgarro o episiotomía, además de una presunta mejora de la higiene. La evidencia ha demostrado que no aporta beneficios y causa molestias, por lo que actualmente no se recomienda de forma rutinaria. El rasurado no tiene ningún efecto sobre la dilatación cervical. Tampoco se ha planteado para reducir el crecimiento del vello ni guarda relación alguna con la necesidad de analgesia durante el parto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977096") }, {"long_answer": "La revisión Cochrane sobre el apoyo continuo durante el parto mostró que las mujeres que lo recibían tenían menor probabilidad de recibir analgesia o anestesia regional, más partos vaginales espontáneos, menos partos instrumentales y cesáreas, partos algo más cortos y mayor satisfacción con la experiencia. Por tanto, es falso que aumente la tendencia a la cesárea. No se demostró un uso mayor de oxitocina, y el efecto sobre la depresión posparto no fue concluyente, por lo que el resultado más claro entre las opciones es la menor necesidad de analgesia regional."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977099") }, {"long_answer": "La evidencia disponible no apoya la realización de amniotomía precoz de rutina en los partos que progresan con normalidad, ya que no acorta de forma relevante la duración del parto ni mejora los resultados maternos o neonatales, y puede aumentar el riesgo de alteraciones de la frecuencia cardiaca fetal, infección y prolapso de cordón. Por ello, la Estrategia de atención al parto normal desaconseja su uso sistemático. Realizarla en todos los partos es contrario a la recomendación. Tampoco se establece hacerla solo a demanda de la mujer o solo en embarazos de alto riesgo, sino únicamente cuando exista una indicación clínica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97709b") }, {"option_1": "Episiotomía y acupuntura", "option_3": "Oxitocina y masajes", "option_4": "Petidina y música", "long_answer": "Entre los métodos no farmacológicos para el alivio del dolor durante el parto que recoge la guía de práctica clínica figuran la inmersión en agua caliente durante la fase de dilatación y la acupuntura, además de otros como el masaje o las técnicas de relajación. Ambos reducen la percepción del dolor y la necesidad de analgesia sin efectos adversos relevantes. Las demás opciones combinan un método no farmacológico con una intervención que no lo es: la episiotomía es un procedimiento quirúrgico, la oxitocina es un fármaco para estimular las contracciones y la petidina es un opioide."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97709e") }, {"option_1": "Reducción de la cartera de servicios de Atención Primaria", "option_3": "Centralización de toda la atención en hospitales terciarios", "option_4": "Supresión de los programas de rehabilitación cardiaca", "long_answer": "Uno de los ámbitos de actuación prioritarios de la Estrategia en Salud Cardiovascular del SNS es la promoción de la salud, la prevención de la enfermedad y la detección precoz, dado que gran parte de la enfermedad cardiovascular puede evitarse actuando sobre factores de riesgo como el tabaco, la hipertensión, la dislipemia o el sedentarismo. La Estrategia refuerza el papel de la Atención Primaria, por lo que reducir su cartera de servicios sería contrario a sus objetivos. Tampoco plantea centralizar toda la atención en hospitales terciarios ni suprimir la rehabilitación cardiaca, que considera una intervención clave de prevención secundaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770a1") }, {"long_answer": "Según los datos recogidos en la Estrategia en Salud Cardiovascular del SNS, la prevalencia de enfermedades cardiovasculares en España en 2019 se situó en torno al 9,8 % de la población total, lo que las convierte en uno de los principales problemas de salud y la primera causa de muerte en el país. Esta cifra engloba patologías como la cardiopatía isquémica, la enfermedad cerebrovascular, la insuficiencia cardiaca o las arritmias. Las cifras del 5,7 % infraestiman la carga real, mientras que el 12,3 % y el 16,5 % no corresponden a la prevalencia registrada para la población total en 2019."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770a8") }, {"long_answer": "La Estrategia en Salud Cardiovascular, al analizar las desigualdades de género, señala el estrés laboral, junto con la sobrecarga de cuidados y la doble jornada, como uno de los estresores crónicos que deterioran la salud cardiovascular de las mujeres, al activar de forma mantenida la respuesta neuroendocrina al estrés y favorecer la hipertensión y otros factores de riesgo. El sedentarismo, el consumo de tabaco y la mala alimentación son factores de riesgo cardiovascular relacionados con el estilo de vida, pero no se consideran estresores crónicos psicosociales, que es lo que plantea la pregunta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770aa") }, {"long_answer": "La Estrategia en Salud Cardiovascular recoge que alrededor del 45 % de las mujeres cancela o retrasa sus citas médicas debido al estigma social asociado al sobrepeso, por miedo a ser juzgadas o a recibir comentarios sobre su peso. Este fenómeno dificulta la detección precoz y el seguimiento de los factores de riesgo cardiovascular en las mujeres y pone de manifiesto la necesidad de una atención libre de estigma. Las cifras del 15 %, 25 % o 35 % infraestiman la magnitud de este problema según los datos que recoge la Estrategia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770ae") }, {"long_answer": "La Estrategia en Salud Cardiovascular identifica el estigma social del sobrepeso como uno de los factores que dificultan el acceso de las mujeres al sistema sanitario, ya que muchas retrasan o evitan las consultas por temor a ser juzgadas por su peso, lo que retrasa la detección y el control de los factores de riesgo. En el contexto del Sistema Nacional de Salud, de cobertura universal, la falta de seguro médico no es la barrera señalada. La falta de instalaciones en áreas rurales o de educación sanitaria pueden influir en el acceso, pero no son el factor específico de género que destaca el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770b0") }, {"long_answer": "Según la Estrategia en Salud Cardiovascular del SNS, la incidencia de cardiopatía isquémica en España en 2019 fue de aproximadamente 361,4 nuevos casos por cada 100.000 habitantes, siendo mayor en hombres y aumentando claramente con la edad. La incidencia se expresa como número de casos nuevos por población en un periodo, por lo que las opciones expresadas como porcentaje de la población adulta, que corresponderían a prevalencia, o como proporción de las muertes por enfermedad cardiovascular, que es un dato de mortalidad, no responden a la pregunta. La cifra de 278 casos por 100.000 no coincide con la incidencia registrada en 2019."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770b1") }, {"question": "Según la Estrategia en Salud Cardiovascular del SNS, ¿cuál era aproximadamente la prevalencia de cardiopatía isquémica en España en 2019?", "option_1": "0,3 %", "option_2": "3,3 %", "option_3": "13 %", "option_4": "25 %", "long_answer": "La Estrategia en Salud Cardiovascular del SNS recoge que la prevalencia de cardiopatía isquémica en España en 2019 fue de aproximadamente el 3,3 %, con un aumento respecto a la década anterior que se explica en parte por el envejecimiento de la población y la mayor supervivencia tras los eventos coronarios, y con cifras más altas en hombres que en mujeres. Un 0,3 % infraestimaría claramente su frecuencia, mientras que el 13 % o el 25 % corresponden a órdenes de magnitud propios de factores de riesgo como la hipertensión o la dislipemia, no a la cardiopatía isquémica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770b2") }, {"long_answer": "Según los datos de la Estrategia en Salud Cardiovascular del SNS, la tasa de incidencia global de cardiopatía isquémica en las personas de 70 y más años es de aproximadamente 1.415,4 casos por 100.000 habitantes, muy superior a la de los grupos de menor edad, ya que el envejecimiento acumula la exposición a factores de riesgo y la progresión de la aterosclerosis. La cifra de 485,5 corresponde a un grupo de edad más joven o a un subgrupo con menor incidencia, mientras que 1.773,2 y 1.160,6 se aproximan a los valores desagregados por sexo, más altos en hombres y más bajos en mujeres, y no a la tasa global."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770b4") }, {"long_answer": "La Estrategia en Salud Cardiovascular describe una brecha de género en el tratamiento del síndrome coronario agudo: en 2015, el 43 % de las mujeres y el 23 % de los hombres no recibieron ningún tipo de reperfusión. Esta diferencia se relaciona con la presentación clínica atípica, la mayor edad y comorbilidad de las mujeres y sesgos en la atención, no con diferencias fisiológicas. Por ello, no es cierto que los hombres recibieran menos intervencionismo coronario percutáneo ni que las mujeres recibieran más en todos los grupos de edad, y tampoco que la tasa de reperfusión fuese igual en ambos sexos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770b5") }, {"option_1": "Realizar coronariografía inmediata, en menos de 2 horas, en los pacientes de muy alto riesgo", "option_2": "Realizar coronariografía en las primeras 24 horas solo en los pacientes de bajo riesgo", "option_4": "Diferir siempre la coronariografía más allá de la primera semana", "long_answer": "Las guías de práctica clínica recomiendan en el SCASEST una estrategia invasiva adaptada al riesgo: coronariografía inmediata, en menos de 2 horas, en los pacientes de muy alto riesgo, como los que presentan inestabilidad hemodinámica, arritmias graves o dolor refractario, y precoz, en las primeras 24 horas, en los de alto riesgo. Los pacientes de bajo riesgo pueden manejarse con una estrategia invasiva selectiva, por lo que limitar la coronariografía precoz a ellos es incorrecto. Es falso que no se recomiende en ningún caso, y diferirla siempre más allá de una semana retrasaría el tratamiento en los pacientes que más se benefician."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770b6") }, {"long_answer": "La Estrategia en Salud Cardiovascular considera que el desarrollo de cuidados individuales y familiares desde las consultas de medicina y enfermería de Atención Primaria contribuye a mejorar los resultados en salud de los pacientes con cardiopatía isquémica, al favorecer el control de factores de riesgo, la adherencia terapéutica, el autocuidado y la implicación de la familia de forma continuada. Limitar el seguimiento a seis meses tras el alta es insuficiente para una enfermedad crónica. El empoderamiento no debe restringirse al periodo de hospitalización, y los cuidados no deben realizarse exclusivamente desde enfermería, sino de forma coordinada entre ambos profesionales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770be") }, {"option_1": "Organizar la asistencia a la insuficiencia cardiaca mediante unidades multidisciplinares", "long_answer": "Entre los puntos críticos que la Estrategia en Salud Cardiovascular asocia a la cardiopatía isquémica figura desarrollar programas de rehabilitación cardiaca y prevención secundaria, tanto hospitalarios como en Atención Primaria, adaptados al riesgo de cada paciente, ya que reducen la mortalidad y los reingresos y siguen estando infrautilizados. La organización de la asistencia en unidades multidisciplinares corresponde a la insuficiencia cardiaca. El diagnóstico precoz de la fibrilación auricular es un punto crítico del área de arritmias, y la valoración multidisciplinar de la estenosis aórtica grave pertenece al área de valvulopatías."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770c1") }, {"option_3": "Optimizar la selección del tratamiento de la estenosis aórtica grave mediante valoración multidisciplinar", "long_answer": "En el área de arritmias, la Estrategia en Salud Cardiovascular señala como punto crítico mejorar la efectividad en el acceso a la reanimación cardiopulmonar, ya que la muerte súbita por arritmias ventriculares requiere una respuesta inmediata con desfibrilación precoz y formación de la población en soporte vital. La organización de la asistencia en unidades multidisciplinares corresponde a la insuficiencia cardiaca. La valoración multidisciplinar de la estenosis aórtica grave pertenece al área de valvulopatías, y la mejora de las redes asistenciales del síndrome coronario agudo corresponde a la cardiopatía isquémica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fc9") }, {"long_answer": "La enfermedad meningocócica invasiva suele presentarse de forma brusca con fiebre, náuseas o vómitos, cefalea intensa y fotofobia, a los que pueden sumarse rigidez de nuca, alteración del nivel de conciencia y un exantema petequial o purpúrico característico de la sepsis meningocócica. Su evolución puede ser muy rápida, por lo que requiere tratamiento antibiótico urgente. El dolor abdominal con tos intensa no es el cuadro típico. Las combinaciones de cefalea con escalofríos y dolor de garganta, o de dolor ocular con fatiga y mialgias, son inespecíficas y propias de infecciones virales leves."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fcd") }, {"long_answer": "La vacuna tetravalente conjugada frente a meningococo ACWY se incorporó al calendario común de vacunación en la adolescencia para mantener la protección frente al serogrupo C, que ya se incluía en el calendario, y ampliarla frente a los serogrupos A, W e Y, ante el aumento de casos por los serogrupos W e Y en España y Europa. Los adolescentes son además los principales portadores, por lo que su vacunación favorece la inmunidad de grupo. El serogrupo B no está incluido en esta vacuna. Es falso que se hayan eliminado los casos de meningitis y que no exista una razón clara para la decisión."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fd4") }, {"long_answer": "En la temporada 2024, la vigilancia de la fiebre del Nilo Occidental en España identificó el linaje 2 del virus en la provincia de Jaén, un hallazgo relevante porque en Andalucía los brotes previos, como el de 2020, se habían asociado al linaje 1. El linaje 2 circula ampliamente en el centro y este de Europa y se relaciona con brotes con casos neuroinvasivos, por lo que su detección refuerza la necesidad de vigilancia entomológica, aviar y humana. Los linajes 3 y 4 son minoritarios y no se han asociado a la circulación del virus en esta provincia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fd9") }, {"option_1": "Tos y rinorrea", "option_2": "Exantema, especialmente anogenital, y fiebre", "option_4": "Diarrea y vómitos", "long_answer": "En los casos confirmados de mpox notificados en España durante el brote, el síntoma más frecuente fue el exantema, con lesiones vesiculopustulosas localizadas principalmente en la región anogenital, seguido de la fiebre, acompañados con frecuencia de linfadenopatías, astenia, cefalea y mialgias. La tos y la rinorrea no son manifestaciones características de la enfermedad. El dolor de garganta y el cansancio pueden aparecer, pero son síntomas inespecíficos y menos frecuentes que el exantema. La diarrea y los vómitos tampoco figuran entre los síntomas más comunes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fda") }, {"long_answer": "Durante el brote de mpox iniciado en 2022, la principal vía de transmisión ha sido el contacto estrecho piel con piel con las lesiones de una persona infectada en el contexto de las relaciones sexuales, sobre todo entre hombres que tienen sexo con hombres con múltiples parejas. El contacto con objetos contaminados, como ropa de cama o toallas, es posible pero secundario. La transmisión aérea a distancia no es una vía relevante, ya que la respiratoria requiere contacto cara a cara prolongado. La transmisión por transfusión sanguínea no se ha documentado como vía significativa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fdb") }, {"long_answer": "Ante la sospecha de haber tenido contacto con una persona con mpox, se aconseja contactar con los servicios sanitarios lo antes posible para valorar la exposición, recibir indicaciones de vigilancia de síntomas durante 21 días y, si procede, la vacunación posexposición, que es más eficaz cuanto antes se administre. Esperar a que aparezcan y se resuelvan los síntomas retrasa el diagnóstico y favorece la transmisión. No hacer nada por considerar la enfermedad leve es incorrecto, ya que puede ser grave en personas vulnerables. Los medicamentos de venta libre no previenen la infección."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fe4") }, {"long_answer": "Las recomendaciones del Ministerio de Sanidad establecen que nirsevimab se administre antes del inicio de cada temporada de VRS a la población infantil menor de 24 meses con condiciones de alto riesgo de enfermedad grave por VRS, como cardiopatías congénitas hemodinámicamente significativas, displasia broncopulmonar, inmunodepresión grave, errores congénitos del metabolismo, enfermedades neuromusculares o síndrome de Down, entre otras. No se limita a los prematuros ni a los niños con cardiopatías, que son solo algunos de estos grupos. La recomendación general de los menores de 6 meses corresponde a la primera temporada, no a la segunda en grupos de riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976feb") }, {"long_answer": "La vacunación frente a la viruela del mono se impulsó en España en el contexto de la declaración por parte de la OMS de una emergencia de salud pública de importancia internacional en julio de 2022, ante la rápida expansión del brote en países no endémicos. Esta situación motivó la adquisición centralizada de dosis y el establecimiento de recomendaciones de vacunación pre y posexposición. No se debió a la alta demanda mundial, que de hecho limitó la disponibilidad, ni a una tendencia decreciente del brote. Las dosis eran escasas, por lo que la mayor disponibilidad tampoco fue la justificación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fef") }, {"option_4": "Administrar dosis de 0,5 ml por vía intramuscular en menores de 18 años", "long_answer": "La recomendación del Ministerio de Sanidad para optimizar las dosis disponibles de vacuna frente a mpox fue administrar 0,1 ml por vía intradérmica en personas de 18 y más años, pauta que ha demostrado una respuesta inmunitaria no inferior a la de la dosis subcutánea completa. En los menores de 18 años, así como en embarazadas e inmunodeprimidos, se utiliza la dosis completa de 0,5 ml por vía subcutánea, no intradérmica ni intramuscular. Por tanto, las opciones que plantean la vía intradérmica en menores de 18 años, con 0,1 o 0,5 ml, son incorrectas, igual que la administración intramuscular, que no es la vía recomendada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ff1") }, {"long_answer": "La Ley 28/2005 considera infracción grave la venta o entrega a menores de edad de productos que imiten productos del tabaco e induzcan a fumar, como dulces, refrigerios o juguetes con forma de cigarrillo, porque normalizan el acto de fumar y favorecen el inicio del consumo en la infancia. La publicidad de productos del tabaco está regulada por otros preceptos y no se refiere a productos que imiten el acto de fumar. La entrega de dulces a menores, en general, no es infracción. La venta de tabaco a menores es otra conducta sancionable, pero no es la que plantea la pregunta."});
rm('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ff3") });
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ff4") }, {"long_answer": "La determinación del condensado bruto de humo y del condensado seco exento de nicotina, es decir, del alquitrán, en los cigarrillos se realiza según la norma ISO 4387, que establece el método de laboratorio con máquina de fumar analítica de rutina. Esta norma, junto con la ISO 10315 para la nicotina y la ISO 8454 para el monóxido de carbono, se utiliza para verificar los niveles máximos de emisión establecidos por la normativa. La ISO 9001 se refiere a sistemas de gestión de la calidad, y las referencias ISO 2000 e ISO 1234 no corresponden a este análisis."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ff5") }, {"long_answer": "La prueba de caída contra rotura de los dispositivos de cigarrillos electrónicos consiste en dejar caer el dispositivo desde una altura determinada sobre una superficie dura para comprobar que no se rompe ni presenta fugas de líquido de recarga, protegiendo así al usuario frente a la exposición a nicotina y a lesiones. Forma parte de los ensayos de verificación de la seguridad de estos productos. Someterlo a altas temperaturas o exponerlo a líquidos corrosivos corresponde a otro tipo de ensayos, no a la prueba de caída, por lo que la opción ninguna de las anteriores también es incorrecta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ff7") }, {"long_answer": "El Plan de Acción Mundial para la Seguridad del Paciente 2021-2030 de la OMS establece siete objetivos estratégicos, entre ellos implicar y empoderar a los pacientes y sus familias para que participen en una atención más segura, junto con políticas para eliminar el daño evitable, sistemas de alta fiabilidad, seguridad de los procesos clínicos, formación de los profesionales, información e investigación, y sinergias y alianzas. Involucrar al equipo multidisciplinar es deseable, pero no constituye uno de los siete objetivos formulados. Reducir la participación de los pacientes o eliminar la confianza en el sistema sanitario son contrarios al plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ff8") }, {"long_answer": "El reto mundial Medicación sin Daño de la OMS se centra en reducir los daños graves y evitables relacionados con los medicamentos, y la seguridad en la administración de medicamentos en los hospitales es una de las áreas concretas en las que se aplica, ya que es una fase del proceso con alta frecuencia de errores, junto con las situaciones de alto riesgo, la polimedicación y las transiciones asistenciales. Las vacunas tienen sus propios programas de seguridad. Los suplementos dietéticos no constituyen el foco del reto, y la terapia psicológica no es un medicamento, por lo que no forma parte de este ámbito."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ff9") }, {"long_answer": "El reto Medicación sin Daño de la OMS señala como una de las principales causas de errores en la administración de medicamentos en el domicilio el desconocimiento de los pacientes, familiares o cuidadores sobre la medicación y cómo utilizarla correctamente, por ejemplo en la dosis, la pauta o la técnica de administración. Por ello insiste en la educación y en proporcionar información clara. Un conocimiento extenso de la medicación sería un factor protector, no una causa de error. La falta de acceso a la atención sanitaria o de disponibilidad de medicamentos puede afectar a la adherencia, pero no son la causa principal de los errores de administración."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976ffe") }, {"long_answer": "Para un uso seguro de la medicación, los pacientes, familiares o cuidadores deben recibir información sobre la dosis y el intervalo de dosificación de cada medicamento, junto con su finalidad, la forma de administración, la duración del tratamiento y los posibles efectos adversos, de modo que puedan administrarlo correctamente y detectar errores. Informar exclusivamente del nombre del medicamento es insuficiente. El precio o la disponibilidad de los medicamentos en el mercado no son datos necesarios para manejar con seguridad el tratamiento ni contribuyen a prevenir errores de medicación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca976fff") }, {"long_answer": "Asegurar que los pacientes, familiares o cuidadores reciben información apropiada sobre su medicación es fundamental para prevenir errores de medicación y los eventos adversos evitables asociados, ya que un paciente informado administra correctamente sus fármacos y puede detectar discrepancias. Este es uno de los ejes del reto Medicación sin Daño. Las demás opciones plantean objetivos contrarios a la seguridad del paciente: evitar que participen en su tratamiento, aumentar los eventos adversos o reducir la confianza en el sistema sanitario no pueden ser la finalidad de informar al paciente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977002") }, {"long_answer": "Para involucrar a pacientes y familiares en la identificación de incidentes relacionados con la medicación, se recomienda animarles a participar activamente, comunicando cualquier duda, cambio inesperado en el aspecto del medicamento o efecto anómalo, ya que son una barrera eficaz para detectar errores. Proporcionarles información confusa o limitar su acceso a la información sobre el tratamiento es contrario a la seguridad del paciente. Facilitar herramientas para organizar y administrar los tratamientos es útil para la adherencia y el manejo seguro, pero no se refiere específicamente a su implicación en la identificación de incidentes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977008") }, {"long_answer": "Si los pacientes, familiares o cuidadores se quedan sin medicación antes de finalizar el tratamiento, deben comunicarlo a los profesionales sanitarios, que valorarán si es necesario renovar la prescripción, si hubo un error en la dispensación o en la administración, o si se ha tomado una dosis superior a la pautada. Dejar de tomar la medicación puede comprometer la eficacia del tratamiento y provocar complicaciones. Buscar alternativas por su cuenta o tomar decisiones sin consultar a los profesionales favorece la automedicación y los errores, por lo que no son actuaciones adecuadas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97700f") }, {"long_answer": "Según los datos de amputaciones en personas con diabetes recogidos en los documentos del SNS sobre el pie diabético, la tasa de amputaciones de miembros inferiores en España se sitúa en torno a 4,71 por cada 1.000 pacientes con diabetes, muy superior a la de la población sin diabetes, lo que refleja la importancia de la prevención, la detección precoz del pie de riesgo y la atención multidisciplinar. Las cifras de 3,89 y 1,18 por mil no corresponden a la tasa global de referencia, y el valor de 4,77 es un dato próximo pero distinto del indicador que recoge el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977012") }, {"long_answer": "Según los datos del Conjunto Mínimo Básico de Datos recogidos en el documento del SNS sobre el pie diabético, en España se realizaron 18.661 procedimientos de amputación de extremidad inferior en 2018, una cifra elevada en la que la diabetes es la principal causa no traumática. Esto pone de relieve la carga del pie diabético y la necesidad de programas de prevención y detección precoz. La cifra de 5.342 es claramente inferior al total de procedimientos registrados, y 13 no tiene relación con el volumen anual de amputaciones. El dato sí figura en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977016") }, {"long_answer": "La estratificación del riesgo del pie en las personas con diabetes debe realizarla preferentemente la enfermería de Atención Primaria, que lleva a cabo el seguimiento periódico de estos pacientes y puede explorar sensibilidad, pulsos, deformidades y antecedentes de úlcera para clasificar el riesgo y planificar la frecuencia de revisiones y la educación sanitaria. Los médicos de atención hospitalaria y los especialistas en cirugía ortopédica intervienen en fases avanzadas o complicadas. Los podólogos tienen un papel importante en el tratamiento y la prevención, pero la estratificación inicial se sitúa preferentemente en la consulta de enfermería de Atención Primaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97701e") }, {"question": "¿Qué medida de autocuidado deben realizar los pacientes con diabetes y sus familiares para detectar precozmente lesiones en el pie?", "long_answer": "La autoexploración diaria de los pies, con ayuda de un espejo o de un familiar si es necesario, permite detectar precozmente heridas, ampollas, grietas, cambios de color o signos de infección en las personas con diabetes, que a menudo no perciben estas lesiones por la neuropatía, y consultar sin demora. Es una de las principales medidas educativas para prevenir úlceras y amputaciones. Llamar al 112 se reserva para situaciones urgentes, no es una medida de detección. Esperar a la próxima cita retrasa el tratamiento, y automedicarse con antibióticos es peligroso y favorece las resistencias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977026") }, {"long_answer": "El Plan de Acción Europeo para el Ictus 2018-2030 plantea, para reducir el número absoluto de ictus en Europa, implementar plenamente estrategias nacionales de intervenciones multisectoriales de salud pública que promuevan estilos de vida saludables y reduzcan los factores ambientales, socioeconómicos y educativos que aumentan el riesgo de ictus. El tratamiento en fase aguda mejora el pronóstico del ictus ya producido, pero no reduce su número. La reducción del estrés y el ejercicio físico regular son medidas individuales beneficiosas, pero no constituyen la estrategia poblacional que propone el plan para alcanzar ese objetivo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977029") }, {"long_answer": "Las enfermedades cerebrovasculares se definen como todas las alteraciones encefálicas secundarias a un trastorno vascular, ya sea por isquemia o por hemorragia, de forma transitoria o permanente, y afectando a una o varias áreas del encéfalo. Esta es la definición recogida en la Estrategia en Ictus del SNS. Las opciones que hablan de trastorno circulatorio, problemas de circulación sanguínea en el cerebro o trastornos cerebrales causados por enfermedades circulatorias son formulaciones imprecisas o incompletas, ya que no abarcan todas las alteraciones encefálicas de origen vascular."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97702a") }, {"long_answer": "Los infartos lacunares representan aproximadamente el 20 % de los ictus isquémicos. Se deben a la oclusión de pequeñas arterias perforantes profundas, generalmente por lipohialinosis asociada a hipertensión arterial y diabetes, y producen infartos de menos de 15 mm en ganglios basales, cápsula interna, tálamo o protuberancia, con síndromes clínicos característicos como el motor puro o el sensitivo puro. Un 10 % infraestima su frecuencia, mientras que un 30 % o un 40 % se aproximan más a la proporción de ictus de origen aterotrombótico o cardioembólico que a la de los lacunares."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977033") }, {"long_answer": "La edad es el principal factor de riesgo no modificable del ictus: a partir de los 65 años, la incidencia y la prevalencia de ictus se duplican aproximadamente cada 5 años, debido a la progresión de la aterosclerosis y a la mayor acumulación de factores de riesgo como la hipertensión o la fibrilación auricular. Por ello, es falso que el riesgo disminuya con la edad o que permanezca constante a lo largo de la vida. Tampoco es cierto que la mortalidad por ictus sea mayor en edades tempranas, ya que aumenta en las personas de mayor edad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977036") }, {"long_answer": "La actividad física insuficiente y el sedentarismo incrementan el riesgo de ictus, tanto de forma directa como a través de su asociación con la hipertensión, la obesidad, la diabetes y la dislipemia, mientras que la actividad física regular reduce este riesgo. Por ello, la Estrategia en Ictus incluye la promoción de la actividad física en la prevención primaria y secundaria. Es falso que no guarden relación con el ictus o que aumenten el riesgo cardiovascular sin afectar al riesgo de ictus. Tampoco disminuyen el riesgo, sino todo lo contrario."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977037") }, {"long_answer": "Las dietas con elevado contenido en sodio y grasas saturadas incrementan el riesgo cerebrovascular porque favorecen la hipertensión arterial, la dislipemia y la aterosclerosis, por lo que la reducción de la sal y de las grasas saturadas es una recomendación clave en la prevención del ictus. La dieta mediterránea y la dieta DASH son patrones alimentarios cardiosaludables que reducen el riesgo vascular, y la DASH se diseñó precisamente para controlar la presión arterial. La dieta alta en azúcares y carbohidratos puede ser perjudicial, pero no es la dieta rica en sodio y grasas saturadas que plantea la pregunta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977038") }, {"long_answer": "El síndrome metabólico es un marcador de alto riesgo vascular asociado a la hiperinsulinemia o resistencia a la insulina, que agrupa obesidad abdominal, hipertensión, hipertrigliceridemia, colesterol HDL bajo e hiperglucemia, y se relaciona con un mayor riesgo de ictus y enfermedad cardiovascular. El síndrome antifosfolípido, la hipercoagulabilidad asociada al cáncer y los trastornos trombofílicos son también situaciones de riesgo trombótico, pero su mecanismo es la alteración de la coagulación, no la resistencia insulínica, por lo que no responden a la pregunta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97703e") }, {"long_answer": "Entre los efectos adversos más graves de la trombectomía mecánica figura la disección arterial, junto con la perforación vascular, la hemorragia intracraneal y la embolización a territorios distales o nuevos, ya que pueden empeorar la isquemia o provocar sangrados con importante repercusión neurológica. El hematoma en el punto de punción es una complicación local frecuente pero habitualmente leve. La hipertensión arterial requiere control tras el procedimiento, pero no es un efecto adverso grave de la técnica, y el vasoespasmo inducido por el catéter suele ser transitorio y de buen pronóstico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977041") }, {"long_answer": "En la trombectomía mecánica, el objetivo es alcanzar una recanalización TICI 2b-3, es decir, una reperfusión de al menos la mitad del territorio afectado o completa, porque este grado de recanalización se asocia de forma consistente a una mejor evolución funcional y a menor mortalidad. Evitar la recanalización es lo contrario de lo que se persigue. La recanalización no busca facilitar complicaciones locales, y una buena reperfusión no aumenta el riesgo de reoclusión, que depende de otros factores como la estenosis residual o la etiología del ictus."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977044") }, {"long_answer": "Tras una hemorragia subaracnoidea, la hidrocefalia aguda aparece en una proporción importante de pacientes, y en aproximadamente el 30 % de los casos se resuelve espontáneamente, sin necesidad de derivación permanente del líquido cefalorraquídeo. En el resto se precisa un drenaje ventricular externo o lumbar y, en algunos casos, una derivación definitiva. Las cifras del 10 % y el 20 % infraestiman la frecuencia de resolución espontánea, mientras que el 40 % la sobrestima respecto a los datos recogidos en la Estrategia en Ictus del SNS."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977046") }, {"long_answer": "El daño cerebral diferido, o isquemia cerebral diferida, es la principal causa de morbilidad en los pacientes que sobreviven a una hemorragia subaracnoidea aneurismática. Suele aparecer entre el 4.º y el 14.º día, se relaciona con el vasoespasmo y otros mecanismos como la microtrombosis y la disfunción microvascular, y puede producir infartos cerebrales con secuelas permanentes. Las crisis epilépticas, la hidrocefalia aguda y el estatus no convulsivo son complicaciones posibles, pero menos determinantes del pronóstico funcional a largo plazo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977048") }, {"long_answer": "En los pacientes con hemorragia subaracnoidea en coma o con bajo nivel de consciencia se recomienda la monitorización con electroencefalografía, ya que permite detectar crisis epilépticas no convulsivas o un estatus no convulsivo, que pueden pasar inadvertidos clínicamente y empeorar el pronóstico, así como identificar signos precoces de isquemia. Los bloqueantes de los canales de calcio, como el nimodipino, se indican en la profilaxis del daño cerebral diferido en todos los pacientes, no específicamente por el nivel de consciencia. Los antagonistas de la endotelina 1 no se recomiendan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977049") }, {"long_answer": "En la profilaxis del daño cerebral diferido tras una hemorragia subaracnoidea aneurismática, el tratamiento con bloqueantes de los canales de calcio, concretamente nimodipino oral, es la terapia con mayor indicación y nivel de evidencia, ya que ha demostrado mejorar el pronóstico funcional. La hipervolemia profiláctica no aporta beneficio y aumenta las complicaciones. La euvolemia se recomienda como medida general, pero su nivel de evidencia es menor. Los antagonistas de la endotelina 1, como el clazosentán, reducen el vasoespasmo angiográfico sin mejorar los resultados clínicos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977050") }, {"long_answer": "En los pacientes con ictus que presentan retención aguda de orina se recomienda realizar sondaje vesical y retirarlo tan pronto como sea posible, preferiblemente con sondajes intermitentes, ya que la sonda permanente aumenta el riesgo de infección urinaria, una de las complicaciones más frecuentes en estos pacientes. La retención urinaria no requiere cirugía urgente. Los antibióticos solo están indicados si existe infección, no como tratamiento de la retención. No actuar es incorrecto, porque la retención mantenida produce dolor, agitación y daño vesical."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977051") }, {"long_answer": "En consonancia con el Plan de Acción Europeo para el Ictus, la Estrategia en Ictus del SNS establece como objetivo principal tratar al menos al 90 % de las personas que sufren un ictus en una unidad de ictus como primer nivel de atención, ya que este tipo de atención reduce la mortalidad y la dependencia. Reducir la mortalidad intrahospitalaria, acortar la estancia media o incrementar la independencia funcional al alta son indicadores de calidad o resultados deseables, pero no se plantean como el objetivo principal de la Estrategia ni con esas cifras concretas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97705a") }, {"long_answer": "En el ámbito de la vida después del ictus, uno de los aspectos más prioritarios es que la persona pueda participar en actividades significativas para ella, como las sociales, laborales, de ocio o familiares, ya que la reintegración en la comunidad es clave para su calidad de vida y bienestar emocional. Desarrollar habilidades cognitivas y realizar terapia ocupacional son medios de rehabilitación que contribuyen a ese objetivo, pero no son el fin en sí mismos. Recibir cuidados intensivos corresponde a la fase aguda y no a la vida después del ictus."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97705b") }, {"question": "¿Qué tratamiento se recomienda en todos los pacientes que han sufrido un ictus isquémico o AIT no cardioembólico para la prevención secundaria?", "option_1": "Antiagregación plaquetaria (AAS, clopidogrel o AAS asociado a dipiridamol)", "option_2": "Anticoagulación oral con antagonistas de la vitamina K", "option_3": "Ningún tratamiento antitrombótico", "option_4": "Heparina de bajo peso molecular de forma indefinida", "answer": 1, "long_answer": "En los pacientes con ictus isquémico o AIT de origen no cardioembólico se recomienda tratamiento antiagregante plaquetario de forma indefinida para la prevención secundaria, con AAS, clopidogrel o la combinación de AAS y dipiridamol de liberación retardada, eligiendo la opción según las características del paciente. La anticoagulación oral se reserva para el ictus de origen cardioembólico, como el asociado a fibrilación auricular, y no ha demostrado superioridad en el no cardioembólico, con mayor riesgo hemorrágico. No tratar es incorrecto, y la heparina de bajo peso molecular indefinida no está indicada en la prevención secundaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977060") }, {"long_answer": "La Neurología clínica tiene un papel central en el estudio etiológico y el tratamiento del paciente con ictus, tanto en la fase aguda, con la indicación de terapias de reperfusión y la coordinación de las unidades de ictus, como en la prevención secundaria y el seguimiento, tal como recoge la Estrategia en Ictus del SNS. La Medicina Interna, la Cardiología y la Cirugía Vascular participan en el abordaje multidisciplinar, por ejemplo en el estudio de fuentes cardioembólicas o en la revascularización carotídea, pero no asumen el papel central en el manejo del ictus."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977062") }, {"long_answer": "En el estudio etiológico del ictus hemorrágico, una de las pruebas básicas recomendadas es la angioTC cerebral, que permite detectar de forma rápida y no invasiva causas secundarias de la hemorragia, como aneurismas, malformaciones arteriovenosas o trombosis venosas, y orientar la necesidad de una arteriografía. El ecocardiograma transtorácico y el Doppler transcraneal forman parte del estudio del ictus isquémico, para buscar fuentes cardioembólicas o estenosis intracraneales. El estudio del líquido cefalorraquídeo no es una prueba básica en la hemorragia intracerebral."});
rm('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977063") });
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a65") }, {"long_answer": "El Plan de Acción de Atención Primaria y Comunitaria recoge, en línea con el Plan Estratégico Nacional para la Reducción de la Obesidad Infantil, que los centros de salud avancen en la acreditación de la Iniciativa para la Humanización de la Asistencia al Nacimiento y la Lactancia (IHAN), porque la lactancia materna es un factor protector frente al exceso de peso en la infancia y la acreditación garantiza prácticas basadas en la evidencia. Promover dietas bajas en grasas sin relación con el nacimiento no es la medida que se plantea, ofrecer atención pediátrica sin apoyo a la lactancia contradice el enfoque preventivo y la atención dietética exclusivamente hospitalaria se aleja del papel central de Atención Primaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a67") }, {"long_answer": "El Plan plantea profesionalizar la gestión en Atención Primaria actualizando el contenido y la metodología de los planes de gestión anuales y formando a los profesionales que asumen funciones directivas, de modo que la planificación sea más rigurosa y orientada a resultados. Descentralizar la gestión en personal administrativo sin formación específica iría en contra de esa profesionalización, reducir la planificación anual empobrecería el control de objetivos y externalizar la gestión a empresas privadas sin control sanitario no forma parte de las medidas del Plan, que apuesta por reforzar la capacidad de gestión pública del primer nivel asistencial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a69") }, {"long_answer": "Para reforzar la orientación comunitaria, el Plan se apoya en la Guía Didáctica en Acción Comunitaria, un recurso que orienta a los equipos de Atención Primaria sobre cómo identificar activos en salud, trabajar con la comunidad y desarrollar intervenciones de salud comunitaria con metodología común. El incremento de personal en hospitales y la digitalización de historiales hospitalarios no actúan sobre la dimensión comunitaria de la Atención Primaria, y ampliar las consultas telefónicas a pacientes crónicos es una medida de accesibilidad asistencial individual, no un mecanismo de acción comunitaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a6c") }, {"long_answer": "En la elaboración del Plan de Acción de Atención Primaria y Comunitaria 2025-2027, la matriz de priorización de acciones se diseñó en mayo de 2024 mediante metodología Delphi, técnica de consenso de expertos en rondas sucesivas que permite ordenar las intervenciones según su relevancia y factibilidad. Las demás opciones combinan fechas y métodos que no corresponden al proceso descrito: ni un análisis estadístico en enero de 2024, ni una consulta pública general en abril de 2023, ni una encuesta clínica en septiembre de 2024 fueron la base de la matriz."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a76") }, {"long_answer": "Para fomentar la longitudinalidad, el Plan propone analizar las buenas prácticas europeas y, a partir de ellas, emitir recomendaciones a corto y medio plazo que favorezcan que cada persona sea atendida a lo largo del tiempo por los mismos profesionales de referencia. Reducir el tiempo de consulta de pacientes sin patología crónica no mejora la continuidad, asignar profesionales solo por volumen poblacional ignora la complejidad y las necesidades de la población, y aumentar la atención online sin contacto directo puede fragmentar la relación profesional-paciente en lugar de reforzarla."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a7b") }, {"long_answer": "El Plan fija como resultado esperado que el 100% de las plazas de Enfermería Familiar y Comunitaria creadas sean ocupadas por especialistas, con el fin de consolidar la especialidad en Atención Primaria y aprovechar las competencias adquiridas durante la residencia EIR. Un aumento genérico del 5% de plazas sin especificar especialidad no responde a este objetivo, la reducción de plazas de EFyC iría en sentido contrario al refuerzo de la enfermería especialista y sustituirlas por contratos temporales sin especialización contradice las metas de estabilidad y cualificación del Plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a7f") }, {"long_answer": "El Plan recoge que todas las comunidades autónomas han implantado un procedimiento específico para la gestión inmediata de los problemas de salud no demorables, de manera que la persona que acude con un problema agudo sea atendida en el mismo día dentro de Atención Primaria. La derivación directa a atención hospitalaria sobrecargaría las urgencias y restaría capacidad resolutiva al primer nivel, el uso exclusivo de tecnología telemática no permite valorar adecuadamente todos los casos y el cierre de consultas presenciales es contrario a la accesibilidad que se pretende garantizar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a86") }, {"long_answer": "Respecto a los acuerdos sobre puestos de difícil cobertura en Atención Primaria, el resultado esperado es que todas las comunidades autónomas hayan implantado el 100% de las acciones acordadas en 2026, lo que se comprueba mediante la monitorización anual de dichos acuerdos. Una implantación parcial superior al 50% en algunas regiones no alcanza la meta fijada, eliminar los incentivos de estas plazas haría aún más difícil cubrirlas y suspender el seguimiento impediría evaluar el cumplimiento, justo lo contrario de lo que persigue la monitorización."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779be") }, {"long_answer": "En la Estrategia de la Industria Farmacéutica, el Programa PROFARMA se presenta como un instrumento de optimización que reconoce y clasifica a las compañías según su actividad industrial, investigadora e innovadora, con el fin de reforzar la competitividad y la resiliencia del sector farmacéutico en España. No consiste en eliminar incentivos fiscales para desplazar la inversión a nuevas provincias, no se limita a la compra pública de genéricos y tampoco pretende restringir la exportación de medicamentos, sino favorecer la inversión y la actividad productiva e innovadora."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779c2") }, {"long_answer": "La Estrategia describe que en 2023 la balanza comercial farmacéutica española fue deficitaria, es decir, España importó un mayor valor de productos farmacéuticos del que exportó, lo que pone de manifiesto la dependencia exterior y justifica medidas para reforzar la producción nacional y la autonomía estratégica. Afirmar que exporta más de lo que importa es lo contrario de lo descrito, decir que no realiza exportación significativa es falso porque el sector exporta un volumen relevante, y limitar sus exportaciones a genéricos y biosimilares no se corresponde con la realidad del sector."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779c6") }, {"long_answer": "La autonomía estratégica se entiende en la Estrategia como la capacidad de la industria para garantizar el suministro interno de medicamentos, especialmente los críticos, fomentando una producción propia resiliente y ecosostenible que reduzca la vulnerabilidad ante crisis y rupturas de las cadenas globales. Depender exclusivamente de importaciones es justo la situación que se quiere evitar, centralizar la producción en un único fabricante nacional aumentaría el riesgo de desabastecimiento y reducir la inversión en investigación propia debilitaría la capacidad innovadora en lugar de reforzarla."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779c7") }, {"long_answer": "La Estrategia considera la medicina personalizada de precisión un área clave que debe impulsarse tanto en la investigación como en su implementación en el Sistema Nacional de Salud, porque permite adaptar diagnósticos y tratamientos a las características genéticas y clínicas de cada paciente y mejorar su eficacia y seguridad. No se trata de una línea sin relevancia práctica ni financiación, tampoco de algo que coexista con la medicina convencional sin integrarse en el sistema, y no se descarta por su coste, ya que se apuesta precisamente por su incorporación progresiva."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779ca") }, {"long_answer": "Dentro del Eje 2, orientado a la investigación y la innovación, la Estrategia promueve el uso de herramientas financieras especializadas en biomedicina para estimular la I+D+i, facilitando capital a proyectos y empresas que necesitan financiación específica durante fases de desarrollo largas y de alto riesgo. No se consideran prescindibles por existir financiación pública, ya que se busca complementarla con inversión privada, no se restringen a proyectos extranjeros y no sirven solo para comprar medicamentos en fase clínica final, sino para apoyar el desarrollo innovador en todas sus etapas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779ce") }, {"long_answer": "La Estrategia destaca que España realiza una inversión pública sin precedentes en el ámbito biomédico, que impulsa tratamientos de vanguardia y proyectos de innovación en colaboración público-privada, como los vinculados a terapias avanzadas o medicina de precisión. Decir que carece de relevancia para el progreso científico o clínico es contrario a lo descrito, limitarla a infraestructuras básicas sin aplicación clínica ignora su orientación traslacional y afirmar que solo apoya investigación sin conexión industrial contradice la apuesta explícita por la colaboración con la industria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779d1") }, {"long_answer": "El Reglamento europeo de evaluación de tecnologías sanitarias establece un procedimiento de evaluación clínica conjunta a escala de la Unión, para el cual el desarrollador presenta una sola vez toda la información necesaria, evitando duplicidades entre Estados miembros y agilizando el acceso a medicamentos y productos sanitarios. No regula los aspectos no clínicos, que siguen siendo competencia nacional (precio, financiación, aspectos organizativos), y su finalidad no es controlar el acceso a datos de pacientes ni limitar el intercambio de información a las autoridades nacionales.", "question": "¿Cuál es el objetivo del Reglamento europeo de evaluación de tecnologías sanitarias en relación con la evaluación clínica conjunta?"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779d4") }, {"long_answer": "La regulación propuesta a partir del Real Decreto 1015/2009, sobre disponibilidad de medicamentos en situaciones especiales, pretende reglar formalmente el acceso a medicamentos que aún no tienen autorización de comercialización o que se usan en condiciones distintas a las autorizadas, como el uso compasivo, dando seguridad jurídica a pacientes y profesionales. No prohíbe todo uso sin autorización, ya que precisamente lo ordena; no garantiza financiación inmediata de todos esos medicamentos, y tampoco elimina los controles sanitarios, que siguen siendo imprescindibles para proteger a los pacientes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779db") }, {"long_answer": "Para impulsar la transparencia y mejorar el sistema de precios de referencia, la Estrategia propone establecer y publicar una contabilidad real del uso de medicamentos en los distintos ámbitos (receta, hospital y otros), de forma que las decisiones sobre conjuntos y precios se basen en datos completos y públicos. Evitar la publicación de datos de uso iría contra la transparencia, mantener precios estáticos sin revisión impediría ajustar el sistema a la realidad del mercado y eliminar las diferencias entre genéricos y biosimilares no es una medida contemplada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779de") }, {"long_answer": "Entre las medidas para mejorar la compra pública de medicamentos, la Estrategia plantea crear un catálogo de buenas prácticas que conjugue el acceso de los pacientes con la sostenibilidad del sistema, sirviendo de referencia para los órganos de contratación de las distintas administraciones. Obligar a usar solo el procedimiento ordinario sin excepciones restaría flexibilidad, eliminar los criterios de autonomía estratégica en las licitaciones contradice el objetivo de asegurar el suministro y reducir procedimientos para evitar la competencia es contrario a los principios de la contratación pública."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779f1") }, {"long_answer": "El despliegue de la taxonomía genómica de resistencias antimicrobianas exige implementar herramientas genómicas que permitan caracterizar precozmente el genotipo de los microorganismos, identificando los mecanismos de resistencia para orientar el tratamiento y la vigilancia epidemiológica. Aumentar el uso de antibióticos sin control favorece la aparición de resistencias, reducir la colaboración internacional dificulta la vigilancia de un problema global y eliminar el diagnóstico molecular en los hospitales sería incompatible con un enfoque basado en la genómica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779f3") }, {"long_answer": "TERAFRONT se configura como una sociedad mercantil de capital mixto, con participación pública y privada, orientada a acompañar el desarrollo de terapias avanzadas desde las fases clínicas precoces hasta su comercialización, cubriendo así el salto entre la investigación y el mercado. No es un programa exclusivo para universidades, no financia producción masiva sin innovación y no se limita a la fase preclínica sin participación estatal, ya que cuenta precisamente con participación pública a través del CDTI."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a00") }, {"long_answer": "En la formación de pacientes en I+D, la Estrategia considera esencial explicar el valor de compartir sus datos de salud para la investigación y cómo esa información influye en la innovación y el desarrollo de nuevos medicamentos, siempre con las debidas garantías de protección. Evitar la participación ciudadana por privacidad, limitar la información a los profesionales sanitarios o centrarse solo en el uso clínico tradicional sin bases de datos contradicen el objetivo de implicar activamente a los pacientes en la investigación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a03") }, {"long_answer": "La Compra Pública de Innovación en salud busca desarrollar soluciones para necesidades clínicas no cubiertas mediante la colaboración entre la administración y el sector privado, de modo que el comprador público actúa como impulsor de la innovación definiendo el problema y no el producto. No persigue la compra masiva de productos existentes sin innovación, no limita la participación a grandes compañías, ya que se abre también a pymes y centros de investigación, y no pretende eludir todo riesgo renunciando al desarrollo tecnológico, sino compartirlo.", "option_4": "Evitar cualquier riesgo renunciando al desarrollo tecnológico"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a04") }, {"long_answer": "TERAFRONT cuenta con un 49% de participación pública, aportada a través del programa INNVIERTE del CDTI, mientras que el 51% restante corresponde al socio privado, lo que la convierte en una sociedad de capital mixto con control mayoritario privado. No está financiada al 100% por el ISCIII, la AEMPS no participa como socio financiador con un 25% y no es correcto decir que carezca de participación pública, puesto que el CDTI es socio relevante del proyecto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a08") }, {"long_answer": "La Alianza de Medicamentos Críticos, impulsada por la Comisión Europea, tiene como objetivo reforzar las capacidades de fabricación en la Unión y diversificar las cadenas de suministro para garantizar la disponibilidad de los medicamentos considerados críticos y prevenir desabastecimientos. Reducir la inversión en medicamentos esenciales, aumentar la dependencia de importaciones de terceros países o eliminar la transparencia de las cadenas de suministro son justo lo contrario de lo que persigue esta alianza."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a0f") }, {"long_answer": "El Plan señala que los factores de riesgo tradicionales tienen escasa capacidad predictiva de la conducta suicida porque son muy prevalentes en la población y poco específicos, de modo que generan numerosos falsos positivos y falsos negativos y no permiten anticipar con precisión qué persona realizará una conducta suicida. La limitación no se debe a la falta de estudios, el riesgo suicida no es estático ni fácil de identificar, sino dinámico, y los factores considerados no son solo sociales, sino también clínicos, psicológicos y biológicos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a12") }, {"long_answer": "La restricción del acceso a los métodos letales más comunes (fármacos, armas de fuego, puntos elevados o pesticidas, entre otros) se considera la intervención estructural más eficaz en prevención del suicidio, porque muchas crisis suicidas son transitorias y dificultar el acceso al medio reduce la letalidad y da tiempo a que la crisis remita. La terapia grupal con allegados es una intervención clínica, no estructural, y las campañas en redes sociales o las charlas informativas tienen un efecto preventivo menor y menos contrastado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a15") }, {"long_answer": "El Plan recoge, a partir de datos de la OMS, una tasa de suicidio en las prisiones españolas de alrededor de 90,9 por cada 100.000 personas privadas de libertad, muy superior a la de la población general, lo que justifica considerar este colectivo especialmente vulnerable. Las cifras de 35,4 y 120 por 100.000 habitantes se refieren a la población general y no se corresponden con los datos descritos, y la cifra de 50 por 100.000 personas privadas de libertad tampoco es la recogida en el Plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a17") }, {"long_answer": "La Guía de Práctica Clínica de Prevención y Tratamiento de la Conducta Suicida recomienda que la familia y los allegados sean informados y orientados para que puedan acompañar a la persona, ofrecer apoyo emocional efectivo, detectar señales de alarma y colaborar en el plan de seguridad. Mantenerlos al margen por respeto a la privacidad les impediría ejercer ese papel protector, su función no se reduce al apoyo económico y la supervisión médica corresponde a los profesionales sanitarios, no a los familiares."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a1f") }, {"long_answer": "El Plan de Acción para la Prevención del Suicidio organiza sus líneas estratégicas según el nivel de intervención: las primeras se orientan a medidas universales dirigidas a toda la población, las intermedias a intervenciones selectivas en grupos vulnerables, y las líneas 5 y 6 a intervenciones indicadas para personas que ya han presentado conducta suicida, incluyendo su atención y seguimiento. Las líneas 1 y 2 y las líneas 3 y 4 corresponden a otros niveles de prevención, y no existe una línea 7 en el Plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a22") }, {"long_answer": "El Plan considera que el registro y seguimiento de la conducta suicida contribuye a mejorar la vigilancia y la calidad de los datos, lo que permite conocer mejor la magnitud y distribución del problema y orientar las medidas de prevención. No se trata de una estadística sin aplicación práctica, ya que sus datos guían intervenciones; no es responsabilidad exclusiva de organismos internacionales, sino de las administraciones sanitarias, y su complejidad es precisamente lo que hace necesario un registro de calidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a23") }, {"long_answer": "Para evaluar el avance en la recogida de datos sobre conducta suicida, el Plan contempla indicadores como el porcentaje de comunidades autónomas que colaboran con los profesionales encargados del registro, lo que refleja la implantación territorial del sistema de información. El número de intervenciones policiales, la cantidad de artículos periodísticos publicados o las sanciones a medios de comunicación no miden la calidad ni la cobertura de la recogida de datos sanitarios sobre conducta suicida."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a2b") }, {"long_answer": "La creación del Observatorio para la Prevención del Suicidio tiene como resultado esperado la elaboración de informes periódicos y el establecimiento de mecanismos de coordinación entre administraciones, de forma que el conocimiento generado se traduzca en mejores políticas de prevención. Reducir el presupuesto de salud mental sería contrario a los objetivos del Plan, limitar la publicación de datos restaría transparencia y delegar todas las tareas en las comunidades autónomas sin coordinación es justo lo que el Observatorio pretende evitar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a31") }, {"long_answer": "El Plan de Acción de Atención Primaria y Comunitaria fija como meta que el 100% de las comunidades autónomas hayan adaptado las competencias del personal administrativo en salud antes de 2026, reconociendo su papel en la gestión de la demanda y en la descarga burocrática de los profesionales sanitarios. Los plazos de antes de 2025, 2027 o 2028 no corresponden al calendario establecido para esta acción en el Plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a33") }, {"long_answer": "El impulso del uso, indicación y autorización de dispensación de medicamentos y productos sanitarios por parte de las enfermeras tiene como objetivo mejorar los resultados en salud mediante una atención integral, segura, colaborativa y basada en la evidencia, aprovechando las competencias enfermeras y agilizando la respuesta a las necesidades de los pacientes. No pretende reducir la autonomía médica en la prescripción, no aumenta la burocracia, sino que la reduce, y su finalidad no es disminuir la cantidad de medicamentos prescritos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a34") }, {"long_answer": "La actualización de la cartera común de servicios de Atención Primaria publicada en 2025 incorpora procedimientos diagnósticos, la atención no presencial y la salud comunitaria, adaptando la oferta del primer nivel asistencial a las necesidades actuales y a la práctica real de los equipos. No pretende reducir los servicios ofrecidos ni eliminar las actividades educativas y preventivas, que son esenciales en Atención Primaria, y tampoco incluir de forma exclusiva servicios quirúrgicos, que no son el núcleo de su actividad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a3b") }, {"long_answer": "El Plan de Acción establece como meta, hasta su finalización, un incremento de al menos un 50% de los procesos optimizados en Atención Primaria, con el fin de mejorar la eficiencia, reducir pasos innecesarios y liberar tiempo asistencial. Los porcentajes del 20% y del 75% no corresponden al objetivo fijado en el documento, y afirmar que no se plantean incrementos es incorrecto, puesto que la optimización de procesos es una de las líneas de mejora de la capacidad resolutiva."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a51") }, {"long_answer": "En la línea de gobernanza y rendición de cuentas, el Plan propone consensuar en el Consejo Interterritorial del SNS una recomendación para vincular el crecimiento del gasto sanitario público al incremento presupuestario de Atención Primaria, de forma que esta reciba una parte proporcional del aumento de recursos. Aumentar la inversión solo en atención hospitalaria, recortar Atención Primaria para financiar urgencias o separar su presupuesto del gasto sanitario general son contrarios al objetivo de reforzar la financiación del primer nivel asistencial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a53") }, {"long_answer": "En la línea 6, el Plan considera fundamental mejorar los servicios de integración e interoperabilidad de las historias de salud digitales autonómicas, porque permiten que la información clínica circule entre niveles asistenciales y comunidades autónomas, garantizando la continuidad asistencial. Aumentar las consultas presenciales sin soporte digital, limitar los sistemas de comunicación al ámbito hospitalario o volver a historiales en papel dificultarían el intercambio de información y la coordinación entre profesionales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a5e") }, {"long_answer": "La renovación de infraestructuras y equipamiento en Atención Primaria tiene como propósito adecuar y modernizar los centros a las actualizaciones autonómicas de la cartera de servicios, de forma que dispongan de los medios necesarios para prestar los nuevos servicios y aumentar su capacidad resolutiva. Reducir inversiones para priorizar hospitales, mantener infraestructuras obsoletas o centralizar servicios en grandes hospitales urbanos son contrarios al objetivo de reforzar el primer nivel asistencial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a60") }, {"long_answer": "Dentro de la mejora de procesos administrativos, el Plan impulsa antes de 2026 un acuerdo para implantar la autodeclaración responsable, que permite al trabajador justificar ausencias breves por enfermedad sin necesidad de acudir a consulta, reduciendo así visitas burocráticas en Atención Primaria. No se plantea eliminar todos los procedimientos administrativos, centralizar procesos en el hospital o incrementar el papeleo, ya que el objetivo es desburocratizar las consultas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a64") }, {"long_answer": "Con la actualización de la cartera básica común de Atención Primaria, en relación con los servicios de atención comunitaria, se busca que las comunidades autónomas adecuen sus carteras de servicios al nuevo marco actualizado, garantizando una oferta homogénea en todo el territorio. Disminuir la oferta comunitaria en zonas rurales, centrar la atención comunitaria en el hospital o descentralizar totalmente el control de los recursos sin un marco común son contrarios a los objetivos de equidad y orientación comunitaria del Plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a66") }, {"long_answer": "Para favorecer la atención social y comunitaria, el Plan propone incluir en la Historia de Salud Digital los condicionantes sociales y del contexto familiar, consensuados y actualizados, ya que los determinantes sociales influyen de forma decisiva en la salud y permiten planificar intervenciones más adecuadas. Registrar solo información clínica sin contexto social, limitar los datos al ámbito hospitalario o eliminar la información social por privacidad impedirían ese enfoque integral de la atención."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a68") }, {"long_answer": "Entre los avances en calidad asistencial que todas las comunidades autónomas han presentado en Atención Primaria destaca la integración de la Historia de Salud Digital, que facilita la continuidad asistencial al permitir el acceso a la información clínica relevante entre profesionales y niveles. La incorporación de nuevas vacunas pediátricas corresponde al calendario vacunal, la extensión de servicios de urgencias no es el avance descrito y la creación de nuevas especialidades médicas no es una competencia de las comunidades autónomas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a6a") }, {"long_answer": "La Red de Investigación en Cronicidad, Atención Primaria y Promoción de la Salud (RICAPPS) está formada a nivel estatal por 26 grupos de investigación, con participación mayoritaria de profesionales de Atención Primaria, lo que refuerza la investigación en el primer nivel asistencial. No está compuesta por 30 grupos de investigación hospitalaria exclusiva, ni por 15 grupos de atención especializada y salud pública, ni por 40 grupos de salud mental, ya que su foco es la cronicidad, la Atención Primaria y la promoción de la salud."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a6f") }, {"long_answer": "En materia de fidelización y atracción de talento, el objetivo prioritario del Plan es garantizar la continuidad y la longitudinalidad de los cuidados, ya que la estabilidad de los profesionales en sus puestos permite mantener la relación con los pacientes a lo largo del tiempo y mejora los resultados en salud. Externalizar la carga administrativa, incrementar la formación en técnicas quirúrgicas o limitar las contrataciones a personal temporal no responden a este objetivo y, en el caso de la temporalidad, lo empeorarían."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a77") }, {"long_answer": "La propuesta para incentivar el retorno de profesionales a Atención Primaria desde otros ámbitos asistenciales consiste en emitir recomendaciones adaptadas a cada categoría profesional y a cada territorio, teniendo en cuenta las distintas necesidades de cobertura. Ofrecer contratos indefinidos sin requisitos no se contempla, obligar a los profesionales a regresar tras un año fuera no es una medida de incentivo y reducir las actividades de investigación iría en contra del desarrollo profesional que se pretende fomentar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a78") }, {"long_answer": "El Plan establece como meta que el 100% de las comunidades autónomas implanten las recomendaciones para el retorno a Atención Primaria antes de 2026, de forma que la medida tenga alcance en todo el Sistema Nacional de Salud. El 60% no es el objetivo fijado, limitarlo a las comunidades con déficit de profesionales no se corresponde con la meta establecida y afirmar que no hay ninguna medida comprometida contradice el carácter del Plan, que fija resultados esperados e indicadores de seguimiento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a79") }, {"long_answer": "En el seguimiento de los acuerdos de la Comisión de Recursos Humanos del Consejo Interterritorial, se monitoriza anualmente la implantación de los criterios para identificar puestos de difícil cobertura y de los incentivos para la fidelización de profesionales en Atención Primaria. La satisfacción de los pacientes hospitalizados, el presupuesto en formación quirúrgica o la adquisición de tecnologías para atención domiciliaria no son el objeto de este seguimiento, que se centra en la estabilidad y atracción de profesionales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a7a") }, {"long_answer": "En los nombramientos de enfermería de Atención Primaria, el Plan impulsa que las normativas establezcan como mérito prioritario el título de especialista en Enfermería Familiar y Comunitaria, para que los puestos sean ocupados por profesionales con la formación específica adquirida en la residencia. La experiencia en servicios hospitalarios no es el mérito priorizado para Atención Primaria, la formación universitaria básica es un requisito y no un mérito diferencial, y los cursos de gestión administrativa no se relacionan con la competencia clínica comunitaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a7e") }, {"long_answer": "Los acuerdos de gestión clínica desarrollados por todas las comunidades autónomas tienen como función dotar a los equipos de Atención Primaria de autonomía en la gestión de sus agendas y de contratos programa adaptados a cada territorio, lo que favorece una organización más ajustada a las necesidades de su población. No se limitan a la contratación de personal médico especializado, no buscan fomentar la atención hospitalaria frente a la primaria ni eliminar la coordinación entre niveles, que sigue siendo esencial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a80") }, {"long_answer": "Según el Plan, la mejora de la capacidad resolutiva y de la gestión de la demanda en Atención Primaria se favorece optimizando los procedimientos administrativos, para reducir la carga burocrática y liberar tiempo clínico, y renovando infraestructuras y equipamiento, para que los centros puedan asumir más procesos sin derivar. Alargar los tiempos de derivación hospitalaria, reducir personal en centros rurales o limitar la atención aguda al teléfono empeorarían la accesibilidad y la resolución de problemas en el primer nivel."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a81") }, {"long_answer": "La interoperabilidad de las historias clínicas digitales tiene como objetivo garantizar una continuidad asistencial de calidad entre Atención Primaria y los niveles hospitalarios, permitiendo que la información clínica relevante esté disponible para todos los profesionales que atienden a la persona. No pretende sustituir completamente las consultas presenciales por teleconsultas ni reducir el almacenamiento de información, y fomentar la desconexión entre niveles asistenciales es justo lo contrario de lo que se busca."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779bf") }, {"long_answer": "La gobernanza de la Estrategia de la Industria Farmacéutica se articula mediante un Comité Interministerial, un Comité mixto entre administración e industria y la Alianza para la Estrategia, estructuras que aseguran la coordinación entre ministerios, el diálogo con el sector y el seguimiento de las medidas. Un comité formado solo por empresas privadas excluiría a la administración, la delegación exclusiva en el Ministerio de Industria sin participación externa ignora el carácter interministerial y una gestión local sin coordinación nacional impediría un seguimiento homogéneo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779c4") }, {"long_answer": "Las patronales de la industria farmacéutica participan activamente en el grupo de trabajo interministerial que elaboró la Estrategia y en el Comité mixto administración-industria encargado de su seguimiento, lo que refleja el enfoque colaborativo entre el sector público y el privado. Por ello no es correcto afirmar que no participan, ni que su papel sea meramente consultivo en temas de producción sin acceso a decisiones, ni que se limiten a la difusión pública sin compromiso con las políticas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779c8") }, {"long_answer": "La mejora del Sistema de Precios de Referencia que propone la Estrategia tiene como objetivo principal aumentar la eficiencia y la sostenibilidad de la financiación pública de medicamentos en el SNS, fomentando la competencia una vez que existen alternativas genéricas o biosimilares. No busca subir de forma arbitraria los precios de los innovadores, no pretende eliminar el sistema en favor de negociaciones individuales y reducir el acceso a medicamentos es contrario a su finalidad de liberar recursos para financiar la innovación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779c9") }, {"long_answer": "La Estrategia recoge que el volumen global de medicamentos utilizados crecerá entre 2023 y 2028 a una tasa media anual estimada en torno al 2,3%, un crecimiento moderado impulsado por el envejecimiento poblacional y el mayor acceso a tratamientos. Una tasa del 5,5% o del 10% sobrestimaría notablemente la evolución del volumen de uso, mientras que un 0,5% supondría prácticamente un estancamiento que no se corresponde con las previsiones descritas en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779cb") }, {"long_answer": "El Sistema Nacional de Información sobre el consumo de medicamentos es, según la Estrategia, una herramienta de ámbito estatal para conocer, gestionar y optimizar el uso de medicamentos y hacer un seguimiento de su consumo en los distintos ámbitos asistenciales, lo que permite tomar decisiones basadas en datos. No se limita a controlar precios, no se plantea su eliminación, ya que se considera prioritario, y no se restringe a los genéricos, sino que abarca el conjunto de medicamentos financiados."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779d6") }, {"long_answer": "Los procedimientos de acceso colaborativos entre las compañías y el Estado buscan complementar la generación de conocimiento sobre el medicamento en condiciones de vida real, de modo que los datos recogidos tras su incorporación al SNS reduzcan la incertidumbre sobre su efectividad y apoyen las decisiones de financiación. No limitan el uso a fases experimentales, no restringen la investigación clínica independiente y su objetivo no es exclusivamente reducir costes, sino facilitar un acceso informado y sostenible."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779d7") }, {"long_answer": "En la reforma del procedimiento de financiación de nuevos medicamentos, la Estrategia considera clave disponer de criterios claros, previsibilidad y reglas conocidas durante toda la tramitación, de modo que compañías y administración sepan qué se valora y cómo se decide. Eliminar los criterios terapéuticos en favor de los económicos, limitar la participación de las comunidades autónomas o reducir la transparencia irían en contra de los principios de rigor, cooperación y rendición de cuentas que inspiran la reforma."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779dc") }, {"long_answer": "La Estrategia propone que los conjuntos de referencia se formen transcurrido un tiempo mínimo de un año desde la entrada en el mercado del primer genérico o biosimilar, de manera que haya un periodo para que la competencia se consolide antes de aplicar el precio de referencia. Un plazo de 6 meses o de 3 años no coincide con el propuesto, y afirmar que no existe un periodo mínimo es incorrecto, ya que precisamente se introduce para dar previsibilidad al sistema."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779e2") }, {"long_answer": "Para fomentar el uso de genéricos y biosimilares, la Estrategia establece un seguimiento con indicadores comunes que permitan medir el impacto de las medidas en el tiempo y en la disponibilidad de estos medicamentos, facilitando la comparación entre territorios. No se descarta realizar proyectos específicos, ya que se promueven planes concretos; tampoco se impone su uso obligatorio al margen del criterio clínico, ni se eliminan los incentivos, que son parte de la estrategia de promoción."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779e7") }, {"long_answer": "El impulso de los ensayos clínicos descentralizados incluye herramientas como el consentimiento informado electrónico, la monitorización remota y la entrega a domicilio de los medicamentos en investigación, lo que facilita la participación de pacientes que viven lejos de los centros y mejora la equidad en el acceso a la investigación. Obligar al reclutamiento presencial en hospitales centrales, eliminar la monitorización remota o prohibir las tecnologías digitales en el reclutamiento son contrarios al propio concepto de descentralización."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779ec") }, {"long_answer": "El desarrollo de Unidades de Investigación Clínica en el SNS debe garantizar un umbral mínimo de dedicación a la investigación clínica independiente y a medicamentos de interés estratégico para el sistema, de modo que no toda la actividad dependa de la iniciativa comercial. Limitarse a investigación financiada por la industria iría en contra de ese equilibrio, restringir la colaboración entre comunidades autónomas e ISCIII debilitaría la red y reducir capacidades para ahorrar presupuesto es contrario a su objetivo de fortalecimiento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779f0") }, {"long_answer": "IMPaCT, la Infraestructura de Medicina de Precisión asociada a la Ciencia y la Tecnología, tiene como objetivo principal mejorar la toma de decisiones clínicas a partir del análisis de grandes volúmenes de datos genómicos, clínicos y de otro tipo, adaptados a las características individuales de cada paciente. No se centra exclusivamente en formar profesionales, ni en abaratar los medicamentos biotecnológicos, ni en aumentar la producción industrial farmacéutica, aunque pueda tener efectos indirectos en estos ámbitos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779f4") }, {"long_answer": "Los planes de matching entre organismos públicos de investigación y el sector industrial farmacéutico buscan incrementar la colaboración público-privada, facilitando la transferencia de conocimiento desde los centros de investigación a las empresas y promoviendo la innovación conjunta. Aumentar la competencia desincentivando acuerdos, centralizar la investigación en órganos estatales o eliminar la cooperación entre academia y empresa son objetivos opuestos a los de estos planes de emparejamiento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779f6") }, {"long_answer": "La Reserva Estratégica basada en las Capacidades Nacionales de Producción Industrial (RECAPI) busca garantizar el suministro y la rápida movilización de capacidad productiva en situaciones excepcionales, como crisis sanitarias o emergencias, para disponer de productos esenciales sin depender del exterior. Externalizar la producción fuera de España, reducir la producción nacional o aumentar la dependencia de terceros países son justamente los riesgos que RECAPI pretende evitar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779f8") }, {"long_answer": "El Fondo de Apoyo a la Inversión Industrial Productiva (FAIIP) ofrece financiación retornable, mediante préstamos y participaciones, para inversiones industriales, y la Estrategia lo identifica como instrumento que favorece la modernización y la sostenibilidad ambiental de la producción farmacéutica. INNVIERTE del CDTI es un programa de capital riesgo para empresas innovadoras, los fondos de ENISA se dirigen a startups y pymes con préstamos participativos, y el fondo de coinversión descrito sin supervisión pública no es el instrumento señalado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779fe") }, {"long_answer": "La colaboración con organizaciones de desarrollo y fabricación por contrato (CDMO) y de investigación por contrato (CRO) especializadas en desarrollo preclínico pretende acercar el ámbito académico y el empresarial, acompañando a los proyectos prometedores hasta que alcanzan las fases clínicas, donde muchos se pierden por falta de capacidades. No implica subcontratar de forma opaca y sin regulación, no busca reducir los ensayos clínicos independientes y no favorece en exclusiva a CRO multinacionales sin presencia local."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779ff") }, {"long_answer": "La Oficina de Innovación y el programa de Asesorías Científicas Nacionales de la AEMPS proporcionan asesoramiento temprano a investigadores y desarrolladores, para orientar el diseño de la investigación clínica y su adecuación a los requisitos regulatorios desde las primeras fases. No se limitan a gestionar ensayos internacionales, no fomentan el uso de medicamentos sin autorización y no actúan como órgano sancionador, sino como servicio de apoyo y acompañamiento a la innovación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a06") }, {"long_answer": "La Estrategia promueve la digitalización y la sostenibilidad ambiental de la industria farmacéutica mediante ayudas a proyectos como la línea Industria Conectada 4.0 y el programa Activa Financiación, que financian la transformación digital y la modernización de los procesos productivos. Limitar el uso de tecnologías digitales, aumentar la producción sin considerar el impacto ambiental o centralizar los procesos en multinacionales sin apoyo estatal son contrarios a los objetivos de transformación y sostenibilidad del sector."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a07") }, {"long_answer": "La Estrategia Farmacéutica para Europa establece un marco regulador al que se alinea la regulación española, orientado a fomentar la investigación y la innovación y a corregir deficiencias del mercado, como la falta de tratamientos para necesidades no cubiertas o los problemas de suministro. No se centra exclusivamente en reducir costes, no ignora las necesidades de los sistemas sanitarios nacionales, ya que busca precisamente atenderlas, y no prohíbe la colaboración público-privada, que se considera necesaria para la innovación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a09") }, {"long_answer": "Para mejorar la seguridad y la transparencia del suministro farmacéutico, la Estrategia apoya acciones legislativas europeas como la Ley de Medicamentos Críticos y la modificación de la contratación pública para incorporar criterios cualitativos, como la resiliencia y diversificación del suministro, además del precio. Restringir la producción europea de genéricos, excluir a fabricantes europeos de los contratos públicos o vetar innovaciones no certificadas por terceros países irían en contra del objetivo de fortalecer la cadena de suministro en la Unión."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a0c") }, {"long_answer": "Para promover la transparencia en la publicación de resultados de ensayos clínicos financiados con fondos públicos, se prevé incluir en los contratos tipo cláusulas que aseguren la difusión de los resultados y un procedimiento de comunicación a las autoridades competentes. Permitir la publicación solo en medios privados sin supervisión, restringir la comunicación hasta la comercialización o conceder exclusividad a la industria sin obligación de reporte reducirían la transparencia que se pretende garantizar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a0d") }, {"long_answer": "Dentro de CERTERA, la plataforma de terapias avanzadas, el ISCIII coordina y articula los distintos nodos participantes, integrando infraestructuras de producción y desarrollo y facilitando las alianzas con el sector industrial para acercar estas terapias a los pacientes. No se limita a financiar ensayos clínicos internacionales, no se dedica a la producción de medicamentos genéricos y su papel no es solo apoyar la investigación básica, ya que busca precisamente la conexión con la industria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a14") }, {"long_answer": "El Plan identifica a las personas mayores como un grupo especialmente vulnerable, ya que la soledad no deseada, la pérdida de roles, las enfermedades crónicas y el dolor aumentan el riesgo de conducta suicida, que alcanza tasas elevadas en edades avanzadas, sobre todo en varones. Adolescentes y jóvenes, personas LGTBIQ+ y personas con discapacidad son también colectivos vulnerables en el Plan, pero la combinación de soledad no deseada y enfermedades crónicas se describe específicamente en relación con las personas mayores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a16") }, {"long_answer": "Los consumidores habituales de alcohol sin diagnóstico formal no figuran como uno de los grupos en situación de vulnerabilidad recogidos en el Plan, que habla de trastornos por consumo de sustancias dentro de los factores clínicos, no de este colectivo concreto. En cambio, el Plan sí incluye expresamente entre los grupos vulnerables a las personas que sufren violencia, a las que padecen enfermedades graves o dolor y a las que se encuentran en riesgo de pobreza y exclusión social."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a1a") }, {"long_answer": "La Ley Orgánica 8/2021, de protección integral a la infancia y la adolescencia frente a la violencia, establece que las comunidades autónomas desarrollen protocolos de actuación intersectoriales en el ámbito educativo frente a distintas formas de violencia, incluidas las conductas autolíticas y el suicidio. No se limita a exigir formación a los docentes, no prevé sanciones para estudiantes con conductas suicidas, que serían contraproducentes y estigmatizantes, y tampoco prohíbe abordar el suicidio en las aulas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a1b") }, {"long_answer": "La Ley Orgánica 8/2021 crea en los centros educativos la figura del coordinador o coordinadora de bienestar y protección del alumnado, cuya función es promover medidas que aseguren el bienestar de niños, niñas y adolescentes y fomentar la cultura del buen trato, actuando como referente ante situaciones de violencia. No le corresponde supervisar el rendimiento académico, imponer disciplina mediante sanciones ni gestionar los recursos económicos del centro."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a26") }, {"long_answer": "El Plan destaca a adolescentes y jóvenes como el grupo en el que ha aumentado el sufrimiento emocional, con un incremento de conductas autolesivas e ideación suicida, y en el que es necesario promover espacios saludables y libres de violencia, incluido el entorno digital. Las personas mayores, las personas con discapacidad y las personas privadas de libertad son también colectivos vulnerables, pero sus factores de riesgo se describen en relación con otros aspectos, como la soledad, la discriminación o el entorno penitenciario."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a28") }, {"long_answer": "En las personas con enfermedades graves o dolor, el Plan señala que el sufrimiento emocional y los sentimientos de desesperanza asociados a su situación afectan negativamente a su bienestar y aumentan el riesgo de conducta suicida, por lo que requieren una atención integral que incluya la esfera psicológica. El acceso a tratamientos médicos, el apoyo social intensivo y la vigilancia comunitaria no son factores que perjudiquen su bienestar; al contrario, el apoyo social es un factor protector."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a2a") }, {"long_answer": "El sistema de vigilancia en salud mental aplicado a la prevención del suicidio tiene la función de proporcionar información relevante sobre persona, lugar y tiempo, es decir, quién, dónde y cuándo se producen las conductas suicidas, para orientar la toma de decisiones y priorizar intervenciones. No debe registrar solo los suicidios consumados, ya que los intentos son un indicador clave de riesgo; no centraliza el tratamiento, y tampoco excluye los entornos educativos y laborales, que son ámbitos relevantes de prevención."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a2e") }, {"long_answer": "La estrategia estatal de Recursos Humanos en Atención Primaria que debe elaborarse antes de 2027 pretende garantizar la accesibilidad, la longitudinalidad, la estabilidad de las plantillas, la atracción de talento y la reducción de la temporalidad, pilares para un primer nivel asistencial sólido. Reducir profesionales para ahorrar, concentrar el trabajo en pocas especialidades o incrementar la temporalidad y la rotación son contrarios a esos objetivos y perjudicarían la continuidad de la atención."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a2f") }, {"long_answer": "El Plan establece que las comunidades autónomas elaboren un plan de recursos humanos para Atención Primaria a 10 años, basado en la estrategia estatal y en las recomendaciones previamente consensuadas, de modo que la planificación de plantillas tenga una perspectiva de medio y largo plazo. Suspender cualquier plan hasta 2027, esperar directrices europeas o limitar la planificación a hospitales de referencia impedirían abordar el déficit de profesionales que afecta al primer nivel asistencial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a32") }, {"long_answer": "La indicación, uso y autorización de dispensación de medicamentos y productos sanitarios por parte de las enfermeras está regulada por el Real Decreto 954/2015 y sus modificaciones posteriores, especialmente el Real Decreto 1302/2018, que desarrollan el marco para la elaboración de guías y protocolos de actuación. El Real Decreto 300/2010 no regula este ámbito, la Ley General de Sanidad de 1986 es una norma general del sistema sanitario y no es cierto que solo exista normativa autonómica, ya que la regulación es estatal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a36") }, {"long_answer": "La ampliación progresiva de la cartera común de salud bucodental del SNS se orienta a garantizar la equidad en el acceso a estas prestaciones, priorizando colectivos como la población infantojuvenil, las embarazadas, las personas con discapacidad y los mayores de 65 años, que tienen mayor necesidad o menor acceso a la atención dental. Ofrecer solo tratamientos estéticos no es un objetivo sanitario, reducir la cartera iría en sentido contrario a la ampliación y concentrar los servicios en grandes hospitales se aleja de su prestación en Atención Primaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a37") }, {"long_answer": "El Plan de Ampliación de la cartera de salud bucodental fija como meta que en 2027 el 70% del colectivo priorizado reciba las nuevas prestaciones, lo que refleja una implantación progresiva con un objetivo de cobertura elevado. Los porcentajes del 50% y del 30% quedan por debajo de la meta establecida, y el 90% no corresponde al objetivo fijado en el documento para ese año."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a38") }, {"long_answer": "La reingeniería de los procesos administrativos en Atención Primaria busca eliminar pasos innecesarios y facilitar la incorporación de avances tecnológicos, con el fin de aligerar la carga administrativa que soportan los profesionales y dedicar más tiempo a la atención directa. Incrementar la burocracia, eliminar los sistemas digitales o externalizar todos los procesos a empresas privadas son medidas opuestas a la simplificación y modernización que persigue el Plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a3c") }, {"long_answer": "El Plan prevé que, antes de 2027, todas las comunidades autónomas hayan implantado herramientas de inteligencia artificial orientadas a la transcripción conversacional en las consultas, que registran automáticamente la información de la entrevista clínica y reducen el tiempo de documentación. No se limita a hospitales terciarios, ya que el foco es Atención Primaria; no se plantea restringir su uso por deficiencias técnicas y tampoco se pospone indefinidamente, puesto que tiene un plazo definido."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a40") }, {"long_answer": "Para seleccionar un modelo de gestión integral de la demanda como recomendación nacional, el Plan se basa en la evaluación de las buenas prácticas desarrolladas en las comunidades autónomas y en el mapa de competencias de los profesionales de Atención Primaria, de forma que cada demanda sea atendida por el profesional más adecuado. Los sondeos internacionales estandarizados no son la base de la selección, y aplicar una tecnología sin consenso o elegir de forma unilateral sin los profesionales contradice el enfoque participativo del Plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a41") }, {"long_answer": "El Plan fija como meta que el 100% de las comunidades autónomas cuenten con planes autonómicos de renovación de infraestructuras y equipamiento antes de diciembre de 2025, para adecuar los centros de salud a la cartera de servicios actualizada. Los porcentajes del 75% y del 60% no corresponden a la meta establecida, y afirmar que no se fija ningún objetivo es incorrecto, ya que se trata de una acción con plazo e indicador definidos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a42") }, {"long_answer": "El Plan establece la actualización anual de las acciones priorizadas en las Estrategias y Planes nacionales del SNS que afectan a Atención Primaria, de modo que los equipos trabajen con objetivos vigentes y coordinados con el resto del sistema. Las normas internas de cada hospital sin coordinación no se refieren al primer nivel, las instrucciones sin evidencia científica contradicen la práctica basada en pruebas y las recomendaciones exclusivas de sociedades farmacéuticas no son el marco de referencia previsto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a44") }, {"long_answer": "En el abordaje de la persona mayor polimedicada, el Plan prioriza las situaciones de mayor riesgo: el uso de 8 o más fármacos, la conciliación de la medicación en las transiciones asistenciales y los medicamentos de alto riesgo, que concentran la mayor parte de los eventos adversos evitables. Reducir solo los fármacos cardiovasculares es un enfoque parcial, evitar toda medicación sin evaluación es inadecuado y potencialmente peligroso, y no priorizar ningún grupo farmacológico iría en contra de la estrategia de centrar la revisión en lo más relevante."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a48") }, {"long_answer": "El Registro Estatal de Profesionales Sanitarios es importante para la estrategia estatal de recursos humanos en Atención Primaria porque permite disponer de datos fiables sobre el número, la distribución y las características de los profesionales, imprescindibles para planificar y hacer seguimiento de las plantillas. No es cierto que carezca de relevancia en la planificación, no sirve solo para la gestión económica y no se limita al ámbito hospitalario, ya que incluye a todos los profesionales sanitarios."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a4d") }, {"long_answer": "El Plan prevé la implantación progresiva en Atención Primaria de un instrumento estandarizado, aprobado por el Consejo Interterritorial del SNS, para la detección temprana de la violencia de género, de modo que todos los profesionales utilicen una herramienta común y validada. Un cuestionario domiciliario no estructurado carece de la sistematización necesaria, la evaluación psicológica en atención especializada no es una herramienta de detección precoz en el primer nivel y un registro confidencial entre servicios sociales no es el instrumento de cribado descrito."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a4e") }, {"long_answer": "El plan de formación específica en violencia de género incluye a los equipos de Atención Primaria, de Salud Mental y de atención al embarazo, parto y puerperio, ámbitos en los que es más probable detectar situaciones de violencia y en los que la mujer puede ser especialmente vulnerable, como durante la gestación. Limitarlo solo a Atención Primaria o solo a Salud Mental deja fuera ámbitos clave, y los equipos hospitalarios y de emergencias no son los incluidos en esta formación específica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a55") }, {"long_answer": "Para mejorar la continuidad asistencial en personas con problemas de salud mental, el Plan propone promover programas colaborativos entre Atención Primaria y Salud Mental, que permiten compartir casos, protocolos y formación, y atender en el primer nivel a muchas personas con problemas leves o moderados. Derivar siempre sin seguimiento en Atención Primaria fragmenta la atención, reducir las visitas al primer nivel resta accesibilidad y limitar la comunicación entre profesionales es contrario a la coordinación que se busca."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a57") }, {"long_answer": "En los pacientes polimedicados, el Plan promueve la optimización de la terapia farmacológica con la participación conjunta de farmacéuticos y prescriptores, mediante la revisión de la medicación para detectar duplicidades, interacciones o fármacos innecesarios y ajustar el tratamiento a los objetivos de cada persona. Mantener las prescripciones sin revisar perpetúa los riesgos, trasladar el seguimiento a la consulta hospitalaria aleja la atención del primer nivel y limitar la revisión a enfermería excluye a otros profesionales necesarios."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a58") }, {"long_answer": "El Plan fomenta la participación comunitaria integrando a las comunidades en los procesos de toma de decisiones sobre las políticas sanitarias de Atención Primaria y Comunitaria, mediante estructuras como consejos de salud y procesos participativos que recogen las necesidades de la población. Centralizar las decisiones sin consulta, limitar la participación a profesionales sanitarios o eliminar las consultas comunitarias para acelerar trámites son contrarios a la orientación comunitaria que el Plan pretende reforzar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a59") }, {"long_answer": "El modelo de cálculo de necesidades de recursos humanos en Atención Primaria se caracteriza por basarse en la morbilidad de la población, los resultados en salud y sus características sociodemográficas, superando el cálculo tradicional basado solo en el número de tarjetas sanitarias. Calcular según la plantilla actual sin considerar la demanda, asignar recursos iguales en todas las zonas sin análisis o planificar solo especialidades hospitalarias no permitirían ajustar los recursos a las necesidades reales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a5d") }, {"long_answer": "En formación sanitaria especializada, el Plan prevé aprobar en 2027 los nuevos programas formativos de Enfermería Familiar y Comunitaria y de Enfermería Obstétrico-Ginecológica, actualizando las competencias que adquieren los residentes de estas especialidades vinculadas a Atención Primaria. No se plantea eliminar la especialidad de Enfermería Familiar y Comunitaria, que se quiere reforzar; tampoco una formación única sin diferenciación entre especialidades ni trasladar la formación a universidades extranjeras."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a61") }, {"long_answer": "En el análisis de procesos resolubles en Atención Primaria antes de 2027, el Plan prioriza aprobar y jerarquizar aquellos procesos de salud que pueden resolverse en el primer nivel, con el objetivo de lograr un incremento significativo de su capacidad resolutiva y evitar derivaciones innecesarias. La derivación sistemática a especialistas hospitalarios, la disminución de procesos atendidos en Atención Primaria o la exclusión de las patologías crónicas son contrarias a este objetivo, ya que la cronicidad es precisamente uno de los ámbitos propios del primer nivel."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a62") }, {"long_answer": "El modelo de gestión integral de la demanda implica la intervención del conjunto de profesionales del equipo de Atención Primaria según un mapa de competencias adaptado a las necesidades de la ciudadanía, de forma que cada demanda sea resuelta por el profesional más adecuado, incluidas enfermería y personal administrativo. La derivación inmediata al médico sin gestión previa, una gestión puramente administrativa sin participación clínica o la descentralización sin coordinación no responden a este modelo de trabajo en equipo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a6d") }, {"long_answer": "La Comisión de Atención Primaria y Comunitaria (CAPYCO) tiene, en relación con el Plan 2025-2027, la función de debatir y validar los criterios de distribución de los créditos destinados a las comunidades autónomas para desarrollar las acciones previstas. No ejecuta directamente las acciones, que corresponden a las administraciones competentes; no se limita a supervisar indicadores de salud mental y no gestiona la financiación de infraestructuras hospitalarias, ajenas al ámbito del Plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a72") }, {"long_answer": "El Plan establece que antes de finalizar 2025 se presente y apruebe en la Comisión de Recursos Humanos del SNS un modelo común de recertificación de los profesionales sanitarios, que permita acreditar periódicamente que mantienen actualizadas sus competencias. Un programa de formación en gestión administrativa no es el objeto de esta acción, un plan exclusivo para médicos especialistas hospitalarios no se ajusta al ámbito de Atención Primaria ni al carácter común del modelo y un protocolo de desvinculación de temporales no guarda relación con la recertificación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a7d") }, {"long_answer": "Para evaluar el impacto del Plan de Acción 2025-2027 se emplean indicadores definidos de resultados en salud y de accesibilidad, que permiten valorar si las acciones se traducen en mejoras reales para la población y en el funcionamiento de Atención Primaria. Las encuestas de satisfacción por sí solas ofrecen una visión parcial, la monitorización de llamadas telefónicas solo recoge un aspecto concreto de la actividad y el análisis exclusivo de costes no permite valorar los resultados en salud."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a82") }, {"long_answer": "El Plan fija como meta que, en diciembre de 2027, el 100% de las comunidades autónomas tengan aprobada una oferta de empleo anual para todas las categorías profesionales de Atención Primaria, lo que favorece la estabilidad de las plantillas y la reducción de la temporalidad. Los porcentajes en torno al 75%, el 50% o inferiores al 30% no corresponden al objetivo establecido, que busca que la medida alcance a todo el territorio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a84") }, {"long_answer": "En relación con el modelo común de recertificación, las comunidades autónomas deben incluir en su plan anual de formación acciones específicas sobre recertificación profesional en Atención Primaria, para que los profesionales conozcan el modelo y puedan cumplir sus requisitos. Los cursos de inglés, los entrenamientos tecnológicos sin relación clínica o la especialización en cirugía general no se vinculan con la recertificación ni con las competencias propias del primer nivel asistencial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a85") }, {"long_answer": "Para promover el retorno a Atención Primaria, el Plan propone reservar en los concursos de traslado un porcentaje común de plazas para enfermeras especialistas en Enfermería Familiar y Comunitaria que trabajan en el ámbito hospitalario, de forma que puedan incorporarse a puestos acordes con su especialidad. Los médicos especialistas en cirugía ambulatoria, los técnicos de laboratorio hospitalario y el personal administrativo hospitalario no son el colectivo al que se dirige esta medida."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779c0") }, {"long_answer": "Para fomentar el uso de genéricos y biosimilares, la Estrategia incluye la implementación de planes específicos que aumenten su utilización y mejoren su accesibilidad, ya que la competencia que introducen genera ahorros que permiten financiar la innovación. Imponer precios elevados reduciría su atractivo y su ventaja económica, eliminar su financiación sería contrario a su promoción y evitar sistemas de información sobre su consumo impediría hacer el seguimiento que la propia Estrategia prevé."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779c1") }, {"long_answer": "La Estrategia destaca que España es el primer país europeo en número de ensayos clínicos con medicamentos y que a nivel mundial solo la superan Estados Unidos y China, gracias a la calidad de sus centros, sus investigadores y la agilidad de su marco regulatorio. Decir que no tiene relevancia en investigación clínica, que se centra en ensayos con genéricos o que ha limitado su participación internacional contradice esta posición de liderazgo.", "option_1": "Es el primer país europeo en ensayos clínicos y, a nivel mundial, solo le superan Estados Unidos y China."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779c3") }, {"long_answer": "La Estrategia busca transformar la relación tradicional entre la industria farmacéutica y las instituciones públicas, basada en un esquema de proveedor-cliente, en un modelo de colaboración con dinámicas virtuosas que integren investigación, producción y acceso a los medicamentos. No se describe como una alianza ya consolidada que no requiere cambios, ni como una relación tercerizada sin innovación conjunta, y tampoco como una dependencia exclusiva de la industria extranjera, ya que el documento parte precisamente de reforzar la colaboración con el tejido industrial que opera en España.", "option_4": "Una relación de dependencia exclusiva de la industria extranjera."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779c5") }, {"long_answer": "El Plan de Recuperación, Transformación y Resiliencia constituye el marco en el que se inscribe la Estrategia de la Industria Farmacéutica, ya que favorece las reformas e inversiones necesarias para que España refuerce su liderazgo en innovación y su autonomía estratégica en el ámbito de la salud. No es cierto que no tenga relación con la Estrategia o que se oponga a sus líneas de acción, y tampoco se limita a financiar infraestructuras sanitarias físicas, ya que incluye investigación, digitalización y capacidades industriales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779cd") }, {"long_answer": "La Estrategia de la Industria Farmacéutica se alinea con la Estrategia Farmacéutica para Europa y contribuye a sus objetivos compartidos de innovación, acceso equitativo a los medicamentos y sostenibilidad de los sistemas sanitarios. No responde a políticas independientes sin coordinación, no se centra exclusivamente en el mercado español sin relación con la Unión Europea y no pretende eliminar la colaboración con las agencias europeas, que es esencial en el marco regulatorio de los medicamentos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779d0") }, {"long_answer": "El Reglamento (UE) 2021/2282 sobre evaluación de tecnologías sanitarias regula únicamente la evaluación de los aspectos clínicos de medicamentos y productos sanitarios mediante evaluaciones clínicas conjuntas a escala europea, mientras que los aspectos no clínicos, como los económicos, éticos u organizativos, siguen siendo competencia de cada Estado miembro. Por ello no evalúa aspectos clínicos y no clínicos a la vez, no se limita a los aspectos económicos y no excluye a los medicamentos, que son uno de sus ámbitos principales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779d2") }, {"long_answer": "La modificación del artículo 92 de la Ley de Garantías y Uso Racional de los Medicamentos establece como regla general que el uso compasivo de medicamentos antes de su autorización de comercialización sea gratuito para el paciente, salvo en casos justificados, con el fin de garantizar el acceso equitativo a tratamientos en situaciones especiales. No es correcto que lo pague siempre el paciente, no se limita a medicamentos ya autorizados, ya que se refiere precisamente a los no autorizados, y no está prohibido."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779d3") }, {"long_answer": "La sistematización de los cauces de interacción temprana, el llamado early dialogue, entre compañías y administración pretende mejorar la coordinación entre las distintas estructuras del sistema sanitario que intervienen en la regulación, la evaluación y la financiación, de modo que los desarrolladores reciban orientaciones coherentes desde fases tempranas. No busca reducir la inversión privada en I+D, no se limita a la transferencia tecnológica preclínica y no pretende centralizar las decisiones exclusivamente en la administración."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779d5") }, {"long_answer": "La Estrategia contempla una financiación acelerada, de carácter provisional o condicionado, para determinados medicamentos, sujeta a revisión posterior a medida que se disponga de más evidencia y sin que esta vía tenga repercusión en la fase de negociación del precio. No se trata de una financiación sin revisiones futuras, no se aplica solo a genéricos y biosimilares, que no presentan la incertidumbre que justifica esta vía, y no excluye las áreas de alta incertidumbre clínica, que son precisamente su ámbito natural."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779d8") }, {"long_answer": "Entre los objetivos de la reforma del procedimiento de inclusión de nuevos medicamentos en la prestación farmacéutica figura consolidar fases de instrucción y de resolución diferenciadas e independientes, lo que refuerza la objetividad y la transparencia de las decisiones. Reducir la evaluación económica, eliminar los criterios clínicos en favor del precio o delegar la evaluación en la industria farmacéutica irían en contra del rigor e independencia que persigue la reforma."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779da") }, {"long_answer": "Para mejorar la evaluación económica en la fijación de precios, la Estrategia propone tener en cuenta la incertidumbre financiera y el análisis del impacto presupuestario, de manera que las decisiones consideren no solo el valor del medicamento, sino también su efecto sobre la sostenibilidad del sistema. Limitarse a los costes directos sin impacto económico, basarse solo en precios internacionales o analizar un supuesto beneficio sin fines económicos no permiten una evaluación económica completa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779df") }, {"long_answer": "Según la Estrategia, el reposicionamiento de medicamentos que ya han perdido los periodos de protección permitirá reconocer nuevas indicaciones a instancia de terceros sin ánimo de lucro, como grupos académicos o sociedades científicas, y sin que ello suponga una penalización en el precio del medicamento. No se reserva solo a las empresas comerciales, no implica una reducción automática del precio y sí se contempla como medida dentro del marco que propone la Estrategia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779e1") }, {"long_answer": "Para completar la incorporación de biomarcadores en el SNS se considera imprescindible facilitar el intercambio de datos genómicos con garantías de seguridad y protección de datos, ya que la medicina de precisión requiere compartir información entre centros y comunidades para que las pruebas sean útiles y equitativas. Permitir actividades autonómicas sin coordinación generaría desigualdades, limitar el diagnóstico molecular a centros privados restringiría el acceso y excluir los biomarcadores de la cartera impediría su uso en la práctica clínica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779e3") }, {"long_answer": "La disposición adicional sexta de la Ley de Garantías, que regula las aportaciones de la industria por volumen de ventas al SNS, se actualizará para ampliar los ámbitos de venta de medicamentos financiados incluidos y para incorporar criterios ambientales en el cálculo de las aportaciones. Reducir los ámbitos de dispensación, eliminar los criterios relacionados con la huella de carbono o centrarse solo en medicamentos hospitalarios son contrarios a la ampliación y a la orientación ambiental que se plantea."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779e6") }, {"long_answer": "La investigación en Atención Primaria se fomentará mediante la creación de unidades de investigación clínica y de programas desarrollados en colaboración entre el ISCIII y las comunidades autónomas, para que los profesionales del primer nivel dispongan de estructuras de apoyo y puedan participar en ensayos y estudios. Confinar la investigación a hospitales especializados, evitar los ensayos descentralizados o eliminar la investigación cooperativa en red son medidas contrarias a este impulso."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779ea") }, {"long_answer": "Entre las estructuras que se reforzarán como soporte a la investigación biomédica figuran los CIBER, la plataforma SCReN de ensayos clínicos, los Institutos de Investigación Sanitaria, el CSIC, el CIEMAT y las universidades, que conforman el ecosistema público de investigación en España. Limitarse a las universidades públicas, a los departamentos privados de I+D o a centros privados internacionales no refleja la amplitud de estructuras que la Estrategia pretende fortalecer."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779eb") }, {"long_answer": "Para fortalecer la investigación en el SNS se priorizarán recursos humanos específicos como los contratos de gestión de la investigación en los Institutos de Investigación Sanitaria, el personal bioinformático, la enfermería especializada en investigación y la farmacia hospitalaria, entre otros perfiles de apoyo. Contar solo con médicos especialistas sin otros profesionales, limitarse a personal administrativo o externalizar la investigación a empresas privadas no permitiría construir equipos multidisciplinares estables."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779f9") }, {"long_answer": "TERAFRONT es una sociedad mercantil de capital mixto en la que el 51% corresponde al socio privado y el 49% a la participación pública, aportada por el CDTI a través de su programa INNVIERTE, lo que permite combinar el impulso público con la gestión empresarial en el desarrollo de terapias avanzadas. No es una entidad 100% pública ni totalmente privada, y afirmar que no tiene participación del CDTI es incorrecto, ya que este organismo es precisamente el socio público."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779fa") }, {"long_answer": "El Pool de Patentes de Medicamentos (Medicines Patent Pool) se cita en la Estrategia como ejemplo de colaboración público-privada para facilitar el acceso a tecnologías sanitarias con responsabilidad social, ya que negocia licencias voluntarias con los titulares de patentes para que fabricantes de genéricos produzcan medicamentos asequibles para países de ingresos bajos y medios. No es una organización privada sin supervisión pública, ni un programa de formación de pacientes, ni un fondo para adquirir equipos médicos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a10") }, {"long_answer": "El Plan recoge que, ante la limitada capacidad predictiva de los factores de riesgo aislados, se proponen modelos basados en algoritmos de aprendizaje automático que integran múltiples variables clínicas, psicológicas y sociales para estimar mejor el riesgo de conducta suicida. Los modelos exclusivos para adolescentes, los centrados solo en factores individuales o los que excluyen variables sociales serían más limitados, precisamente porque la conducta suicida es multifactorial y requiere integrar distintas dimensiones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a1d") }, {"long_answer": "Uno de los objetivos principales del Plan de prevención del suicidio es reducir el estigma asociado a la conducta suicida, porque el estigma dificulta que las personas en riesgo y sus allegados pidan ayuda y que se hable del problema de forma abierta y responsable. Incrementar la hospitalización obligatoria no es un objetivo del Plan, limitar la información pública contradice la sensibilización y la comunicación responsable, y fomentar el aislamiento social aumentaría el riesgo, ya que la conexión social es un factor protector."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a20") }, {"long_answer": "El Grupo Motor del Plan de prevención del suicidio se encarga de diseñar las líneas estratégicas y de colaborar con personas expertas, instituciones, sociedades científicas y personas con experiencia vivida para desarrollarlas, actuando como órgano de impulso y coordinación técnica. No realiza intervenciones clínicas directas, no gestiona el presupuesto del Sistema Nacional de Salud y no tiene funciones de supervisión del cumplimiento de la normativa general."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a25") }, {"long_answer": "Fuera del ámbito sanitario, el Plan prioriza la implantación de programas de prevención del suicidio en escuelas, comunidades, lugares de trabajo, prisiones y fuerzas armadas, entornos donde se concentran personas en riesgo y donde es posible detectar señales de alarma y promover factores protectores. Los hospitales y centros de salud mental pertenecen al ámbito sanitario, y limitarse a zonas rurales o a áreas urbanas densas dejaría fuera a gran parte de la población y de los entornos clave."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a3d") }, {"long_answer": "La identificación y definición de procesos de salud susceptibles de resolverse en Atención Primaria antes de 2027 busca mejorar su capacidad resolutiva, mediante un consenso con las comunidades autónomas, las sociedades científicas y las asociaciones de pacientes que garantice la viabilidad y aceptación de los procesos seleccionados. Limitar las funciones de Atención Primaria para delegarlas en el hospital, eliminar procesos no invasivos u obligar a derivar todos los procesos son contrarios a este objetivo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a3f") }, {"long_answer": "El modelo de gestión integral de la demanda que se publicará en 2027 tiene como finalidad atender de forma eficaz y satisfactoria las necesidades de los pacientes y promover una gestión preventiva y proactiva de la salud, en lugar de limitarse a responder a la demanda espontánea. Concentrar la demanda en el hospital, eliminar la coordinación entre profesionales de Atención Primaria o reducir las consultas presenciales al mínimo no responden a los principios de accesibilidad y trabajo en equipo del modelo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a45") }, {"long_answer": "En relación con el Plan de Prevención de la Fragilidad en la persona mayor, el objetivo fijado para 2027 es que el 50% de las comunidades autónomas presenten evidencias de la implementación del documento de consenso actualizado sobre prevención de la fragilidad y las caídas. Que solo lo implementen hospitales públicos es contrario a su enfoque, centrado en Atención Primaria y la comunidad; hospitalizar a toda la población mayor no tiene sentido preventivo y reducir los recursos para las personas mayores iría en sentido contrario al Plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a4a") }, {"long_answer": "El objetivo principal de implantar las recomendaciones de no hacer en Atención Primaria es adecuar la práctica clínica a la evidencia científica para mejorar la calidad y la seguridad de la atención, evitando pruebas, tratamientos o intervenciones que no aportan beneficio o pueden causar daño. Aunque reducir procedimientos innecesarios puede generar ahorros, el ahorro de costes es una consecuencia y no el objetivo principal; mejorar la precisión diagnóstica en atención especializada no es su ámbito y aumentar las visitas programadas no se relaciona con estas recomendaciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a4b") }, {"long_answer": "El Plan de Acción prioriza, en la persona mayor polimedicada, a quienes utilizan 8 o más fármacos y la conciliación de la medicación, especialmente en las transiciones entre niveles asistenciales, ya que son las situaciones con mayor riesgo de errores, interacciones y efectos adversos. Aumentar la prescripción de antibióticos con fines preventivos favorece las resistencias, suspender todos los medicamentos sin valoración puede descompensar enfermedades y aumentar los controles hospitalarios no responde al abordaje desde Atención Primaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a4f") }, {"long_answer": "En línea con el Plan Estratégico Nacional para la reducción de la obesidad infantil, en Atención Primaria se promueve el apoyo a la lactancia materna siguiendo las recomendaciones de la Iniciativa para la Humanización de la Asistencia al Nacimiento y la Lactancia (IHAN), dado que la lactancia materna protege frente al exceso de peso en la infancia. La promoción exclusiva de dietas hipocalóricas no es adecuada en niños, las campañas de actividad física intensiva no son la medida descrita y el uso rutinario de suplementos no está indicado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a52") }, {"long_answer": "En materia de sistemas de información, el Plan impulsa mejoras en la medición de la calidad de Atención Primaria y el benchmarking entre comunidades autónomas, lo que permite comparar resultados, identificar buenas prácticas y orientar la mejora continua. Externalizar completamente la gestión de los datos sanitarios plantea problemas de control y confidencialidad, reducir indicadores clínicos empobrece la evaluación y eliminar las comparaciones entre comunidades es contrario al objetivo de aprendizaje compartido."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a54") }, {"long_answer": "Dentro de la línea 6, el Plan considera imprescindible reforzar la atención domiciliaria de los equipos de Atención Primaria, porque permite atender a personas con dependencia, enfermedades crónicas avanzadas o necesidades paliativas en su entorno, mejorando la continuidad de los cuidados y evitando ingresos. El acceso preferente a pruebas hospitalarias, la formación en cirugía menor o la gestión administrativa centralizada pueden ser útiles, pero no son la actividad que el Plan señala como imprescindible reforzar en esta línea."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a5a") }, {"long_answer": "El modelo de recertificación profesional propuesto para Atención Primaria busca una acreditación periódica que garantice que los profesionales mantienen actualizada su competencia a lo largo de su carrera, vinculando el ejercicio profesional a la formación y el desarrollo continuos. Eliminar los requisitos de actualización, conceder una certificación única sin formación continua o limitar la evaluación al personal médico contradicen el propio concepto de recertificación, que se plantea para todos los profesionales sanitarios."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a5c") }, {"long_answer": "La estrategia estatal de Recursos Humanos para Atención Primaria debe garantizar la accesibilidad de la población a sus profesionales, la longitudinalidad de la atención, la estabilidad de las plantillas, la atracción del talento y la reducción de la temporalidad, condiciones necesarias para un primer nivel asistencial resolutivo. Aumentar la rotación rápida del personal, priorizar la temporalidad o desvincular a los profesionales de su comunidad perjudicarían la continuidad asistencial y la relación con los pacientes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a6b") }, {"long_answer": "Uno de los objetivos del Plan de Acción de Atención Primaria y Comunitaria 2025-2027 es mejorar la capacidad de resolución y la gestión de la demanda en Atención Primaria, de forma que el primer nivel pueda resolver más problemas de salud y atender a la población con mayor agilidad. Reducir el número de centros de salud urbanos, aumentar la especialización hospitalaria en áreas rurales o instalar unidades móviles de atención especializada no figuran entre sus objetivos y no refuerzan la Atención Primaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a6e") }, {"long_answer": "En 2024 se destinaron 85 millones de euros a financiar acciones de formación y de mejora en Atención Primaria basadas en la evidencia, distribuidos entre las comunidades autónomas para desarrollar las líneas del marco estratégico. Las cifras de 493 millones para digitalización, 172 millones para equipamiento hospitalario o 50 millones para campañas de vacunación no corresponden a la asignación descrita para formación y mejora de Atención Primaria en ese año."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a70") }, {"long_answer": "Para la monitorización de las ofertas de empleo en Atención Primaria en 2024, el indicador clave es el porcentaje de comunidades autónomas con la convocatoria de estabilización resuelta antes del 31 de diciembre de 2024, en relación con los procesos destinados a reducir la temporalidad. El número de plazas ofertadas en hospitales, el índice de rotación en atención especializada o el número de cursos impartidos no miden la estabilización del empleo en Atención Primaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a71") }, {"long_answer": "Para mejorar la organización y las condiciones laborales en Atención Primaria, el Plan prevé alcanzar en la Comisión de Recursos Humanos del SNS un acuerdo con compromiso de seguimiento y evaluación antes de 2027, de forma que las medidas pactadas se apliquen y se pueda comprobar su cumplimiento. Reducir la jornada sin cambios retributivos, incluir clínicos en cargos administrativos nacionales o derivar a los pacientes crónicos a otros niveles no son los resultados previstos para esta acción."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a73") }, {"long_answer": "El Plan establece que el 100% de las comunidades autónomas incluyan en su plan de formación acciones específicas sobre el modelo común de recertificación antes del primer semestre de 2026, para que su implantación sea homogénea en todo el SNS. Los porcentajes del 70% y del 50% no corresponden a la meta fijada, y no es una medida voluntaria, ya que forma parte de las acciones con objetivo e indicador definidos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a74") }, {"long_answer": "El modelo común para calcular las necesidades de recursos humanos en Atención Primaria debe basarse en la morbilidad de la población, en los resultados en salud y en sus características sociodemográficas, de modo que las plantillas se ajusten a la complejidad real de cada zona. Contar solo el número de médicos activos, considerar exclusivamente a la población mayor de 65 años o fijar un número fijo de profesionales por centro ignorarían las diferencias de necesidades entre territorios."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a75") }, {"long_answer": "El Plan prevé que en 2026 todas las comunidades autónomas hayan identificado, según el modelo común aprobado, las necesidades de plantilla de al menos el 50% de sus áreas de salud, como primer paso para adecuar los recursos humanos a las necesidades reales. Reducir la plantilla rural un 10% o establecer contratos temporales en el 75% de los centros contradicen los objetivos de suficiencia y estabilidad, y crear unidades exclusivas de cuidados paliativos no es la medida vinculada a este modelo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a7c") }, {"long_answer": "En la mejora continua de la formación sanitaria especializada en Atención Primaria, el objetivo es asegurar la estabilidad de las unidades docentes y la calidad de las comisiones de docencia, sometidas a auditorías, para garantizar una formación de residentes de calidad en el primer nivel asistencial. Reducir a la mitad la duración de los programas, excluir la formación en atención comunitaria o privatizar la formación son medidas contrarias a la calidad y al enfoque comunitario de estas especialidades."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a83") }, {"long_answer": "El Plan 2025-2027 fija como indicador de ajuste de la temporalidad que, en diciembre de 2027, la tasa de temporalidad en las categorías profesionales de Atención Primaria se sitúe en el 8%, en coherencia con el objetivo general de reducción de la temporalidad en el empleo público. Una temporalidad superior al 15% o por debajo del 20% sería demasiado elevada para ese objetivo, y una temporalidad variable sin límite impediría medir el cumplimiento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a88") }, {"long_answer": "La línea 1 del Plan de Acción de Atención Primaria y Comunitaria 2025-2027 se dedica a fidelizar y atraer talento hacia la Atención Primaria, porque la falta de profesionales, la dificultad para cubrir plazas y la salida de personal hacia otros ámbitos son algunos de los principales problemas del primer nivel asistencial. Por ello recoge medidas de estabilidad laboral, condiciones atractivas y desarrollo profesional. La mejora de la capacidad diagnóstica, la financiación y la digitalización también aparecen en el Plan, pero corresponden a otras líneas o acciones y no constituyen el objetivo de la línea 1."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a8b") }, {"long_answer": "La línea 2 del Plan de Acción de Atención Primaria y Comunitaria busca ampliar los perfiles profesionales del equipo de Atención Primaria y mejorar su coordinación, incorporando o reforzando figuras como fisioterapia, psicología clínica, farmacia, trabajo social u otras, para dar una respuesta más resolutiva y multidisciplinar. Las demás opciones van en sentido contrario al Plan: no se plantea reducir el personal sanitario, ni limitar la dispensación de medicamentos a los médicos, ni eliminar procesos administrativos con el objetivo de abaratar costes, sino reorganizar y reforzar el equipo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a8e") }, {"long_answer": "Según los datos de diagnóstico que recoge el Plan de Acción de Atención Primaria y Comunitaria, el promedio de población asignada por profesional de Medicina Familiar y Comunitaria es de 1.351 personas. Esta cifra, procedente de los sistemas de información del SNS, se utiliza como referencia para valorar la carga asistencial y la necesidad de ajustar los cupos. La cifra de 1.370 es próxima pero no coincide con la reflejada en el documento, 901 personas es un valor muy inferior propio de otros perfiles o ámbitos, y 2.000 personas supera ampliamente el promedio nacional."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a99") }, {"long_answer": "La evaluación del Plan de Acción de Atención Primaria 2022-2023 mostró que más del 80% de las acciones previstas alcanzaron un cumplimiento parcial o total, lo que el nuevo Plan 2025-2027 toma como punto de partida para dar continuidad a las medidas y reforzar las que quedaron pendientes. Las cifras inferiores, como menos del 40%, entre el 50 y el 60% o el 75%, no corresponden al resultado de la evaluación recogido en el documento, que fue claramente más favorable."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a9a") }, {"long_answer": "Según el diagnóstico de recursos humanos del Plan de Acción de Atención Primaria y Comunitaria, el 60% de las vacantes se cubrió con contratos de al menos dos años ofrecidos a los profesionales al terminar la residencia. Este tipo de medida busca retener a los especialistas recién formados y favorecer la estabilidad de los equipos, uno de los objetivos de la línea de fidelización del talento. Los porcentajes del 76%, el 100% y el 45% no corresponden al dato que recoge el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a9b") }, {"long_answer": "El Plan de Acción de Atención Primaria y Comunitaria recoge que el 64,70% de las Comunidades Autónomas, es decir, 11 de las 17, han implantado un presupuesto finalista específico para la mejora de la Atención Primaria. Este tipo de partida reservada garantiza que los fondos se destinen realmente al primer nivel asistencial. El 58,80% equivaldría a 10 de 17 comunidades y no es el dato del documento; el 75% y el 30% tampoco corresponden a la cifra recogida en el diagnóstico de situación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a9d") }, {"long_answer": "El Plan establece que la Atención Primaria debe coordinarse y alinearse con instituciones sanitarias y no sanitarias, incluidas Salud Pública y la Atención Sociosanitaria, para actuar sobre los determinantes sociales de la salud, ya que estos dependen de ámbitos como la vivienda, la educación, el empleo o los servicios sociales. Limitar esa coordinación solo a la Atención Especializada, solo a las Administraciones Locales o exclusivamente a los Servicios Sociales sería insuficiente, porque el abordaje de los determinantes exige una acción intersectorial amplia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a9e") }, {"long_answer": "Según los datos de opinión ciudadana que recoge el Plan, procedentes del Barómetro Sanitario, el 46,50% de la población cree que la sanidad pública presta los mismos servicios con independencia de la comunidad autónoma de residencia. Es decir, menos de la mitad percibe homogeneidad entre territorios, lo que refuerza la necesidad de trabajar la equidad y la cohesión del SNS. Los porcentajes del 75,80%, el 82% y el 57% no corresponden al dato que recoge el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aa1") }, {"long_answer": "Uno de los retos de la línea 6 del Plan de Acción de Atención Primaria y Comunitaria es impulsar la atención familiar en el hogar y garantizar la continuidad asistencial, especialmente en personas con dependencia, cronicidad compleja o al final de la vida, coordinando la Atención Primaria con el resto de recursos sanitarios y sociales. Las demás opciones contradicen la filosofía del Plan: no se busca reducir profesionales en zonas urbanas, ni centralizar la atención en los hospitales, ni aumentar la burocracia, sino acercar la atención al domicilio y reducir cargas administrativas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aa4") }, {"long_answer": "Según los datos del Barómetro Sanitario recogidos en el Plan, el 69% de los pacientes que recibieron consulta telefónica en Atención Primaria se declara bastante o muy satisfecho con ella. Es un nivel de satisfacción aceptable, aunque inferior al de la atención presencial, por lo que el Plan plantea criterios comunes para la atención no presencial y su uso como complemento, no como sustituto. Los porcentajes del 82,20%, el 50,30% y el 33,90% no corresponden al dato recogido en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aa9") }, {"long_answer": "El Plan potencia las herramientas digitales en las zonas rurales más despobladas para fortalecer la cobertura asistencial y mejorar el acceso a la atención sanitaria, ya que la dispersión geográfica y la falta de profesionales dificultan la atención presencial continua. La teleconsulta y otras herramientas complementan la atención, pero no pretenden reemplazar por completo la presencialidad. Tampoco buscan restringir el acceso para ahorrar recursos ni reservar estas herramientas en exclusiva al personal sanitario, lo que iría en contra de la equidad que persigue el Plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ab1") }, {"long_answer": "El Plan promueve la investigación cooperativa en redes específicas de Atención Primaria mediante la priorización de convocatorias de redes dentro de la Acción Estratégica en Salud (AES), gestionada por el Instituto de Salud Carlos III. Con ello se pretende que los grupos de Atención Primaria accedan a financiación estable y colaboren entre sí. Las demás opciones van en sentido contrario: no se busca reducir la participación de los clínicos, ni limitar la cooperación a los grandes hospitales, ni eliminar las redes de Atención Primaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ab4") }, {"long_answer": "Para favorecer que los profesionales de Atención Primaria participen en la convocatoria de intensificación de la actividad investigadora, el Plan prevé liberar parte de su tiempo de dedicación asistencial, de modo que puedan dedicar horas de su jornada a investigar sin abandonar la práctica clínica. No se contempla una reducción de jornada sin límite ni la suspensión completa de la actividad asistencial, ya que se busca compatibilizar ambas tareas, y tampoco se limita a liberar tareas administrativas, que no es el objeto de la intensificación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ab6") }, {"long_answer": "El Plan fija como objetivo que el porcentaje de profesionales de Atención Primaria integrados en los Institutos de Investigación Sanitaria (IIS) acreditados aumente en un 15% o más durante el periodo 2025-2027, tomando como referencia la situación de enero de 2024. Con ello se pretende reforzar el peso de la Atención Primaria en las estructuras de investigación biomédica. Un incremento del 5% sin evaluación, una disminución o la ausencia de incremento no se corresponden con la meta del Plan, que apuesta por impulsar la investigación en este nivel."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977abc") }, {"long_answer": "El Plan atribuye al Ministerio de Sanidad la evaluación, antes de 2026, del grado de implantación de la modalidad de atención no presencial en Atención Primaria en las Comunidades Autónomas, en coherencia con su papel de coordinación y cohesión del SNS. No la realizan las Comunidades Autónomas sin coordinación central, ya que se busca una visión de conjunto, ni el Instituto de Salud Carlos III al margen del Ministerio, ni entidades privadas, que no tienen competencias de evaluación de las políticas del SNS."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977abd") }, {"long_answer": "El indicador previsto es el número de estancias formativas ofertadas y realizadas, desglosadas por sexo, señalando las realizadas por personas de instituciones distintas a la que oferta la estancia; así se puede seguir su evolución anual y la movilidad entre grupos. Las estancias internas sin colaboración externa no reflejan intercambio entre instituciones, que es precisamente lo que se quiere medir. Contabilizar las estancias canceladas o las de duración inferior a una semana no informa sobre la evolución de la colaboración interinstitucional."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ac0") }, {"long_answer": "Para aumentar la presencia de los grupos de investigación de Atención Primaria en proyectos europeos, el Plan prioriza la difusión de las convocatorias y el apoyo dirigido a estos grupos, por ejemplo mediante asesoramiento en la preparación de propuestas, ya que su participación internacional es todavía escasa. Reducir la participación para ahorrar costes, incluir solo proyectos con presencia hospitalaria o fomentar proyectos sin profesionales de Atención Primaria contradice el objetivo de fortalecer la investigación propia de este nivel asistencial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ac5") }, {"long_answer": "El Plan prevé publicar en diciembre de 2025 un documento con los indicadores comunes consensuados en el Grupo de Trabajo de Salud Comunitaria para evaluar las Estrategias de Salud Comunitaria de las Comunidades Autónomas. Disponer de indicadores comunes permite comparar la implantación entre territorios y facilita la evaluación participada. Un plan de capacitación profesional, un informe sobre brecha digital o un manual de implementación de servicios comunitarios pueden ser útiles, pero no son el documento ligado a la evaluación de las Estrategias en esa fecha."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ac7") }, {"long_answer": "Para medir la incorporación de los condicionantes sociales y del contexto familiar en la Historia de Salud Digital, el Plan utiliza el porcentaje de Comunidades Autónomas que han incorporado el conjunto mínimo de condicionantes consensuado. Este indicador refleja si los sistemas de información recogen de forma homogénea aspectos como la situación social o familiar, relevantes para una atención integral. El número de profesionales formados, el número de visitas no presenciales o la satisfacción de los pacientes miden otras cuestiones y no la incorporación de esos datos a la historia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ac8") }, {"long_answer": "Incluir herramientas de recomendación de activos para la salud en la Historia de Salud Digital permite al profesional ofrecer un consejo integral y adaptado a cada persona sin salir del contexto de la consulta, recomendando recursos comunitarios como grupos, asociaciones o actividades del barrio. Es una forma de facilitar la prescripción social desde la propia historia clínica. No tiene como objetivo principal reducir la carga administrativa, aumentar las visitas presenciales de seguimiento ni mejorar la interoperabilidad entre hospitales, que son cuestiones abordadas en otras acciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977acc") }, {"long_answer": "Las convocatorias competitivas y no competitivas específicas para Atención Primaria buscan, entre otros fines, facilitar el inicio en la investigación, especialmente de los profesionales jóvenes, que suelen tener más dificultades para competir con grupos consolidados en las convocatorias generales. Así se favorece la creación de una masa crítica investigadora en este nivel. Reducir la tensión asistencial, aumentar el uso de la Historia de Salud Digital o incrementar la atención presencial a grupos vulnerables son objetivos de otras líneas del Plan, no de estas convocatorias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ad2") }, {"long_answer": "El Plan toma como referencia para la modalidad de atención no presencial en Atención Primaria la norma UNE 179011:2023, una norma técnica española sobre la teleconsulta y la atención sanitaria no presencial que establece requisitos de calidad y seguridad para este tipo de atención. La ISO 9001:2015 regula sistemas de gestión de calidad en general y la ISO 14001:2018 se refiere a la gestión ambiental, por lo que no son específicas de la atención no presencial. La UNE 139802:2022 pertenece a la serie de normas de accesibilidad de las tecnologías de la información y no es la referencia citada para la atención no presencial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ad3") }, {"long_answer": "La educación sanitaria individualizada avanzada no es uno de los niveles de la formación online en orientación comunitaria dirigida a profesionales de Atención Primaria, ya que este itinerario se centra en el trabajo colectivo y comunitario, no en la intervención individual. Los niveles formativos que recoge el Plan son la acción comunitaria para la salud, la equidad en salud con el curso Aprendiendo con el pueblo gitano y la educación para la salud grupal sobre estilos de vida, todos ellos orientados a la intervención con grupos y comunidades."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ad7") }, {"long_answer": "La evaluación convocada para antes de 2026 tiene como objetivo medir el grado de implantación de la modalidad de atención no presencial en Atención Primaria en las Comunidades Autónomas, para conocer cómo se está aplicando y si se ajusta a los criterios comunes acordados. Auditar la calidad de la historia clínica digital, evaluar la capacitación en salud comunitaria o medir la penetración de la telemonitorización en pacientes crónicos son cuestiones diferentes, que no constituyen el objeto de esta evaluación concreta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ad8") }, {"long_answer": "Dentro del Plan de Transformación Digital de Atención Primaria, el grupo de trabajo encargado de la escuela de pacientes y de la promoción de la salud es el GT3. Este grupo impulsa herramientas digitales para que la ciudadanía acceda a información de salud fiable y participe activamente en su autocuidado. Los grupos GT2, GT4 y GT6 tienen asignados otros ámbitos del plan de transformación digital, por lo que no son los responsables de la escuela de pacientes ni de la promoción de la salud."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ad9") }, {"long_answer": "Para garantizar la equidad en el acceso, el Plan propone adecuar las modalidades de atención, presencial, telefónica o telemática, a las necesidades de la población y reducir la brecha digital, de manera que nadie quede excluido por su edad, nivel socioeconómico o competencias digitales. Imponer la asistencia presencial obligatoria en todos los casos restaría accesibilidad, limitar la teleconsulta a las personas mayores no tiene justificación y eliminar la atención online en zonas rurales perjudicaría precisamente a la población con más dificultades de acceso."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ada") }, {"long_answer": "La Estrategia de Salud Comunitaria plantea implicar a diferentes agentes, incluida la ciudadanía, en todo el proceso, desde la identificación de necesidades y activos hasta la planificación, la ejecución y la evaluación de las intervenciones. La participación comunitaria es un elemento central de la orientación comunitaria de la Atención Primaria. Por eso son incorrectas las opciones que plantean una gestión exclusivamente profesional, un trabajo solo entre administraciones y profesionales o una delegación total en asociaciones locales sin coordinación con el sistema sanitario."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977adc") }, {"long_answer": "El Plan establece como objetivo que, a partir de 2026, el 100% de las Comunidades Autónomas publiquen anualmente la evaluación de la implementación de sus Estrategias de Salud Comunitaria. La publicación por todas las comunidades favorece la transparencia, la rendición de cuentas y la comparación entre territorios, y se apoya en los indicadores comunes consensuados en el Grupo de Trabajo de Salud Comunitaria. Los porcentajes del 75%, el 50% y el 25% no se corresponden con la meta, que alcanza a la totalidad de las comunidades."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ae4") }, {"long_answer": "El Instrumento Estandarizado aprobado por el Consejo Interterritorial del SNS para los servicios sanitarios tiene como objetivo mejorar la detección temprana de la violencia de género, facilitando que los profesionales, especialmente de Atención Primaria, identifiquen precozmente los casos y actúen de forma homogénea en todo el territorio. La formación en atención materna, la reducción de la obesidad infantil y la gestión de recursos humanos en zonas rurales son objetivos de otras actuaciones y no guardan relación con este instrumento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aea") }, {"long_answer": "El Plan fija como meta que para 2027 al menos el 80% de las Comunidades Autónomas trabajen en la identificación de las personas en situación de soledad no deseada, un problema con repercusiones sobre la salud física y mental, sobre todo en personas mayores. La Atención Primaria, por su cercanía y longitudinalidad, ocupa un lugar privilegiado para detectar estas situaciones y vincular a las personas con recursos comunitarios. Los porcentajes del 60%, el 50% y el 40% son inferiores a la meta establecida."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aed") }, {"long_answer": "El Plan prevé que los indicadores seleccionados para monitorizar la Atención Primaria se publiquen antes de que finalice 2025, como paso previo a la elaboración del primer informe del SNS sobre su situación, cuyos resultados se publicarían posteriormente. Fijar primero los indicadores permite que todas las comunidades recojan la información de forma homogénea. Fin de 2026 corresponde a la publicación de los resultados, fin de 2027 es el horizonte final del Plan y fin de 2024 es anterior a su periodo de vigencia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977af4") }, {"long_answer": "Para integrar la participación comunitaria en la toma de decisiones de las políticas de Atención Primaria y Comunitaria, el Plan propone crear mecanismos de participación y canales de comunicación estables entre los órganos decisores y la comunidad, de forma que la ciudadanía pueda aportar sus necesidades y propuestas. Las consultas esporádicas sin canales formales no garantizan una participación real, la delegación total en asociaciones externas desvincula la participación de la toma de decisiones y eliminar las consultas comunitarias va en contra del enfoque del Plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977af6") }, {"long_answer": "La actualización del contenido y la metodología de los planes de gestión anuales de los centros de salud busca impulsar la autonomía de gestión de los equipos de Atención Primaria y establecer un marco común de evaluación que permita comparar resultados entre centros y territorios. Las opciones que plantean reducir la participación de los profesionales, centralizar la gestión en el Ministerio de Sanidad o eliminar la evaluación de los planes son contrarias a este objetivo, que apuesta por la descentralización y la gestión participativa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b00") }, {"long_answer": "En el modelo colaborativo entre Atención Primaria y Salud Mental, el profesional de salud mental realiza intervenciones breves individuales y grupales, participa en la formación de los equipos de Atención Primaria, ofrece consultoría sobre casos y actúa de enlace entre ambos niveles. Este modelo mejora la resolución de los problemas de salud mental comunes desde el primer nivel y evita derivaciones innecesarias. No se limita a la atención en crisis hospitalarias, ni solo a la formación sin atención directa, ni a tareas de gestión administrativa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b01") }, {"long_answer": "El Plan establece como resultado esperado para 2026 que el 100% de las Comunidades Autónomas tengan implantados programas colaborativos entre Atención Primaria y Salud Mental, de modo que todas cuenten con este modelo de atención compartida para los problemas de salud mental más frecuentes. Las opciones que hablan de un 50% de comunidades con programas en desarrollo, de solo un 30% o de ninguna comunidad no se corresponden con la meta, que pretende la extensión del modelo a todo el territorio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b02") }, {"long_answer": "Además de la implantación en todas las Comunidades Autónomas, el Plan fija como objetivo que para 2027 al menos el 60% de las áreas sanitarias cuenten con programas colaborativos entre Atención Primaria y Salud Mental, lo que supone extender el modelo a la mayor parte del territorio de cada comunidad. Un 90% supera la meta fijada, mientras que el 40% y el 20% son inferiores a ella, por lo que ninguna de estas cifras se corresponde con el objetivo establecido en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b04") }, {"long_answer": "El Plan fija que para 2027 al menos el 80% de las Comunidades Autónomas tengan implantado un sistema de comunicación bidireccional entre las farmacias comunitarias y los profesionales de los centros de salud. Esta comunicación facilita la coordinación en el seguimiento farmacoterapéutico, la detección de problemas relacionados con los medicamentos y la adherencia, especialmente en pacientes polimedicados. Los porcentajes del 70%, el 50% y el 90% no se corresponden con la meta recogida en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b09") }, {"long_answer": "La pandemia de COVID-19 puso de manifiesto la vulnerabilidad de la cadena de suministro farmacéutica, muy concentrada en pocas empresas situadas fuera de la Unión Europea, sobre todo en la fabricación de materias primas y principios activos y de medicamentos genéricos, lo que provocó problemas de abastecimiento. Por eso la Estrategia apuesta por la autonomía estratégica. No hubo un aumento de la producción local que garantizara la autosuficiencia, ni un exceso de diversificación de proveedores o de materias primas almacenadas; el problema fue precisamente el contrario."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b13") }, {"long_answer": "La medicina personalizada de precisión se basa en integrar datos genéticos, clínicos, ambientales, socioeconómicos y otros datos relevantes del paciente para adaptar la prevención, el diagnóstico y el tratamiento a sus características individuales. Por eso no se apoya en desarrollos genéricos estandarizados ni en el uso exclusivo de medicamentos tradicionales, que aplican el mismo abordaje a todos los pacientes. Aunque las terapias avanzadas celulares pueden formar parte de ella, la medicina de precisión no se reduce exclusivamente a este tipo de terapias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b16") }, {"long_answer": "La Estrategia contempla que, si se superase la tasa de referencia del gasto farmacéutico, el Estado, las Comunidades Autónomas y la industria evalúen la situación y adopten medidas de mejora que contribuyan a la sostenibilidad financiera del Sistema Nacional de Salud, en un marco de corresponsabilidad. Aumentar el precio de los medicamentos incrementaría el gasto, reducir la inversión en innovación perjudicaría el desarrollo del sector y limitar la producción de genéricos iría en contra de su papel en la sostenibilidad del sistema."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b17") }, {"long_answer": "La Estrategia propone un sistema de evaluación de la eficiencia de las tecnologías sanitarias y de fijación de precios de los medicamentos en el que se separen claramente las funciones de evaluación, negociación y gestión, para garantizar la transparencia, la independencia técnica de la evaluación y la ausencia de conflictos de interés. Integrar todas las funciones en una única unidad, hacer depender la evaluación de quienes negocian con la industria o eliminar la participación pública en la fijación de precios irían en contra de estos principios."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b1a") }, {"long_answer": "En la gobernanza de la Estrategia de la Industria Farmacéutica, la Comisión técnica interministerial se encarga de preparar las reuniones del órgano de nivel superior, coordinar las actuaciones de los distintos ministerios y establecer los recursos necesarios para avanzar en la ejecución de las medidas. No delega el seguimiento en la industria, ya que la gobernanza es pública, ni se limita a una reunión anual informativa, y tampoco gestiona la comercialización de medicamentos, que no forma parte de sus funciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b24") }, {"long_answer": "La Estrategia considera fundamental la evaluación clínica y económica de los medicamentos, porque aporta la base técnica para decidir el precio y la financiación pública y para controlar el crecimiento del gasto farmacéutico, priorizando aquellos fármacos que aportan valor terapéutico real. Esta evaluación no se sustituye por decisiones comerciales de la industria, no se limita a los medicamentos nuevos y no depende exclusivamente de organismos internacionales, aunque se coordine con la evaluación europea de tecnologías sanitarias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b2b") }, {"long_answer": "Según los datos de contexto de la Estrategia, se estima que el volumen global de medicamentos, medido en unidades consumidas, crecerá en torno a un 2,30% anual entre 2023 y 2028. Este crecimiento moderado en volumen contrasta con el mayor crecimiento del mercado en valor, de entre un 5 y un 8% anual, impulsado sobre todo por la entrada de medicamentos innovadores de alto precio. Las cifras del 10% y del 0,50% tampoco corresponden al dato recogido en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b31") }, {"long_answer": "El Plan INNVIERTE tiene como objetivo prioritario impulsar la inversión en el sector biomédico, especialmente en proyectos de desarrollo de tratamientos avanzados, movilizando capital público y privado para que la innovación llegue a fases de desarrollo clínico y a los pacientes. No busca concentrar la producción farmacéutica en un único centro nacional, ni reducir la inversión pública en investigación clínica, ni obligar a una reducción drástica del gasto farmacéutico, que serían objetivos ajenos a un instrumento de inversión."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b33") }, {"long_answer": "Dentro de la inversión en I+D de la industria farmacéutica en España en 2022, el ámbito más relevante fue la investigación clínica, es decir, los ensayos clínicos, que concentran la mayor parte del gasto en investigación del sector y en los que España ocupa una posición destacada en Europa. La investigación básica tiene un peso menor en la inversión de la industria. La fabricación y la comercialización internacional no son ámbitos de I+D en sentido estricto, sino actividades productivas y comerciales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b34") }, {"long_answer": "La Estrategia recoge que, en el periodo 2023-2028, se espera que el mercado farmacéutico mundial crezca en valor a un ritmo medio anual de entre el 5 y el 8%, impulsado sobre todo por los medicamentos innovadores, como los de oncología, inmunología o las terapias avanzadas. Este crecimiento es superior al del volumen de unidades consumidas. Un crecimiento inferior al 2%, superior al 10% o el estancamiento total no se corresponden con las previsiones recogidas en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b35") }, {"long_answer": "El Sistema Nacional de Salud es el principal cliente de la industria farmacéutica en España, ya que financia la mayor parte de los medicamentos dispensados en farmacias y utilizados en los hospitales, con un gasto que crece año tras año. Esta relación explica la necesidad de equilibrar innovación, acceso y sostenibilidad. El SNS no compite con la industria en la producción de genéricos, no es el único responsable de la innovación, que también depende de la industria y del sistema de ciencia, y no es solo un regulador sin relación de compra."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b3d") }, {"long_answer": "España es el principal foco europeo de ensayos clínicos con medicamentos y, a escala mundial, solo la superan Estados Unidos y China en número de ensayos, gracias a la calidad de sus centros, la agilidad de la autorización y la experiencia de sus investigadores. Por eso es falso que ocupe la última posición dentro de la Unión Europea, que no participe en ensayos internacionales o que se limite a ensayos con medicamentos genéricos; la mayoría de los ensayos que acoge son de medicamentos innovadores e internacionales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b3e") }, {"long_answer": "Para que la industria farmacéutica contribuya a la sostenibilidad del Sistema Nacional de Salud, la Estrategia plantea integrar la innovación, la producción, el acceso de los pacientes a los medicamentos y el control del gasto, de forma que los avances terapéuticos lleguen a la población sin comprometer la viabilidad del sistema. Concentrar el gasto solo en medicamentos innovadores de alto coste, reducir la producción nacional aumentando las importaciones o limitar la producción a unos pocos medicamentos esenciales irían en contra de esa visión integrada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b42") }, {"long_answer": "La Estrategia muestra el compromiso del Estado con el sector biomédico a través de inversiones sin precedentes mediante programas como INNVIERTE, orientado a la inversión en empresas innovadoras, y TERAFRONT, sociedad público-privada para el desarrollo de terapias avanzadas. Ambos instrumentos pretenden que la investigación se traduzca en productos que lleguen a los pacientes. La disminución de fondos para investigación clínica, la focalización solo en genéricos o la suspensión de programas público-privados son contrarios a lo que plantea la Estrategia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b43") }, {"long_answer": "En investigación y desarrollo, la Estrategia busca incrementar la financiación, reforzar las estructuras de soporte a la investigación clínica y preclínica y promover la medicina personalizada de precisión, para que España mantenga y mejore su posición en innovación biomédica. Reducir la investigación para centrarse en la producción masiva, concentrarla únicamente en el sector privado sin colaboración pública o limitar la formación en I+D contradicen el planteamiento de la Estrategia, que apuesta por la colaboración público-privada y por el refuerzo del sistema investigador."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b44") }, {"long_answer": "La Regla de Gasto y la comunicación europea sobre la política fiscal condicionan la Estrategia nacional en 2023-2024, porque obligan a contener el crecimiento del gasto público, incluido el farmacéutico. Por ello hacen necesario priorizar a la vez el acceso oportuno a los medicamentos y el control del gasto farmacéutico. Estas reglas no permiten eliminar los controles presupuestarios ni aumentar libremente el gasto, no eximen a las Comunidades Autónomas de su responsabilidad en el gasto y tampoco prohíben invertir en medicamentos innovadores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b50") }, {"long_answer": "Para garantizar la igualdad en el acceso al diagnóstico molecular, la Estrategia plantea incluir en la cartera común de servicios del SNS los biomarcadores necesarios para utilizar un medicamento en el momento en que ese medicamento se incorpora a la financiación, de forma que cualquier paciente pueda acceder a la prueba con independencia de dónde viva. Fomentar la competencia de laboratorios privados sin regulación, reducir la inversión pública en genética o suspender el intercambio de datos genómicos entre comunidades aumentaría las desigualdades."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b56") }, {"long_answer": "La Estrategia promueve la investigación en Atención Primaria impulsando la realización de ensayos clínicos en este nivel asistencial, creando unidades de investigación clínica en Atención Primaria y favoreciendo colaboraciones públicas y privadas, ya que gran parte de los pacientes con enfermedades crónicas se atienden allí. Limitar la investigación a hospitales de referencia, disminuir la inversión en ensayos en Atención Primaria o centralizarla en un único centro nacional irían en contra del objetivo de acercar la investigación clínica a la población."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b58") }, {"long_answer": "La participación de España en asociaciones europeas de investigación como ERDERA, centrada en enfermedades raras, y OH-AMR, dedicada a la resistencia a los antimicrobianos desde el enfoque Una sola salud, busca potenciar la presencia española en la investigación clínica y preclínica en áreas alineadas con las prioridades de la Estrategia. Consolidar una investigación exclusivamente nacional, evitar la colaboración público-privada o reducir la inversión en investigación biomédica son contrarios al sentido de estas alianzas internacionales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b5a") }, {"long_answer": "Entre las acciones previstas para las estructuras de soporte a la investigación clínica y preclínica, la Estrategia incluye reforzar la cohesión territorial y dotar de medios materiales y humanos a los centros de investigación, para que todas las Comunidades Autónomas puedan participar en ensayos y proyectos en condiciones adecuadas. Disminuir la participación autonómica, cerrar las unidades con baja producción o trasladar la mayoría de los ensayos al ámbito privado aumentarían las desigualdades territoriales que la Estrategia pretende corregir."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b5b") }, {"long_answer": "La Estrategia prevé mesas de diálogo con los agentes implicados en la realización de ensayos clínicos, como promotores, centros, investigadores y comités de ética, para resolver las dificultades técnicas que surgen en la práctica y adaptar los procesos a la digitalización y al Reglamento Europeo de ensayos clínicos. No pretenden promover la desregulación ni la entrada urgente de medicamentos sin garantías, ni limitar la participación del Estado en la investigación clínica, ni coordinar exclusivamente la compra pública."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b60") }, {"long_answer": "En el desarrollo de las Unidades de Investigación Clínica del SNS, la Estrategia prioriza garantizar una dedicación mínima a la investigación clínica independiente, es decir, no promovida por la industria, y a los medicamentos de interés estratégico para el sistema sanitario. Así se protege la investigación que responde a necesidades del SNS y no solo a intereses comerciales. Externalizar ensayos a otros países, reducir el número de ensayos o dedicarse exclusivamente a medicamentos genéricos no se corresponde con este planteamiento.", "option_1": "Garantizar una dedicación mínima a la investigación clínica independiente y a medicamentos de interés estratégico"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b6b") }, {"long_answer": "El programa IMPaCT, Infraestructura de Medicina de Precisión asociada a la Ciencia y la Tecnología, impulsado por el Instituto de Salud Carlos III, busca transformar la toma de decisiones clínicas mediante el uso de grandes volúmenes de datos, genómicos, clínicos y de otro tipo, adaptados a las características individuales de cada paciente. No se limita al desarrollo de terapias génicas para enfermedades raras, no pretende reducir la presencia territorial de la medicina de precisión, sino extenderla, y no es un instrumento de gestión del presupuesto público de I+D."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b6e") }, {"long_answer": "TERAFRONT es una sociedad mercantil con participación pública y privada creada para desarrollar terapias avanzadas desde las fases clínicas precoces hasta su comercialización, de modo que los avances de la investigación española en este campo lleguen a los pacientes y generen valor en el propio país. No tiene como objetivo fabricar medicamentos genéricos de bajo coste, ni regular la producción de principios activos en laboratorios públicos, ni gestionar la distribución nacional de medicamentos hospitalarios, que son funciones ajenas a su finalidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b6f") }, {"long_answer": "La compra pública de innovación en salud está dirigida a desarrollar soluciones para necesidades clínicas no cubiertas que todavía no están disponibles en el mercado, de forma que la administración actúa como cliente que impulsa el desarrollo de productos o servicios innovadores. No pretende externalizar la producción farmacéutica a empresas extranjeras, ni limitar la innovación a productos ya establecidos, que es justo lo contrario de su finalidad. Promover la competencia entre proveedores tradicionales corresponde a la compra pública ordinaria, no a la de innovación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b72") }, {"long_answer": "En el ámbito de la formación en I+D+i, la Estrategia atribuye a la Agencia Española de Medicamentos y Productos Sanitarios el papel de proporcionar asesoría científico-regulatoria a los investigadores y empresas, formar a los agentes implicados en el desarrollo de medicamentos e incentivar el reposicionamiento terapéutico de fármacos ya existentes. Su función no se reduce a autorizar la comercialización de medicamentos, ni a capacitar solo a enfermeras en la práctica clínica habitual, ni a regular la formación de los técnicos de laboratorio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b74") }, {"long_answer": "La Reserva Estratégica basada en Capacidades Nacionales de Producción Industrial (RECAPI) tiene como propósito garantizar el suministro de productos esenciales y permitir la rápida movilización de la capacidad de producción industrial en situaciones de alta demanda, como emergencias sanitarias similares a la pandemia de COVID-19. No pretende centralizar en España toda la producción farmacéutica europea, ni dedicarse exclusivamente a exportar principios activos, ni limitar la producción nacional, lo que debilitaría la autonomía estratégica que busca reforzar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a8f") }, {"long_answer": "Según los datos de actividad recogidos en el Plan, la consulta en el centro sanitario es la modalidad con mayor número de consultas anuales en Medicina Familiar y Comunitaria, ya que la atención presencial sigue siendo la forma principal de contacto con la Atención Primaria. La teleconsulta ha aumentado desde la pandemia, pero continúa por detrás de la consulta presencial. La consulta domiciliaria tiene un volumen mucho menor y se reserva sobre todo a pacientes inmovilizados, y la consulta grupal es minoritaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a91") }, {"long_answer": "Entre las opciones planteadas, la enfermedad cerebrovascular es la principal causa de muerte entre las mujeres en España según los datos que recoge el informe, mientras que en los hombres la primera causa es la enfermedad isquémica del corazón. Esta diferencia por sexo es un dato clásico de la estadística de defunciones según causa de muerte. El cáncer de pulmón es una causa creciente en mujeres, pero no la primera, y los accidentes de tráfico tienen un peso mucho menor en la mortalidad global femenina."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a95") }, {"long_answer": "El Marco Estratégico para la Atención Primaria y Comunitaria se organiza en estrategias identificadas con letras, y la Estrategia F es la dedicada a impulsar la formación y la investigación en Atención Primaria. La Estrategia A se refiere al compromiso y liderazgo del Consejo Interterritorial con la Atención Primaria, la Estrategia C a mejorar la calidad de la atención y la coordinación con los demás ámbitos asistenciales y la Estrategia D a reforzar la orientación comunitaria, la promoción de la salud y la prevención."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a98") }, {"long_answer": "Según los datos del Plan, la tasa de hospitalizaciones potencialmente evitables por patologías agudas sensibles a los cuidados de Atención Primaria es de 31,0 por 10.000 habitantes. Este indicador incluye ingresos por procesos como infecciones urinarias, deshidratación o neumonías, que podrían evitarse con una atención primaria accesible y resolutiva, y se utiliza como medida indirecta de su efectividad. Las cifras de 50,3 y 76,2 por 10.000 y la de 10,8 por 1.000 habitantes no corresponden al dato de patologías agudas recogido en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aa0") }, {"long_answer": "En el Marco Estratégico de Atención Primaria y Comunitaria, la Estrategia C es la dirigida a mejorar la calidad de la atención y la coordinación con el resto de ámbitos asistenciales, servicios e instituciones, incluida la continuidad con la atención hospitalaria y la coordinación sociosanitaria. La Estrategia A se centra en el compromiso y liderazgo del Consejo Interterritorial, la Estrategia B en la política presupuestaria y de recursos humanos y la Estrategia E en el uso de las tecnologías de la información y la comunicación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aa5") }, {"long_answer": "Para hacer frente a la fuga de talento, el Plan contempla incentivar el retorno a la Atención Primaria de los profesionales que trabajan en otros ámbitos asistenciales, como urgencias u hospitales, junto con otras medidas de fidelización como la estabilidad laboral y el desarrollo profesional. Reducir el salario, limitar las oportunidades de crecimiento profesional o desincentivar la estabilidad laboral provocarían el efecto contrario, aumentando el abandono de la Atención Primaria y agravando el déficit de profesionales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aa8") }, {"long_answer": "Antes de 2027, el Plan prevé incorporar al modelo de gestión integral de la demanda criterios comunes para la modalidad de atención no presencial, de forma que la consulta telefónica o telemática se utilice de manera homogénea, segura y adecuada a cada situación en todas las Comunidades Autónomas. No se pretende reducir la atención presencial, priorizar únicamente a los pacientes crónicos ni eliminar la atención telefónica, sino ordenar las distintas modalidades de atención para mejorar la accesibilidad y la calidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aaa") }, {"long_answer": "Para mejorar el acceso al sistema sanitario de las personas sin hogar, el Plan señala como documento fundamental las recomendaciones para la mejora del acceso y el cuidado de la salud de estas personas, que abordan barreras como la falta de empadronamiento, de tarjeta sanitaria o de domicilio, y proponen circuitos adaptados. Un protocolo de exclusión sanitaria, un manual para evitar la atención no presencial o una guía para limitar recursos en zonas urbanas serían contrarios al objetivo de equidad del Plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aab") }, {"long_answer": "La puesta en marcha de las recomendaciones para mejorar la atención a las personas sin hogar corresponde a las Comunidades Autónomas, que tienen las competencias en la gestión de la asistencia sanitaria, en coordinación con el Ministerio de Sanidad, que impulsa y coordina las recomendaciones a nivel estatal. No depende solo del Ministerio, que no gestiona directamente los servicios, ni de los centros de Atención Primaria sin apoyo externo, ya que se requiere coordinación con servicios sociales, ni de entidades privadas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aac") }, {"long_answer": "En la actualización anual del mapa de situación de la I+D en Atención Primaria, la información referida a personas, como investigadores o responsables de grupos, se presenta desglosada por sexo, siguiendo el enfoque de género que aplica el Plan a todos sus indicadores para detectar posibles desigualdades entre mujeres y hombres en la carrera investigadora. Presentarla agrupada sin desgloses impediría ese análisis, incluir solo datos de hombres sería discriminatorio y excluir a los profesionales investigadores dejaría el mapa sin su contenido principal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aae") }, {"long_answer": "Para medir el éxito del sistema de identificación de colaboradores en investigación en 2026 y 2027, el Plan utiliza el número de consultas realizadas anualmente a través de esta utilidad, ya que refleja en qué medida los profesionales la usan para encontrar personas o grupos con intereses afines. El número de proyectos internacionales aprobados, el total de profesionales de Atención Primaria o las publicaciones de cada investigador miden otros aspectos y no dependen directamente del uso de esta herramienta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aaf") }, {"long_answer": "El seguimiento del número de estancias formativas ofertadas y realizadas se presenta desglosado por sexo y señalando cuáles han sido realizadas por profesionales de instituciones distintas a la que oferta la estancia, porque el objetivo es fomentar la colaboración y el intercambio entre grupos de investigación con perspectiva de género. Por eso son incorrectas las opciones que excluyen las estancias de personas externas, que las limitan a la misma institución o que ignoran las diferencias por sexo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ab2") }, {"long_answer": "El aumento de la investigación cooperativa en la Acción Estratégica en Salud se refleja en el incremento del número de grupos liderados por profesionales con actividad clínica en Atención Primaria que obtienen financiación dentro de las redes cooperativas. Este indicador muestra si la Atención Primaria gana peso real en las estructuras de investigación en red. La reducción de proyectos cooperativos o de grupos emergentes indicaría un retroceso, y el número total de concursos públicos generales no mide la investigación cooperativa en Atención Primaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977abf") }, {"long_answer": "En el ámbito de la investigación cooperativa, el número de grupos liderados por personas con actividad clínica en Atención Primaria que reciben financiación en redes se presenta además desglosado por sexo, para analizar si existen diferencias entre mujeres y hombres en el liderazgo de la investigación. Las publicaciones sin distinción de sexo no cumplen con el enfoque de género del Plan, y los datos económicos por comunidad o las remuneraciones de los investigadores no forman parte de este indicador."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ac3") }, {"long_answer": "En el seguimiento de los indicadores de investigación en Atención Primaria, toda la información referida a personas se presenta desglosada por sexo, de acuerdo con el principio de igualdad de género que el Plan aplica de forma transversal. Este desglose permite detectar posibles brechas en la participación, el liderazgo o la financiación de la investigación. Por eso son incorrectas las opciones que afirman que no se detalla ninguna variable sociodemográfica, que solo se recoge información profesional o que se ignoran los datos de sexo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ac6") }, {"long_answer": "La formación avanzada en telemonitorización no forma parte de los tres niveles de formación en orientación comunitaria dirigida a los profesionales de Atención Primaria, ya que pertenece al ámbito de la atención digital y no al trabajo comunitario. Los niveles de esta formación son la acción comunitaria para la salud, la equidad en salud con el curso Aprendiendo con el pueblo gitano y la educación para la salud grupal sobre estilos de vida, todos ellos centrados en la intervención con grupos y comunidades."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ac9") }, {"long_answer": "El Plan fija como meta que en diciembre de 2027 el 100% de las Comunidades Autónomas enlacen desde la Historia de Salud Digital a herramientas de recomendación de activos para la salud, coincidiendo con el final de su periodo de vigencia. Estas herramientas permiten al profesional recomendar recursos comunitarios durante la consulta. Las fechas de diciembre de 2025 y diciembre de 2026 corresponden a hitos intermedios de otras acciones del Plan, y diciembre de 2028 queda fuera del periodo 2025-2027."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977acb") }, {"long_answer": "El módulo específico que se desarrollará en el mapa de I+D en Atención Primaria durante 2026-2027 servirá para facilitar la búsqueda e identificación de personas o grupos de investigación con intereses afines, favoreciendo la colaboración y la creación de redes entre profesionales de distintos centros y comunidades. No se trata de un sistema para registrar citas médicas digitales, para monitorizar el uso de las teleconsultas en cada comunidad ni para evaluar la formación en competencias comunitarias, que son cuestiones ajenas a la investigación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977acf") }, {"long_answer": "La meta del Plan para diciembre de 2027 es que en cada Instituto de Investigación Sanitaria haya al menos un 5% de participación de profesionales de Atención Primaria o un mínimo de 40 personas investigadoras de este ámbito, para asegurar su presencia real en las estructuras de investigación biomédica. Una participación del 50% en proyectos europeos, una reducción del 15% de las cargas asistenciales o duplicar el número de grupos de investigación no son las metas fijadas para esta acción."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977adb") }, {"long_answer": "La actualización de la Cartera Básica Común de Atención Primaria para incluir los servicios de atención comunitaria tiene como finalidad que las Comunidades Autónomas adecúen sus servicios para mejorar la atención comunitaria, de forma que actividades como la educación para la salud grupal o la intervención comunitaria tengan un reconocimiento homogéneo en todo el SNS. No se busca reducir la oferta de servicios para ahorrar costes, establecer nuevos criterios de exclusión de pacientes ni centralizar la atención en los hospitales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977add") }, {"long_answer": "Las encuestas dirigidas exclusivamente a gestores hospitalarios no son un mecanismo de evaluación participada de las Estrategias de Salud Comunitaria, porque la evaluación participada implica a la ciudadanía, a los profesionales de Atención Primaria y a otros agentes comunitarios, no solo a gestores de otro nivel asistencial. Sí forman parte de este proceso los indicadores comunes consensuados en el Grupo de Trabajo de Salud Comunitaria, las evaluaciones participadas con los agentes implicados y la difusión de los resultados a la población y a los profesionales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977adf") }, {"long_answer": "En relación con la teleconsulta, el Plan busca reducir las barreras derivadas de la brecha digital en los colectivos vulnerables y las personas mayores, que pueden tener menos acceso a dispositivos o menos competencias digitales, para que la atención no presencial no genere desigualdades. Excluir a estos colectivos de la modalidad no presencial, ofrecerles teleconsulta solo en horario reducido o imponerla como obligatoria en todas las visitas no garantiza la equidad, ya que la modalidad debe adaptarse a las necesidades de cada persona."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ae2") }, {"long_answer": "El mapa actualizado de situación de la I+D en Atención Primaria tiene como propósito visibilizar la investigación que se realiza en este nivel asistencial, identificar sinergias entre grupos y centros y optimizar los recursos disponibles, evitando duplicidades y favoreciendo la colaboración. No pretende centralizar todos los proyectos en Madrid, limitar la investigación a las áreas urbanas ni eliminarla en zonas con poca población, lo que iría en contra de la cohesión territorial que persigue el Plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ae3") }, {"long_answer": "Dentro de sus Estrategias de Salud Comunitaria, las Comunidades Autónomas promoverán la formación práctica en competencias y habilidades en salud comunitaria dirigida a los profesionales, para que puedan aplicar en su trabajo diario herramientas como el mapeo de activos, la intervención grupal o la participación comunitaria. La formación exclusiva en atención hospitalaria, los cursos de técnicas quirúrgicas avanzadas o los seminarios de gestión financiera solo para médicos no guardan relación con la orientación comunitaria de la Atención Primaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aee") }, {"long_answer": "En la acción del Plan dedicada a la monitorización de la Atención Primaria, el indicador 2 corresponde a la publicación del resultado de los indicadores antes de que finalice 2026, una vez que previamente se han seleccionado y publicado los indicadores que se van a utilizar. Este orden permite elaborar el primer informe del SNS con datos homogéneos de todas las comunidades. Los indicadores 1, 3 y 4 se refieren a otros hitos de la acción y no a la publicación de estos resultados."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977af0") }, {"long_answer": "Antes de 2026, la Oficina Ejecutiva del Marco Estratégico de Atención Primaria y Comunitaria debe desarrollar un procedimiento para identificar, seleccionar y evaluar prácticas innovadoras y buenas prácticas en este ámbito, con el fin de difundirlas y facilitar que se extiendan a otros centros y comunidades. Capacitar a los profesionales en cuidados paliativos, reducir el gasto farmacéutico o elaborar informes financieros para las Comunidades Autónomas no son el objetivo de este procedimiento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977af2") }, {"long_answer": "En el análisis de necesidades de las zonas rurales más despobladas, el Plan prevé publicar antes de 2026 un documento de consenso con criterios específicos comunes, que sirva de referencia a las Comunidades Autónomas para reorganizar recursos e inversiones según las características de estas zonas, como la dispersión y el envejecimiento. Un plan de inversión en infraestructuras, un informe de evaluación económica o unas recomendaciones para la atención urgente pueden derivarse de ese análisis, pero no son el documento que establece el Plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977af3") }, {"long_answer": "El Plan establece como meta que el 100% de las Comunidades Autónomas más afectadas por la despoblación hayan realizado la evaluación de necesidades específicas para reorganizar sus recursos e inversiones en Atención Primaria, aplicando los criterios comunes consensuados. La meta abarca a todas estas comunidades porque son las que más dificultades tienen para garantizar el acceso en el medio rural. Las opciones que hablan del 50%, del 75% o de que ninguna ha realizado la evaluación no se corresponden con el objetivo fijado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977af7") }, {"long_answer": "El Plan fija como objetivo que antes de 2027 al menos el 10% de los profesionales de Atención Primaria reciban formación en gestión, para reforzar las competencias necesarias en un modelo que apuesta por una mayor autonomía de gestión de los centros de salud y por la participación de los profesionales en la toma de decisiones. Los porcentajes del 50%, el 5% y el 30% no se corresponden con la meta recogida en el documento para esta acción formativa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977af8") }, {"long_answer": "En el marco de la coordinación sociosanitaria, la definición de perfiles incluye a las personas que necesitan una atención sanitaria y social integrada, teniendo en cuenta múltiples factores como la dependencia, la cronicidad, la situación social, el apoyo familiar o la vulnerabilidad. No se limita a los pacientes hospitalizados por enfermedades crónicas ni a las personas mayores de 80 años, ya que la necesidad sociosanitaria puede darse a cualquier edad, y no incluye a personas sin necesidades sociales, que no requieren este tipo de atención."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977afa") }, {"long_answer": "El Plan fija como meta que en 2027 el 100% de las Comunidades Autónomas tengan implantada la interoperabilidad de la historia clínica digital entre la Atención Primaria y la atención hospitalaria, de modo que la información clínica esté disponible para los profesionales de ambos niveles. Esto favorece la continuidad asistencial, evita duplicidades de pruebas y mejora la seguridad del paciente. Los porcentajes del 90%, el 75% y el 50% no se corresponden con la meta, que abarca a todas las comunidades."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977afc") }, {"long_answer": "Para asegurar una atención integral en la atención familiar en el hogar, el Plan considera fundamental la coordinación con la atención hospitalaria, por ejemplo con unidades de hospitalización a domicilio o de cuidados paliativos, y con la Estrategia estatal para un nuevo modelo de cuidados en la comunidad, que integra los recursos sociales. Limitarse a actividades de Atención Primaria sin apoyo externo, colaborar solo con hospitales privados o eliminar la colaboración interinstitucional impediría dar respuesta a las necesidades complejas de las personas atendidas en su domicilio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977afe") }, {"long_answer": "El Plan establece como objetivo que antes de 2026 el 100% de las Comunidades Autónomas tengan implantado un sistema que permita identificar a los pacientes en situación de vulnerabilidad, de forma que los equipos de Atención Primaria puedan adaptar la atención y priorizar a quienes tienen más riesgo por motivos sociales, económicos o de salud. Esta identificación es clave para avanzar en equidad. Los porcentajes del 80%, el 60% y el 50% no se corresponden con la meta, que alcanza a todas las comunidades."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b05") }, {"long_answer": "En la optimización de la terapia farmacológica de los pacientes polimedicados, los farmacéuticos de Atención Primaria revisan los regímenes farmacoterapéuticos para detectar interacciones, duplicidades o medicamentos inadecuados, resuelven dudas de los profesionales sanitarios y se coordinan con las farmacias comunitarias para el seguimiento del paciente. Su papel no se reduce a dispensar medicamentos con receta, no administran tratamientos sin supervisión médica y no realizan solo funciones administrativas sin contacto con la actividad clínica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b07") }, {"long_answer": "El Plan fija como resultado esperado para 2027 un incremento del 30% en el número de Comunidades Autónomas con modelos de coordinación farmacoterapéutica centrados en la Atención Primaria, que integran la actuación de médicos, enfermeras, farmacéuticos de Atención Primaria y farmacias comunitarias en el seguimiento de los tratamientos. Disminuir la coordinación, mantener las cifras actuales sin cambios o reducir la participación de la farmacia comunitaria iría en contra de este objetivo de mejora del uso de los medicamentos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b0b") }, {"long_answer": "Las reformas de la regulación de medicamentos incluidas en el Plan de Recuperación, Transformación y Resiliencia se centran en incrementar la competencia, por ejemplo favoreciendo genéricos y biosimilares, y en facilitar el acceso a nuevos tratamientos, junto con la sostenibilidad del sistema y la racionalización del consumo de medicamentos. No buscan reducir la inversión pública en I+D, eliminar la financiación privada del sector ni fomentar exclusivamente la industria de genéricos, ya que la Estrategia pretende equilibrar innovación, acceso y sostenibilidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b0c") }, {"long_answer": "La Estrategia de la Industria Farmacéutica se articula en torno a ejes básicos que son la investigación y la innovación, la autonomía industrial o estratégica, el acceso de los pacientes a los medicamentos y la sostenibilidad del Sistema Nacional de Salud. Estos ejes reflejan el equilibrio entre el desarrollo del sector y el interés sanitario. Las demás opciones mezclan objetivos parciales o ajenos a la Estrategia, como la reducción de costes como eje, la eliminación de los genéricos o la homologación internacional, que no constituyen sus ejes vertebradores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b0d") }, {"long_answer": "El Ministerio de Cultura y Deporte no forma parte del Comité Interministerial que gobierna la Estrategia de la Industria Farmacéutica, ya que sus competencias no guardan relación con el sector del medicamento. El Comité, presidido por el Ministerio de Sanidad, cuenta con vocalías de los ministerios con competencias relacionadas con el sector, como Hacienda, por su papel en el gasto y la fijación de precios, Ciencia, Innovación y Universidades, por la investigación, e Industria y Turismo, por la política industrial y la capacidad productiva."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b0e") }, {"long_answer": "Según la Estrategia, la Secretaría de Estado de Sanidad coordina la gobernanza interministerial y se encarga del seguimiento y la evaluación de la Estrategia y de sus actuaciones, actuando como impulsora técnica del Comité Interministerial. No toma por sí sola las decisiones finales sobre el precio de los medicamentos, que siguen su propio procedimiento, ni gestiona exclusivamente la financiación externa y privada, y mucho menos ejecuta actividades comerciales o de marketing de la industria, que son ajenas a una administración pública."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b18") }, {"long_answer": "Tras la creación del nuevo sistema de evaluación, la resolución final sobre la financiación y el precio de los medicamentos seguirá correspondiendo al Ministerio de Sanidad, previo acuerdo de la Comisión Interministerial de Precios de los Medicamentos (CIPM), en la que participan otros ministerios y representantes de las Comunidades Autónomas. El nuevo sistema refuerza la evaluación técnica, pero no traslada la decisión al Ministerio de Hacienda sin intervención sanitaria, ni a organizaciones privadas, ni a las propias compañías farmacéuticas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b19") }, {"long_answer": "Dentro del sistema de evaluación y financiación, la Comisión Delegada del Gobierno para Asuntos Económicos (CDGAE) se encarga de aprobar las directrices de evaluación y las reglas aplicables a la prestación farmacéutica, a propuesta conjunta de los ministerios de Sanidad y de Hacienda, dada la repercusión económica de estas decisiones. No evalúa los aspectos científicos de los medicamentos, que corresponden a organismos técnicos, no realiza compras centralizadas y tampoco expide licencias de producción, que son competencia de la autoridad sanitaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b1f") }, {"long_answer": "La Estrategia plantea analizar el gasto farmacéutico al menos una vez al año, para conocer su evolución y las causas de su crecimiento y poder adoptar medidas a tiempo si se aleja de la tasa de referencia. Un análisis solo una vez por legislatura o cada cinco años sería demasiado espaciado para detectar desviaciones, y realizarlo solo cuando el gasto supere el presupuesto inicial impediría anticiparse a los problemas, que es precisamente lo que pretende el seguimiento periódico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b21") }, {"long_answer": "Para evitar que el sistema farmacéutico se oriente únicamente por la oferta tecnológica de la industria, la Estrategia propone que las necesidades de salud de la población se expresen de forma pública, continua y estructurada, de manera que guíen las prioridades de investigación, desarrollo y financiación. Invertir exclusivamente en empresas privadas, producir solo en el ámbito local sin influencia externa o centrarse únicamente en reducir costes sin considerar las necesidades no responde a este objetivo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b22") }, {"long_answer": "La Estrategia considera prioritaria la inversión en cronicidad por el impacto global creciente de las enfermedades crónicas en la salud pública, ligado al envejecimiento de la población y a la multimorbilidad, y por los elevados costes asociados a su manejo a lo largo de muchos años. Estas enfermedades no son de baja prevalencia, sino muy frecuentes, y la prioridad no se justifica por la facilidad para estudiar enfermedades infecciosas ni por un supuesto ahorro derivado del tratamiento de las enfermedades agudas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b23") }, {"long_answer": "Dentro de la Estrategia de la Industria Farmacéutica, la autonomía estratégica busca garantizar una cadena de suministro de medicamentos resiliente, sólida y ecosostenible, reduciendo la dependencia exterior en materias primas y principios activos que puso de manifiesto la pandemia de COVID-19. No pretende reducir la diversidad de actores de la industria, fomentar exclusividades comerciales sin competencia ni centralizar toda la producción en el sector público, sino reforzar las capacidades productivas en España y en Europa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b2d") }, {"long_answer": "Según los datos de la Estrategia, el 98,20% del gasto público en medicamentos y productos sanitarios en 2023 correspondió a las Comunidades Autónomas, ya que son ellas las que gestionan la asistencia sanitaria, incluida la prestación farmacéutica en farmacias y hospitales, tras el traspaso de competencias. El resto corresponde a otras administraciones como las mutualidades o el Estado. Los porcentajes del 75%, el 60% y el 85% infravaloran el peso que tienen las comunidades en este gasto según el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b30") }, {"long_answer": "La Estrategia incluye una línea de acción dirigida a completar la incorporación de biomarcadores y pruebas genéticas a la cartera de servicios, para que la medicina personalizada de precisión llegue a todos los pacientes en condiciones de equidad y los tratamientos dirigidos puedan utilizarse con el diagnóstico molecular adecuado. Impulsar la producción local de genéricos, establecer un sistema nacional de distribución o crear centros exclusivos para terapias avanzadas son actuaciones distintas que no se refieren a la incorporación de biomarcadores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b39") }, {"long_answer": "El Plan para fomentar el uso de medicamentos genéricos y biosimilares busca mejorar el acceso de la población a los tratamientos y contribuir a la sostenibilidad del sistema sanitario, ya que estos medicamentos tienen la misma eficacia y seguridad que los de referencia a un precio menor, lo que libera recursos para financiar la innovación. Disminuir el uso de genéricos, excluir los biosimilares o concentrar la producción en medicamentos originales sería contrario a este plan y aumentaría el gasto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b3b") }, {"long_answer": "El Programa PROFARMA, impulsado por la Administración General del Estado, evalúa y clasifica a las compañías farmacéuticas según su actividad industrial, su inversión en I+D y su contribución a la economía, y su reconocimiento tiene efectos en aspectos como la fiscalidad. Por ello la Estrategia lo vincula a optimizar la fiscalidad y el reconocimiento del sector. No regula la producción de vacunas de ARN mensajero, no coordina exclusivamente las cadenas de suministro de genéricos y no pretende reducir la inversión en investigación básica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b3c") }, {"long_answer": "En materia de financiación y desarrollo, la Estrategia busca estimular el uso y el desarrollo de herramientas financieras especializadas en biomedicina, como fondos de capital riesgo, préstamos o instrumentos público-privados, que permitan a las empresas innovadoras financiar las largas y costosas fases de desarrollo de medicamentos. Excluir al sector privado de la I+D+i, reducir el número de proyectos para ahorrar costes o centralizar todos los recursos en investigación clínica son medidas contrarias a lo que plantea la Estrategia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b3f") }, {"long_answer": "Según los datos recogidos en la Estrategia, la industria farmacéutica española invirtió en 2022 alrededor de 1.400 millones de euros en investigación y desarrollo, lo que la sitúa como uno de los sectores industriales con mayor inversión en I+D del país. Una parte importante de esta cantidad se destina a investigación clínica, es decir, a ensayos clínicos. Las cifras de 500 y 800 millones de euros infravaloran esta inversión, mientras que 5.000 millones de euros la sobreestima claramente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b46") }, {"long_answer": "La Estrategia considera esencial una gobernanza integral que una la acción pública y la privada, implicando a los distintos ministerios, a las Comunidades Autónomas y a la industria, para que el sector farmacéutico contribuya a la competitividad y al desarrollo económico del país sin perder de vista el interés sanitario. Reducir la acción pública a una regulación básica, limitar la innovación para evitar riesgos o externalizar completamente la producción debilitaría tanto la competitividad como la autonomía estratégica que persigue la Estrategia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b52") }, {"long_answer": "La Estrategia prevé crear fórmulas regulatorias que permitan reconocer nuevas indicaciones de medicamentos que ya están fuera del periodo de protección sin que ello penalice su precio de financiación, para incentivar que se investiguen y se incorporen a la ficha técnica usos que ya se aplican o que tienen evidencia. Penalizar automáticamente el precio desincentivaría esa investigación, y no se plantea impedir la inclusión de indicaciones en la ficha técnica ni limitar la financiación a solicitudes de laboratorios sin ánimo de lucro."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b54") }, {"long_answer": "La reforma de la financiación pública en I+D recogida en la Estrategia, alineada con la Ley de la Ciencia, tiene como objetivo que la financiación pública en investigación y desarrollo alcance el 1,25% del PIB en 2030, con un crecimiento progresivo y estable de los recursos. Mantenerla en un 0,5% del PIB supondría un nivel muy inferior al objetivo, la meta no se refiere a que la financiación privada alcance el 5% del PIB y tampoco se plantea reducir la financiación pública para favorecer la iniciativa privada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b64") }, {"long_answer": "La Estrategia prevé publicar guías técnicas metodológicas sobre evaluación económica y beneficio clínico para que sirvan de referencia común en los análisis económicos, en la valoración del valor terapéutico añadido y en la negociación de precios, con criterios claros, transparentes y a la vez flexibles. Estas guías no eliminan la necesidad de evaluar antes de financiar, sino que la refuerzan, no trasladan la aprobación de medicamentos a organismos europeos y no dejan la evaluación en manos exclusivas de expertos privados."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b67") }, {"long_answer": "La Estrategia considera la colaboración público-privada fundamental para el avance de la I+D+i biomédica, porque permite acelerar el desarrollo de innovaciones y aprovechar de forma conjunta los recursos, las infraestructuras y el conocimiento de los centros públicos y de las empresas. Por ello no la considera un obstáculo para la eficiencia o la equidad, ni la limita a proyectos preclínicos, ya que también es esencial en los ensayos clínicos, ni propone evitarla en nombre de la independencia científica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b70") }, {"long_answer": "Para fomentar la colaboración entre los Organismos Públicos de Investigación, el sector académico y la industria farmacéutica, la Estrategia propone planes de matching, es decir, encuentros y herramientas para que los distintos agentes se conozcan mejor, identifiquen intereses comunes y faciliten la transferencia de conocimiento hacia proyectos de desarrollo. La exclusividad industrial sin acceso público, la reducción de proyectos conjuntos o la externalización completa de la investigación académica al sector privado irían en contra de esta colaboración equilibrada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b75") }, {"long_answer": "La futura Ley de Industria se plantea como un instrumento para promover ecosistemas industriales, favorecer la internacionalización de las empresas y proteger la base industrial estratégica del país, en la que se incluye el sector farmacéutico por su importancia para la autonomía sanitaria. No pretende privatizar el sector sanitario público, eliminar las ayudas financieras al sector ni reducir la inversión en tecnologías farmacéuticas avanzadas, medidas que debilitarían precisamente la capacidad industrial que la ley busca reforzar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b77") }, {"long_answer": "ENISA, Empresa Nacional de Innovación, es una entidad pública que concede préstamos participativos para financiar proyectos innovadores y de crecimiento de pymes y startups, incluidas las del sector farmacéutico y biotecnológico. Su papel en la Estrategia es facilitar el acceso a financiación a empresas jóvenes con potencial innovador. No impone restricciones regulatorias, no se dedica a facilitar fusiones de grandes empresas y tampoco gestiona la propiedad intelectual de los medicamentos, que corresponde a otros organismos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b7e") }, {"long_answer": "La Mesa de Trabajo para el aumento de las capacidades productivas incluirá a las principales organizaciones empresariales del sector farmacéutico, con el objetivo de identificar los recursos estratégicos y las capacidades de fabricación disponibles en España y detectar dónde es necesario reforzarlas. Excluir a los socios privados, contar solo con organismos internacionales o limitarse a los laboratorios de genéricos impediría tener una visión completa del tejido productivo, que es lo que se busca con este espacio de colaboración."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b80") }, {"long_answer": "La Estrategia de Industria y Autonomía Industrial definirá los sectores estratégicos, los retos a los que se enfrentan y las transformaciones que se desean alcanzar en un periodo determinado, sirviendo de marco para orientar las políticas industriales, entre ellas las del sector farmacéutico. No contempla excluir al sector farmacéutico del plan industrial, cerrar fábricas nacionales sin alternativas ni limitarse a atraer inversión extranjera sin control, ya que su finalidad es reforzar la autonomía y la capacidad industrial del país."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b82") }, {"long_answer": "Las medidas para mejorar el acceso a instrumentos financieros en el sector farmacéutico buscan mejorar la coordinación interna entre los organismos públicos que los gestionan y facilitar la financiación a startups y pymes, que son las que más dificultades tienen para financiar el desarrollo de sus innovaciones. Incrementar las barreras de acceso, concentrar los recursos solo en las grandes empresas o limitar el acceso a la financiación pública sería contrario al objetivo de impulsar la innovación en todo el tejido empresarial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b83") }, {"long_answer": "La Estrategia orientada a la regulación y a la autonomía estratégica busca crear un marco regulador que apoye la investigación y el desarrollo de tecnologías sanitarias y que permita que los avances lleguen a los pacientes de forma segura y ágil. Reducir la regulación para producir sin control comprometería la calidad y la seguridad, desentenderse de la innovación sanitaria en favor de lo comercial contradice el interés público, y fomentar exclusivamente la importación de medicamentos aumentaría la dependencia exterior que se quiere reducir.", "option_1": "Crear un marco regulador de apoyo a la investigación y a las tecnologías sanitarias que permita que lleguen a los pacientes"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b89") }, {"long_answer": "El Plan de acción para la prevención del suicidio señala que la conducta suicida no puede considerarse propiamente una enfermedad, sino una manifestación de un sufrimiento emocional profundo, en la que influyen factores psicológicos, sociales, biológicos y ambientales. Aunque se asocia con frecuencia a trastornos mentales, también puede darse en personas sin ellos, por lo que es falso que ocurra solo en personas sin enfermedad mental. No presenta siempre síntomas físicos claros y no se diagnostica únicamente en hospitales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b8f") }, {"long_answer": "En las personas mayores, la soledad no deseada y las pérdidas significativas, como la viudedad, la pérdida de autonomía, de salud o de roles sociales, son factores que aumentan el riesgo de suicidio, sobre todo cuando se acompañan de dolor crónico, dependencia o depresión. Por el contrario, la participación en grupos sociales activos actúa como factor protector, al igual que una buena salud física sin enfermedades crónicas. Un alto nivel educativo no se considera un factor que aumente el riesgo de suicidio en este grupo de edad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b92") }, {"long_answer": "Los familiares y personas allegadas tienen un papel clave en la prevención y el acompañamiento de la conducta suicida, por lo que el Plan recomienda que reciban formación para ofrecer apoyo emocional, reconocer las señales de alerta y disponer de un plan claro sobre cómo y dónde pedir ayuda en caso de crisis. Limitarse a dar información científica sin apoyo emocional, evitar la cercanía con la persona afectada o reducir su papel a los cuidados físicos no responde a las necesidades de quien está en riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b98") }, {"long_answer": "Uno de los objetivos del Plan de acción para la prevención del suicidio es mejorar la disponibilidad, la oportunidad y la calidad de la información sobre la conducta suicida, para conocer su magnitud real, identificar grupos de riesgo y planificar intervenciones eficaces. La desinformación, la reducción de la conciencia pública o el secretismo en torno a los pacientes con conducta suicida aumentan el estigma y dificultan la prevención, por lo que son contrarios a los objetivos del Plan, que promueve hablar del suicidio de forma responsable."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b9f") }, {"long_answer": "La prevención del suicidio requiere un enfoque multisectorial porque el suicidio es un fenómeno complejo en el que intervienen factores sanitarios, sociales, económicos, educativos y culturales, de modo que ningún sector por sí solo puede abordarlo. Por eso el Plan implica a sanidad, servicios sociales, educación, empleo, justicia, medios de comunicación y ciudadanía. La implicación de varios sectores no tiene como fin aumentar la burocracia ni limitar la participación ciudadana, y es falso que solo el sector salud pueda intervenir eficazmente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977baa") }, {"long_answer": "En niños menores de 2 meses, la guía recomienda realizar la antisepsia de la piel con clorhexidina al 2% en solución acuosa, dejándola secar completamente durante 3 a 5 minutos antes de la punción, ya que en esta edad la piel es más inmadura y permeable y los preparados alcohólicos aumentan el riesgo de irritación y quemaduras químicas. No se emplea la clorhexidina alcohólica como en adultos, la povidona yodada debe dejarse secar y no es la opción indicada en esta edad, y prescindir de la antisepsia aumentaría la contaminación de las muestras."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bac") }, {"long_answer": "Una vez realizada la antisepsia, no se debe volver a palpar el punto de punción, porque se contaminaría la zona y aumentaría el riesgo de falsos positivos en el hemocultivo. Si es imprescindible palpar, se debe utilizar un guante estéril nuevo o volver a desinfectar la piel antes de pinchar. Palpar con un guante ya usado sin desinfectar, hacerlo de forma sistemática para localizar mejor la vena o palpar sin guantes son prácticas incorrectas que comprometen la asepsia de la extracción."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bbd") }, {"long_answer": "Cuando se utiliza un sistema de extracción con vacío, se recomienda llenar primero el frasco aerobio, porque el aire que contiene el tubo de la palomilla pasaría al primer frasco y, si este fuese el anaerobio, se alteraría el ambiente necesario para el crecimiento de las bacterias anaerobias. Llenar primero el anaerobio solo se recomienda cuando la extracción se realiza con jeringa. El orden sí importa, por lo que no deben llenarse simultáneamente ni elegirse según las bacterias que se esperan encontrar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bbf") }, {"long_answer": "Al retirar la aguja tras la extracción de hemocultivos, la guía sugiere no colocar algodón ni otros materiales no estériles sobre la aguja en ese momento, porque podrían contaminar la muestra si todavía queda sangre por transferir a los frascos o si la aguja entra en contacto con ellos. La compresión del punto de punción debe hacerse después, con material adecuado. No es correcto considerar que ocluir con una gasa sea una práctica sin riesgo, ni que dependa del tamaño de la aguja o de que la extracción sea pediátrica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bc2") }, {"long_answer": "Dentro del laboratorio, el mejor método de almacenaje de los hemocultivos son los equipos automatizados de incubación y lectura continua, incluidos los equipos satélite cuando el laboratorio principal no está disponible de forma inmediata, ya que permiten incubar las muestras sin demora y detectar precozmente el crecimiento bacteriano. Los hemocultivos no deben refrigerarse a 4 ºC, porque se reduce la viabilidad de algunos microorganismos. Las estufas convencionales sin automatización y las cámaras anaerobias no son el método recomendado para su conservación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bc4") }, {"long_answer": "Un buen registro enfermero tras la extracción de hemocultivos debe incluir el nombre completo del paciente, la fecha, el número de historia clínica, la hora de la toma y el número de secuencia de las muestras, porque estos datos permiten identificar correctamente cada frasco e interpretar los resultados, por ejemplo al distinguir una bacteriemia verdadera de una contaminación. Registrar solo el nombre y la fecha resulta insuficiente, la hora y los síntomas no identifican al paciente y los datos del laboratorio o del médico solicitante no sustituyen a la identificación de las muestras."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bc5") }, {"long_answer": "Explicar al paciente la técnica y la finalidad del hemocultivo mejora su colaboración y su comprensión del procedimiento, reduce la ansiedad y favorece que permanezca quieto durante la extracción, lo que aumenta la seguridad y facilita mantener la técnica aséptica. La información no acorta necesariamente el procedimiento, no exime del uso de guantes ni de las medidas de asepsia y tampoco sustituye al consentimiento del paciente, sino que forma parte de él y del respeto a su autonomía."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bc7") }, {"long_answer": "Según el Plan Nacional contra el Radón, la presidencia del Comité encargado de su coordinación y seguimiento corresponde al Ministerio de Sanidad, en coherencia con el enfoque de protección de la salud pública del Plan, ya que la exposición al radón en interiores es la segunda causa de cáncer de pulmón tras el tabaco. El Consejo de Seguridad Nuclear, el Ministerio para la Transición Ecológica y el Reto Demográfico y la Federación Española de Municipios y Provincias tienen competencias relacionadas con la protección radiológica, el territorio o la gestión local, pero no ocupan la presidencia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bc8") }, {"long_answer": "De las fuentes naturales de radiación ionizante, la más relevante para la población general es el radón y sus descendientes, que suponen aproximadamente la mitad de la dosis media que recibe una persona. El radón es un gas que procede del uranio presente en el terreno y se acumula en el interior de los edificios, donde se inhala. La radiación cósmica, la radiación gamma exterior procedente del suelo y la radiación de los materiales de construcción contribuyen a la dosis, pero en una proporción claramente inferior."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bc9") }, {"long_answer": "El tabaquismo potencia de forma sinérgica el riesgo de cáncer de pulmón asociado a la exposición al radón, de modo que el riesgo de una persona fumadora expuesta es mucho mayor que la simple suma de ambos riesgos por separado. Por eso la mayoría de los cánceres de pulmón atribuibles al radón se producen en fumadores y exfumadores, y el Plan recomienda combinar la reducción de la exposición con la prevención del tabaquismo. Es falso que el tabaco no influya, que disminuya el efecto del radón o que eleve el umbral de riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bcd") }, {"long_answer": "El radón 222 es un gas noble radiactivo de origen natural, incoloro, inodoro e insípido, que procede de la desintegración del radio 226 en la cadena del uranio y es moderadamente soluble en agua, por lo que también puede encontrarse en aguas subterráneas. Al no tener color ni olor no puede detectarse con los sentidos y su presencia solo se conoce mediante mediciones, lo que justifica las campañas de medida en viviendas y lugares de trabajo. Por ello son incorrectas las opciones que lo describen como coloreado o con olor."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bdf") }, {"long_answer": "La reglamentación vigente sobre protección frente a la radiación natural, incorporada al ordenamiento español a partir de la Directiva 2013/59/Euratom, establece para la exposición externa a radiación gamma procedente de materiales de construcción en recintos cerrados un nivel de referencia de 1 mSv al año adicional a la exposición exterior. La cifra de 300 Bq/m³ corresponde al nivel de referencia de concentración de radón en el aire interior, no a la radiación gamma. Los valores de 6 y 10 mSv al año no son los establecidos para los materiales de construcción."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977be4") }, {"long_answer": "A nivel mundial, la principal razón por la que las enfermedades bucodentales no se tratan en etapas tempranas es que el tratamiento no es asequible para gran parte de la población y no está cubierto por la mayoría de los sistemas sanitarios, lo que retrasa la consulta hasta que aparecen dolor o complicaciones. Las enfermedades bucodentales, como la caries o la enfermedad periodontal, son de las más prevalentes del mundo, la caries inicial puede diagnosticarse sin gran dificultad técnica y el problema no es la falta de interés de los profesionales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977be7") }, {"long_answer": "Según el Plan de ampliación de la cartera de salud bucodental, el modelo mayoritario en las Comunidades Autónomas para la asistencia bucodental infantil es el modelo mixto, en el que la atención básica se presta tanto con medios públicos como mediante dentistas privados habilitados y financiados por el sistema, como ocurre en los programas tipo PADI. El modelo exclusivamente público existe en algunas comunidades, pero no es el mayoritario. El modelo de reintegro de gastos o el puramente privado sin financiación pública no son los predominantes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bee") }, {"long_answer": "La valoración económica del Plan de ampliación de la cartera común de servicios de salud bucodental estima un gasto total de 45.585.460 euros para homogeneizar y ampliar la cartera en todo el SNS, sumando el coste de las distintas prestaciones y grupos de población priorizados. Las cifras de 30.860.737, 8.406.463 y 686.332 euros son inferiores al total y pueden corresponder a partidas parciales o a colectivos concretos, pero no al gasto global estimado para la ampliación.", "option_1": "45.585.460 euros", "option_2": "30.860.737 euros", "option_3": "686.332 euros", "option_4": "8.406.463 euros"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bf0") }, {"long_answer": "En el modelo de provisión mixta de la atención bucodental infantil, la atención básica se retribuye mediante pago por capitación, es decir, una cantidad fija anual por cada niño asignado al dentista, con independencia de los actos que se le realicen, lo que incentiva la prevención. El pago por acto se reserva habitualmente para tratamientos especiales o complejos no incluidos en la atención básica. El pago a tanto alzado sin relación con el número de pacientes y el pago único anual fijo por dentista no son los mecanismos utilizados."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bf6") }, {"long_answer": "Para medir la cobertura en la población infantojuvenil se utiliza el número de niños atendidos en relación con la población diana, es decir, el porcentaje de niños y adolescentes con derecho a la prestación que efectivamente la han recibido. Este indicador refleja el grado de acceso real al servicio. El número total de citas o de tratamientos de ortodoncia completados mide actividad, no cobertura, y el número de dentistas públicos contratados es un indicador de recursos, no de la población atendida.", "option_4": "Número de dentistas públicos contratados"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bf7") }, {"long_answer": "La ampliación de la cartera común de servicios de salud bucodental prioriza a la población infantojuvenil de 0 a 14 años inclusive, a la que se ofrecen actuaciones preventivas, como selladores y aplicaciones de flúor, y tratamientos de la caries y de otros problemas de la dentición. Este grupo de edad se prioriza porque las intervenciones tempranas son más eficaces y evitan problemas en la edad adulta. Los rangos de 0 a 17 años, de 6 a 15 años y de 4 a 12 años no coinciden con la población priorizada en el Plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bf8") }, {"long_answer": "El plan de ampliación de la cartera de salud bucodental recomienda que la visita odontológica de la mujer embarazada se realice preferentemente durante el primer trimestre, para poder valorar el estado de salud oral, dar educación sanitaria precoz y tratar a tiempo los problemas que el embarazo puede agravar, como la gingivitis gestacional. Limitarla al tercer trimestre retrasa la prevención y coincide con la etapa de mayor incomodidad para la gestante. El momento del parto no es un contexto adecuado para una revisión dental. Tampoco es cierto que se desaconseje la atención odontológica en el embarazo: al contrario, la gestante es uno de los grupos prioritarios de la cartera común."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bf9") }, {"long_answer": "Para estimar el impacto presupuestario de incluir a las personas con enfermedades neuromusculares en la cartera bucodental, el plan utiliza una prevalencia estimada en adultos del 0,12%, un valor coherente con que se trate de un conjunto de enfermedades raras o poco frecuentes de base genética o adquirida. Cifras como el 0,5%, el 1,5% o el 5% sobrestimarían de forma notable la población afectada, propia de enfermedades frecuentes, y no corresponden al dato utilizado por el documento para calcular el número de personas beneficiarias y el coste de la ampliación de la cartera en este grupo prioritario."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bfc") }, {"long_answer": "El Grupo de Trabajo de Salud Bucodental se constituyó en 2021 en el seno del Consejo Interterritorial con el objetivo de definir una cartera común de servicios de salud bucodental homogénea y equitativa para los grupos prioritarios (población infantil y juvenil, embarazadas, personas con discapacidad, personas con procesos oncológicos de cabeza y cuello, entre otros), reduciendo las desigualdades entre comunidades autónomas. No pretendía impulsar un sistema privado de atención dental, sino reforzar la prestación pública. Tampoco su finalidad era recortar el gasto ni eliminar las carteras complementarias autonómicas, que pueden seguir existiendo por encima de la cartera común."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bfd") }, {"long_answer": "El análisis internacional incluido en el plan muestra que Suecia ofrece una cobertura pública prácticamente universal y gratuita de la atención bucodental para la población infantil y juvenil, con un modelo consolidado de odontología pública preventiva, lo que la sitúa como referente europeo. España, por el contrario, ha tenido históricamente una cobertura pública limitada y desigual entre comunidades, motivo precisamente del plan de ampliación. Italia y Grecia presentan modelos con mucha mayor dependencia del gasto privado y del pago directo por parte de las familias, por lo que no destacan por su cobertura universal en la infancia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bff") }, {"long_answer": "Para evaluar la efectividad de las medidas dirigidas a la gestante, el plan propone un indicador de cobertura: el número de embarazadas atendidas en las unidades de salud bucodental dividido entre la estimación de la población de embarazadas. Así se mide qué proporción de la población diana accede realmente a la prestación. Los implantes y las prótesis dentales no forman parte de la cartera de la embarazada, que se centra en la valoración, la educación sanitaria y el tratamiento preventivo y básico, por lo que no sirven como indicador. El número de urgencias odontológicas mide actividad asistencial aguda, pero no la cobertura del programa preventivo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c06") }, {"long_answer": "La concentración de radón en el interior de los edificios depende principalmente del contenido en uranio 238 del sustrato geológico, ya que el radón 222 es un gas radiactivo que procede de la cadena de desintegración de este elemento. Por eso las zonas con rocas graníticas, ricas en uranio, presentan los niveles más altos. El plomo no genera radón: de hecho, es uno de los productos finales estables de la cadena. El tipo de roca superficial influye solo en la medida en que contiene uranio y condiciona la permeabilidad, y el agua subterránea puede transportar radón, pero ninguno de estos dos es el factor determinante principal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c0e") }, {"option_3": "Existe un efecto sinérgico (submultiplicativo) que incrementa significativamente el riesgo en fumadores", "long_answer": "El Libro del Radón recoge que entre el tabaco y la exposición a radón existe un efecto sinérgico de tipo submultiplicativo: el riesgo combinado es mayor que la suma de ambos riesgos, aunque algo menor que su producto. Esto hace que en los fumadores la exposición a radón incremente de forma muy importante el riesgo absoluto de cáncer de pulmón, y que la mayor parte de los cánceres atribuibles al radón se produzcan en fumadores o exfumadores. Es falso que no exista interacción, que el radón afecte solo a no fumadores (en quienes es la primera causa de cáncer de pulmón, pero no la única población afectada) o que reduzca el riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c12") }, {"long_answer": "Galicia es la comunidad autónoma con mayor porcentaje de su territorio clasificado como zona de actuación prioritaria por radón, debido a la abundancia de rocas graníticas ricas en uranio en su sustrato geológico. Le siguen en importancia otras zonas con sustrato granítico como áreas de Extremadura, de Castilla y León o de la sierra de Madrid, pero en proporción de territorio afectado ninguna alcanza a Galicia. Madrid y Extremadura tienen zonas concretas con niveles elevados, sin llegar a esa extensión, y Cataluña presenta un porcentaje de territorio afectado mucho menor."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c19") }, {"question": "Según la consulta a expertos recogida en el Libro del Radón, ¿cuál es la situación en la Unión Europea respecto a los protocolos de vigilancia sanitaria de los trabajadores expuestos a radón?", "long_answer": "La consulta a expertos realizada para el Libro del Radón puso de manifiesto que en la Unión Europea no existe ningún protocolo específico y obligatorio de vigilancia sanitaria para los trabajadores expuestos a radón; las actuaciones se centran en la medición, la reducción de la exposición y la protección radiológica, y la vigilancia de la salud se aplica de forma heterogénea. Por tanto, no hay un protocolo común europeo obligatorio. Tampoco se recomienda aumentar la frecuencia de radiografías de tórax, que no son útiles como cribado y suponen radiación adicional, ni se aplica sin más el protocolo de los trabajadores expuestos a radiaciones en instalaciones nucleares."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c1c") }, {"long_answer": "En trabajadores expuestos a radón que fuman, la medida de prevención primaria más eficaz es la deshabituación tabáquica, facilitada por los empleadores y mediante programas específicos, porque el tabaco y el radón actúan de forma sinérgica sobre el riesgo de cáncer de pulmón y abandonar el tabaco reduce de forma muy importante ese riesgo combinado. Las mascarillas no son la medida de elección frente a un gas presente en el ambiente; la prioridad es reducir la concentración de radón en el lugar de trabajo. La tomografía de baja dosis es una medida de cribado, es decir, de prevención secundaria, y la reducción de jornada no es la recomendación principal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c1f") }, {"long_answer": "La revisión sistemática del Libro del Radón no identificó ningún estudio que evaluara los beneficios o los riesgos de programas de vigilancia sanitaria o de cribado específicos para trabajadores expuestos a radón; las recomendaciones se basan, por tanto, en la extrapolación de la evidencia sobre cribado de cáncer de pulmón en población de alto riesgo y en el consenso de expertos. No es cierto que exista abundante evidencia a favor de un cribado anual, ni que haya estudios contradictorios que impidan recomendar, ni que se haya demostrado un beneficio específico en exfumadores: simplemente, la evidencia directa en este colectivo no existe."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c25") }, {"long_answer": "El documento propone que la vigilancia específica de síntomas y signos precoces de cáncer de pulmón en trabajadores expuestos a radón la realicen neumólogos y personal facultativo con entrenamiento específico, ya que requiere interpretar de forma experta la clínica, las pruebas de imagen y los hallazgos sospechosos, y decidir el circuito diagnóstico. La enfermería general colabora en la educación sanitaria, la deshabituación tabáquica y el seguimiento, pero no es la responsable de esta vigilancia clínica especializada. Tampoco se propone que la asuman médicos sin formación específica en este riesgo, ni los técnicos en radiología, cuya función es la realización técnica de las pruebas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c2a") }, {"long_answer": "La desfibrilación de doble secuencia está indicada en la parada cardiorrespiratoria con ritmo desfibrilable (fibrilación ventricular o taquicardia ventricular sin pulso) que persiste o es refractaria tras tres desfibrilaciones estándar correctamente realizadas. En estos casos se utilizan dos monitores desfibriladores para administrar dos descargas casi consecutivas con distinto vector. No está indicada en cualquier parada ni en los ritmos no desfibrilables (asistolia o actividad eléctrica sin pulso), en los que la descarga no aporta beneficio. Además, precisa disponer de dos monitores desfibriladores, por lo que no puede plantearse cuando no se dispone de ellos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c2b") }, {"long_answer": "En la desfibrilación de doble secuencia las dos descargas deben administrarse de forma secuencial y muy próxima, con un intervalo inferior a un segundo entre ambas, de manera que actúen sobre el miocardio prácticamente en el mismo periodo refractario y con dos vectores distintos. Intervalos de tres o cinco segundos ya no se consideran doble secuencia, sino dos descargas independientes, y pierden el efecto buscado. Esperar dos minutos correspondería al intervalo habitual entre ciclos de RCP y análisis del ritmo, no al tiempo entre las dos descargas de la técnica. Tampoco se recomienda la descarga exactamente simultánea por el riesgo de dañar los equipos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c2e") }, {"long_answer": "Durante las tres primeras desfibrilaciones estándar se utiliza la posición anterolateral habitual: un parche bajo la clavícula derecha, a la derecha del esternón, y el otro en la línea axilar del lado izquierdo a la altura del quinto espacio intercostal, sobre el ápex cardíaco. Así la corriente atraviesa la mayor masa ventricular posible. Si la fibrilación persiste, en la doble secuencia se añade un segundo juego de parches en posición anteroposterior. Colocar un electrodo en la espalda baja, en las extremidades o en la línea media esternal y lateral derecha no sitúa el corazón entre ambos parches y reduce la eficacia de la descarga."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c32") }, {"long_answer": "El protocolo establece que una sola persona maneje ambos monitores desfibriladores y realice las dos descargas de forma secuencial. De este modo se controla mejor el intervalo entre descargas, que debe ser inferior a un segundo, se evitan descoordinaciones y se garantiza la seguridad del resto del equipo, que debe estar separado del paciente. Que dos personas pulsen cada una un monitor dificulta la sincronización y aumenta el riesgo de error. No es una función reservada exclusivamente al médico, sino a la persona del equipo designada y entrenada, y tampoco corresponde al personal de soporte vital básico, ya que exige manejo de monitores manuales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c37") }, {"long_answer": "La persona que maneja los desfibriladores debe anunciar en voz alta la doble descarga para asegurar que nadie toca al paciente, pulsar el primer monitor y, a continuación, anunciar y pulsar el segundo, con una diferencia aproximada de un segundo. Esta secuencia combina seguridad y eficacia. Esperar diez segundos entre descargas anula el efecto de la doble secuencia. Pulsar ambos de forma estrictamente simultánea no es lo recomendado, porque puede dañar los equipos y no es lo que define la técnica secuencial. Nunca debe omitirse el aviso previo, ya que es una medida esencial de seguridad para el equipo que atiende la parada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c39") }, {"long_answer": "Comunicar la parada cardiorrespiratoria a la Central de Comunicaciones antes de plantear la doble secuencia permite activar precozmente los recursos necesarios para disponer de un segundo monitor desfibrilador, que suele llegar con otra unidad asistencial, ya que la técnica exige dos equipos. Si no se solicita a tiempo, cuando la fibrilación resulte refractaria no habrá segundo monitor disponible. No se trata de pedir fármacos específicos, porque la técnica no los requiere, ni de comunicar datos estadísticos, que pueden registrarse después. Tampoco hace falta una autorización médica para administrar descargas múltiples, ya que la indicación está protocolizada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c48") }, {"long_answer": "El objetivo de la inmunización con nirsevimab es prevenir la enfermedad de las vías respiratorias inferiores causada por el virus respiratorio sincitial en neonatos y lactantes durante su primera temporada de VRS, y en determinados niños con factores de riesgo hasta su segunda temporada, reduciendo bronquiolitis, hospitalizaciones e ingresos en UCI. No está indicado en adultos mayores, para quienes existen vacunas específicas. Tampoco es un tratamiento de la bronquiolitis ya establecida, sino un anticuerpo monoclonal de uso profiláctico. Aunque pueda tener efectos indirectos, su finalidad no es reducir la transmisión comunitaria en la población general, sino proteger al lactante inmunizado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c4a") }, {"long_answer": "Las recomendaciones para la temporada 2024-2025 incluyen como población diana a los prematuros de menos de 35 semanas de edad gestacional, también los menores de 29 semanas, que deben recibir nirsevimab antes de cumplir los 12 meses de edad si no lo recibieron al nacer o al inicio de la temporada. Los prematuros de 35 semanas o más se inmunizan como el resto de lactantes según su fecha de nacimiento, no por su prematuridad. No se restringe a quienes tienen displasia broncopulmonar, que es otro grupo de riesgo independiente. Y la indicación no depende de haber nacido después de la temporada, sino de la edad gestacional."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c4f") }, {"long_answer": "Durante la primera temporada de implantación, la 2023-2024, la cobertura de inmunización con nirsevimab en los recién nacidos durante la temporada alcanzó aproximadamente el 92%, una cifra muy elevada que se asoció a una reducción importante de las hospitalizaciones por VRS en menores de seis meses. Este dato sirvió de base para mantener y ampliar la estrategia en la temporada siguiente. Las cifras del 50% o del 75% infravaloran claramente la aceptación lograda. El 88% se aproxima, pero no es el dato de cobertura en recién nacidos durante la temporada que recoge el documento de actualización."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c54") }, {"long_answer": "En los lactantes nacidos durante la temporada de VRS, de octubre a marzo, se recomienda administrar nirsevimab de forma precoz, preferiblemente en las primeras 24 a 48 horas de vida, aprovechando la estancia en la maternidad, porque el riesgo de enfermedad grave es máximo en los primeros meses y en plena circulación del virus. Esperar a los seis meses los dejaría desprotegidos en el periodo más vulnerable. No administrarlo contradice la estrategia, ya que son precisamente la población diana prioritaria. Y como se trata de una medida preventiva, no debe reservarse para cuando aparezcan síntomas, momento en el que ya no evita la infección."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c57") }, {"long_answer": "La estrategia para la temporada 2024-2025 mantiene como medida principal la inmunización pasiva del lactante con nirsevimab, que se recomienda independientemente de que la madre haya recibido o no la vacuna frente al VRS durante el embarazo. La vacuna materna no se incluyó como estrategia poblacional del SNS en esa temporada, y por eso no se plantea sustituir la inmunización infantil por la vacunación de la gestante. Tampoco se recomienda la vacunación materna limitada a casos de alto riesgo como alternativa al anticuerpo monoclonal. Con ello se busca una protección homogénea de todos los lactantes de la población diana."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c5d") }, {"long_answer": "Los lactantes de la población diana nacidos fuera de la temporada de VRS, entre abril y septiembre, deben recibir nirsevimab al comienzo de la temporada, idealmente en octubre, de forma que tengan niveles protectores de anticuerpos durante todo el periodo de máxima circulación del virus. Esperar a que cumplan seis meses no tiene sentido, ya que la indicación se establece por la temporada y no por la edad. No administrarlo los dejaría sin protección en su primera temporada. Tampoco se limita a los que ingresan en UCI, porque el objetivo es precisamente prevenir esas formas graves de la enfermedad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c5f") }, {"long_answer": "Nirsevimab es un anticuerpo monoclonal de semivida prolongada, diseñado para que una única dosis proporcione protección durante al menos cinco meses, es decir, una temporada completa de VRS de otoño e invierno. Esta característica es la que permite administrarlo una sola vez al nacer o al inicio de la temporada. Una protección de solo un mes o de dos semanas correspondería a anticuerpos de semivida corta, como palivizumab, que requiere dosis mensuales. Una protección de dos años no es real: en los niños con riesgo que siguen siendo vulnerables en su segunda temporada se administra una nueva dosis antes de que comience."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c62") }, {"long_answer": "En la primera temporada de VRS la dosis de nirsevimab depende del peso: los lactantes de menos de 5 kg reciben 50 mg por vía intramuscular y los de 5 kg o más reciben 100 mg. Por tanto, un lactante de menos de 5 kg debe recibir 50 mg. La dosis de 100 mg corresponde a los lactantes de 5 kg o más en su primera temporada, o a los niños de menos de 10 kg en su segunda temporada. La de 200 mg, en dos inyecciones de 100 mg, es la de los niños de 10 kg o más en su segunda temporada. La dosis de 25 mg no está contemplada en las recomendaciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c63") }, {"question": "En un lactante en su primera temporada de VRS que se somete a cirugía cardíaca con circulación extracorpórea cuando han pasado más de 90 días desde que recibió nirsevimab, ¿qué dosis adicional se recomienda?", "long_answer": "Cuando un lactante en su primera temporada se somete a cirugía cardíaca con circulación extracorpórea, se pierde parte del anticuerpo circulante, por lo que se recomienda una dosis adicional en cuanto esté estable. Si han transcurrido más de 90 días desde la primera dosis, la dosis adicional es de 50 mg independientemente del peso, ya que los niveles residuales son menores y se busca completar la protección hasta el final de la temporada. Si la cirugía ocurre dentro de los 90 días, la dosis adicional se ajusta al peso (50 o 100 mg). La de 200 mg corresponde a la segunda temporada, y no administrar dosis adicional dejaría al lactante insuficientemente protegido."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c67") }, {"long_answer": "El Marco Estratégico para los Cuidados de Enfermería 2025-2027 adopta un concepto amplio de cuidado profesional: el conjunto de actuaciones que realizan enfermeras y enfermeros para promover la vida y la salud y apoyar a las personas con carencia de autonomía, ejercido con autonomía y responsabilidad propias. Esta definición reconoce la enfermería como disciplina con cuerpo de conocimiento propio. No se limita al tratamiento de enfermedades, ya que incluye promoción, prevención y acompañamiento. Tampoco reduce el cuidado a ayudas basadas en pautas médicas sin autonomía, ni lo restringe al hospital bajo supervisión médica, ya que se presta en todos los ámbitos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c68") }, {"question": "Según la Ley de Ordenación de las Profesiones Sanitarias (LOPS), ¿qué competencias corresponden a los Diplomados universitarios en Enfermería?", "long_answer": "El artículo 7 de la Ley 44/2003, de Ordenación de las Profesiones Sanitarias, atribuye a los Diplomados universitarios en Enfermería la dirección, evaluación y prestación de los cuidados de enfermería orientados a la promoción, mantenimiento y recuperación de la salud, así como a la prevención de enfermedades y discapacidades. Esta definición reconoce la autonomía de la profesión en su ámbito de competencia. Por ello es incorrecto afirmar que sus funciones sean exclusivamente asistenciales bajo orden médica, que se limiten a la gestión de servicios sin atención directa o que se reduzcan a la investigación y la docencia, que son funciones complementarias de la enfermera."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a87") }, {"long_answer": "El Plan de Acción de Atención Primaria y Comunitaria 2025-2027 establece que, durante el primer trimestre de 2025, se consensúe con los actores participantes la metodología de seguimiento y evaluación, de manera que el sistema de indicadores y los responsables de su recogida queden definidos desde el principio y la evaluación sea compartida. El plan no propone simplificarlo eliminando indicadores complejos, ni externalizar la evaluación a empresas privadas, ya que el seguimiento se realiza en el marco del Ministerio de Sanidad y las comunidades autónomas. Ignorar los indicadores de accesibilidad sería contrario al propio plan, que considera la accesibilidad una de sus prioridades."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a8a") }, {"long_answer": "El plan propone desarrollar un modelo común en el SNS para calcular las necesidades de recursos humanos en Atención Primaria que tenga en cuenta la morbilidad atendida, los resultados en salud y las características sociodemográficas de la población, superando el criterio clásico basado solo en el número de tarjetas sanitarias. Así se pretende asignar profesionales según la complejidad y las necesidades reales. No se basa en el nivel económico de los profesionales de cada región, ni únicamente en la densidad de población, que no refleja la carga asistencial, ni en la capacidad tecnológica disponible, que es un recurso complementario pero no determina las plantillas necesarias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a8c") }, {"long_answer": "En su línea 3, el plan contempla renovar las infraestructuras y el equipamiento de los centros de Atención Primaria de forma acorde con la actualización de la cartera de servicios que realicen las comunidades autónomas, con el fin de aumentar la capacidad resolutiva de los equipos y permitir incorporar nuevas pruebas y procedimientos en el propio centro de salud. No se plantea cancelar las actualizaciones, que son necesarias para mantener la calidad asistencial, ni trasladar a los profesionales a nuevos centros urbanos, lo que perjudicaría la accesibilidad en el medio rural. Tampoco se limita al equipamiento tecnológico dejando de lado los edificios."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a93") }, {"question": "Según los datos del Plan de Acción de Atención Primaria y Comunitaria, ¿cuántas consultas anuales se atienden en los servicios de urgencias de Atención Primaria?", "long_answer": "Según los datos de actividad recogidos en el plan, los servicios de urgencias de Atención Primaria atienden alrededor de 33,6 millones de consultas al año (33.608.094), una cifra muy inferior a la de la actividad ordinaria de los centros de salud en medicina de familia, pediatría y enfermería. Las cifras de 385, 213 o 144 millones son órdenes de magnitud propios de la actividad ordinaria programada y a demanda, no de la atención urgente, que representa solo una parte menor del total de consultas de Atención Primaria. Conocer este volumen ayuda a dimensionar los dispositivos de atención continuada y urgente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a97") }, {"long_answer": "Los datos del plan muestran que la mayoría de las personas con problemas de salud mental son atendidas en Atención Primaria, y que el profesional que con más frecuencia las atiende es el médico de familia, puerta de entrada al sistema y responsable del seguimiento de los trastornos mentales comunes como la ansiedad o la depresión leve. Por eso el plan insiste en reforzar la colaboración entre Atención Primaria y Salud Mental. Psicólogos, psiquiatras y enfermeras especialistas en salud mental atienden sobre todo los casos derivados o de mayor complejidad, por lo que, en volumen de pacientes atendidos, no superan al médico de familia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a9c") }, {"long_answer": "El plan destaca la potenciación de la figura del administrativo de salud, o gestor sanitario, como la medida que ha permitido optimizar más del 75% de los procedimientos administrativos en Atención Primaria, liberando tiempo de médicos y enfermeras para tareas clínicas al asumir gestiones como citas, informes, bajas o derivaciones. La digitalización es un apoyo importante, pero no es la medida a la que el plan atribuye este resultado. Contratar exclusivamente médicos no resuelve la carga burocrática, sino que la mantiene en profesionales clínicos, y reducir las consultas no es una medida de optimización administrativa, sino que limitaría la accesibilidad de la población."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aa3") }, {"long_answer": "La línea 1 del plan incluye medidas para fomentar la longitudinalidad, es decir, que cada persona sea atendida de forma continuada por el mismo médico de familia y la misma enfermera a lo largo del tiempo, lo que se asocia a menos hospitalizaciones, menos urgencias, mejor control de las enfermedades crónicas e incluso menor mortalidad. Incentivar la rotación frecuente de profesionales o eliminar el seguimiento longitudinal irían en dirección contraria, rompiendo la relación de confianza y el conocimiento acumulado del paciente. Centralizar la atención en la Atención Especializada contradice el enfoque del plan, que sitúa a la Atención Primaria como eje del sistema."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aa6") }, {"long_answer": "Para asegurar la equidad en el acceso, el plan propone adecuar las modalidades de atención (presencial, telefónica, telemática y domiciliaria) a las necesidades de la población y, al mismo tiempo, reducir la brecha digital en los grupos vulnerables, como personas mayores o en situación de exclusión, para que la atención no presencial no genere nuevas desigualdades. Implantar exclusivamente la atención presencial en centros urbanos excluiría a la población rural y renunciaría a las ventajas de la no presencial. Eliminar todas las modalidades no presenciales iría contra la accesibilidad, y limitar el acceso de las personas mayores sería discriminatorio y contrario a la equidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ab0") }, {"option_4": "No se desglosa ninguna información sobre las personas", "long_answer": "En el seguimiento de las convocatorias competitivas y no competitivas específicas para investigación en Atención Primaria, el plan establece que se recoja la información de las personas convocadas desglosada por sexo y por tipo de convocatoria, lo que permite analizar la perspectiva de género en el acceso a la financiación y comparar ambos tipos de convocatoria. No se consideran solo las competitivas ni solo las no competitivas, ya que la medida incluye ambas modalidades para favorecer tanto la investigación consolidada como el inicio de nuevos investigadores. Y afirmar que no se desglosa información contradice el indicador definido en el propio plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ab3") }, {"long_answer": "En el programa de intensificación de la actividad investigadora de la Acción Estratégica en Salud, el indicador definido es la tasa de éxito anual, calculada como la relación entre el número de profesionales de Atención Primaria a los que se concede financiación y el número de los que la solicitan. Este indicador permite valorar si la convocatoria facilita realmente que los profesionales liberen tiempo asistencial para investigar. El número de solicitudes ignoradas, el número de proyectos no competitivos o el porcentaje de proyectos rechazados sin evaluación no son indicadores contemplados ni reflejan el éxito de la convocatoria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ab5") }, {"long_answer": "El plan establece el seguimiento anual del porcentaje de investigadores de Atención Primaria integrados en los Institutos de Investigación Sanitaria y lo vincula con la acreditación de estos institutos por el Instituto de Salud Carlos III, de modo que la incorporación de profesionales de primaria se convierta en un criterio para mantener dicha acreditación. Con ello se incentiva que los institutos, tradicionalmente muy hospitalarios, integren grupos de Atención Primaria. No se pretende asignar fondos exclusivamente a hospitales, ni reducir el apoyo a la investigación en primaria, ni eliminar su componente investigador, que es justo lo que el plan quiere reforzar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ab7") }, {"long_answer": "Para valorar la internacionalización de la investigación en Atención Primaria, el plan monitoriza el porcentaje de proyectos europeos concedidos que cuentan con profesionales de Atención Primaria en sus equipos de investigación. Este indicador mide de forma directa la participación efectiva de primaria en convocatorias competitivas internacionales. El número de proyectos presentados sin inclusión de profesionales de primaria no informa sobre su participación, el porcentaje de proyectos rechazados por falta de equipos multidisciplinares no es un indicador definido y el número de colaboraciones no europeas no corresponde al ámbito al que se refiere la medida."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ab8") }, {"long_answer": "El mapa de situación de la I+D en Atención Primaria no se limita a datos de producción o económicos, sino que incluye información sobre los recursos de apoyo metodológico disponibles y las infraestructuras de investigación existentes en los centros de salud, junto con los grupos y la actividad investigadora. Esto permite detectar dónde faltan unidades de apoyo y planificar recursos. Por tanto, es incorrecto que se limite a datos económicos sin análisis metodológico, que incluya solo datos hospitalarios, ya que su objeto es precisamente la Atención Primaria, o que ignore los grupos de investigación reconocidos, que forman parte de la información recogida."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ab9") }, {"long_answer": "El plan prevé convocatorias específicas para Atención Primaria tanto competitivas como no competitivas, acompañadas de apoyo metodológico, con el fin de favorecer que los profesionales se inicien en la investigación y que los grupos emergentes puedan consolidarse. Las no competitivas facilitan el primer contacto con la investigación y las competitivas impulsan proyectos de mayor envergadura. Por ello es incorrecto que solo se contemplen convocatorias no competitivas, que se trate de convocatorias externas sin apoyo metodológico, cuando este apoyo es un elemento clave de la medida, o que se abran exclusivamente a hospitales universitarios, lo que excluiría a la propia Atención Primaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ac2") }, {"long_answer": "El plan establece un calendario en dos fases para las modalidades de atención no presencial: antes de 2026, las comunidades autónomas deben presentar los resultados de la evaluación de su implantación, y antes de 2027 deben incorporarse criterios comunes consensuados en el SNS a partir de esa evaluación. Así se garantiza que la atención telefónica y telemática se ordene con criterios de calidad y equidad. No se trata de un plazo en 2028 sin seguimiento previo ni de 2030 sin indicadores, ya que el plan tiene horizonte 2025-2027, y afirmar que no hay plazo claro contradice los hitos fijados en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ac4") }, {"long_answer": "El plan fija como resultado esperado que el 100% de las comunidades autónomas hayan publicado su Estrategia de Salud Comunitaria antes de diciembre de 2027, coincidiendo con el final de su periodo de vigencia, 2025-2027. Así se da un margen suficiente para que cada comunidad elabore su estrategia con participación de profesionales, ayuntamientos y ciudadanía. Diciembre de 2025 y de 2026 son hitos intermedios demasiado tempranos para exigir a todas las comunidades la publicación, y diciembre de 2028 queda fuera del horizonte temporal del plan, por lo que no puede ser el plazo establecido."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aca") }, {"long_answer": "La actualización anual del mapa de situación de la I+D en Atención Primaria tiene como objetivo aportar información que permita una planificación eficiente de los recursos de investigación y dar visibilidad a la actividad investigadora que se realiza en primaria, a menudo poco reconocida. Con ello se identifican grupos, líneas y necesidades de apoyo. La evaluación de la brecha digital en colectivos vulnerables y el seguimiento del acceso a la atención no presencial pertenecen a la línea de accesibilidad del plan, y la medición de la satisfacción del paciente es un indicador de calidad percibida, no el objetivo de este mapa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ad0") }, {"long_answer": "En la línea de accesibilidad, el plan prevé evaluar antes de 2026 la implantación de la modalidad de atención no presencial en las comunidades autónomas, es decir, cómo se están utilizando la consulta telefónica y la telemática, con qué criterios y con qué resultados, como paso previo para consensuar criterios comunes. La satisfacción del paciente en Atención Primaria es un aspecto distinto de calidad percibida. La formación de profesionales en salud comunitaria corresponde a la línea de orientación comunitaria, y la actualización de la cartera básica común es otra medida del plan, sin relación directa con esta evaluación de la atención no presencial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ad1") }, {"long_answer": "Para la atención sanitaria a personas sin hogar, el plan fija como resultado esperado en 2027 que al menos el 50% de las comunidades autónomas hayan puesto en marcha al menos el 30% de las recomendaciones consensuadas, una meta realista que mide la implantación progresiva. Erradicar el sinhogarismo en el 100% de las comunidades excede las competencias sanitarias y no es un objetivo medible del plan. Prestar la atención exclusivamente mediante teleconsulta sería contraproducente en una población con importantes barreras de acceso digital, y la publicación semestral de un informe sobre sinhogarismo no es el indicador definido en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ad5") }, {"long_answer": "El plan prevé incluir en la Historia Clínica Digital Interoperable del SNS un conjunto mínimo consensuado de condicionantes sociales y del contexto familiar, como la situación de convivencia, las personas cuidadoras o la situación socioeconómica, ya que estos determinantes influyen en la salud y deben estar accesibles para todos los profesionales que atienden a la persona. Limitarla a indicadores clínicos, a datos administrativos y económicos o a datos biométricos y constantes vitales no responde al objetivo de la medida, que es incorporar la dimensión social y comunitaria a la información clínica compartida entre niveles asistenciales y comunidades autónomas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ad6") }, {"long_answer": "El Plan de Capacitación en Salud Comunitaria prevé una formación en formato de cursos online, acreditados y gratuitos para los profesionales de Atención Primaria, con el fin de llegar a todos los equipos del territorio, facilitar la conciliación con la actividad asistencial y garantizar el reconocimiento de la formación. No se dirige exclusivamente a médicos, ya que la salud comunitaria es una tarea de todo el equipo, con un papel destacado de la enfermería. Los talleres presenciales de pago y los cursos de especialización en universidades privadas no se corresponden con la formación prevista, que es pública, accesible y gratuita."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ade") }, {"long_answer": "El indicador de proceso de la formación en salud comunitaria es el número de profesionales formados por las comunidades autónomas y por el Ministerio de Sanidad, desglosado por nivel y modalidad de formación, ya que permite conocer el alcance real del Plan de Capacitación y su distribución territorial. El porcentaje de pacientes que usan teleconsulta corresponde a la línea de accesibilidad, el número de proyectos de I+D aprobados pertenece a la línea de investigación y el porcentaje de herramientas digitales usadas en Atención Primaria se relaciona con la transformación digital, por lo que ninguno de ellos mide la formación en salud comunitaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ae1") }, {"long_answer": "La acción prevista para lograr un modelo común de cálculo de necesidades de recursos humanos en Atención Primaria consiste en basarlo en la morbilidad atendida, los resultados en salud y las características sociodemográficas de la población, de forma que las plantillas se ajusten a la carga de trabajo y la complejidad reales de cada zona. Fijar un número de profesionales igual con independencia del territorio ignoraría las diferencias de envejecimiento, dispersión o vulnerabilidad. Asignar los recursos por criterio político carece de base técnica, y determinar las necesidades por los años de experiencia de los profesionales no guarda relación con las necesidades de salud de la población."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ae9") }, {"long_answer": "En el sistema de indicadores del plan, el indicador 11 es el que recoge el número de centros de salud acreditados por la Iniciativa para la Humanización de la Asistencia al Nacimiento y la Lactancia (IHAN) en cada comunidad autónoma, en relación con la medida de promoción y apoyo a la lactancia materna desde Atención Primaria, incluida en el abordaje de la obesidad infantil. La acreditación IHAN garantiza que el centro aplica prácticas basadas en la evidencia para proteger, promover y apoyar la lactancia. Los indicadores 1, 7 y 12 corresponden a otras medidas del plan y no miden la acreditación IHAN de los centros de salud."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977afb") }, {"long_answer": "El plan impulsa la atención familiar en el hogar desde Atención Primaria con el objetivo de proporcionar cuidados adecuados en el domicilio a las personas que lo necesitan, como pacientes inmovilizados, con enfermedades crónicas avanzadas o al final de la vida, y de garantizar la longitudinalidad de la atención por su equipo de referencia, médico de familia y enfermera. Reducir las visitas domiciliarias y centralizar la atención en los hospitales, o limitarla a equipos hospitalarios, iría en contra de ese objetivo. Disminuir el papel de la enfermería sería contrario al plan, que reconoce a la enfermera como figura clave en la atención domiciliaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b03") }, {"long_answer": "La comunicación bidireccional entre las farmacias comunitarias y los centros de salud o consultorios tiene como finalidad mejorar el uso racional y seguro de los medicamentos mediante la coordinación entre farmacéuticos, médicos y enfermeras, por ejemplo para comunicar problemas relacionados con la medicación, interacciones, duplicidades o dificultades de adherencia, especialmente en pacientes polimedicados. No persigue aumentar la venta de medicamentos sin receta, ni reducir la comunicación entre profesionales, que es justo lo que se quiere reforzar. Tampoco pretende centralizar la prescripción en los hospitales, lo que alejaría la atención farmacoterapéutica de la comunidad y de la Atención Primaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b08") }, {"long_answer": "Entre los recursos de apoyo digital, el plan menciona el Plan de Transformación Digital de Atención Primaria, que incluye herramientas como cuadros de mando para la gestión y la evaluación de la actividad, y la teleconsulta como modalidad de atención, con el objetivo de mejorar la eficiencia, la accesibilidad y la gestión de los equipos. No se trata de una aplicación móvil exclusiva para pacientes crónicos, ni de un software privativo sin acceso público, ya que se basa en la interoperabilidad dentro del SNS. Tampoco es un sistema de gestión solo para hospitales, puesto que va dirigido específicamente a la Atención Primaria."});
print(`\nParte terminada: ${ok} corregidas, ${del} borradas, ${warn} avisos.`);
